/**
 * Execution phase in the Loki workflow
 */
export type Phase =
    | 'idle'
    | 'initializing'
    | 'planning'
    | 'implementing'
    | 'testing'
    | 'reviewing'
    | 'deploying'
    | 'completed'
    | 'failed'
    | 'paused';

/**
 * Task status within a session
 */
export type TaskStatus =
    | 'pending'
    | 'in_progress'
    | 'completed'
    | 'failed'
    | 'skipped';

/**
 * Session state (matches dashboard/server.py)
 */
export type SessionState =
    | 'running'
    | 'paused'
    | 'stopping'
    | 'stopped'
    | 'completed'
    | 'failed';

/**
 * Provider type for multi-provider support
 */
export type Provider = 'claude' | 'codex' | 'gemini';

/**
 * A task within the Loki workflow
 */
export interface Task {
    id: string;
    title: string;
    description: string;
    status: TaskStatus;
    phase: Phase;
    startedAt?: string;
    completedAt?: string;
    error?: string;
    output?: string;
    subtasks?: Task[];
}

/**
 * Current session status (matches server response format)
 * Server returns: { state, pid, statusText, currentPhase, currentTask, pendingTasks, provider, version, lokiDir, timestamp }
 */
export interface SessionStatus {
    state: 'running' | 'paused' | 'stopping' | 'stopped';
    pid: number | null;
    statusText: string;
    currentPhase: string;
    currentTask: string;
    pendingTasks: number;
    provider: Provider;
    version: string;
    lokiDir: string;
    timestamp: string;
}

