    path.join(os.homedir(), 'bin/loki'),
    // Windows locations
    path.join(os.homedir(), 'AppData/Roaming/npm/loki.cmd'),
    'C:/Program Files/nodejs/loki.cmd',
];

/**
 * Version info returned by getLokiVersion
 */
export interface VersionInfo {
    version: string;
    fullOutput: string;
}

/**
 * Detection result with path and version
 */
export interface DetectionResult {
    found: boolean;
    path: string | null;
    version: string | null;
    source: 'path' | 'common' | 'not_found';
}

/**
 * Check if a file exists and is executable
 */
async function isExecutable(filePath: string): Promise<boolean> {
    try {
        await access(filePath, constants.X_OK);
        return true;
    } catch {
        return false;
    }
}

/**
 * Try to find loki using the which/where command
 */
async function findInPath(): Promise<string | null> {
    const command = process.platform === 'win32' ? 'where' : 'which';

    try {
        const { stdout } = await execAsync(`${command} loki`, {
            timeout: 5000,
            env: { ...process.env },
        });

        const lokiPath = stdout.trim().split('\n')[0];
        if (lokiPath && await isExecutable(lokiPath)) {
            return lokiPath;
        }
    } catch {
        // Command not found or error
    }

    return null;
}

/**
 * Try to find loki in common installation locations
 */
async function findInCommonLocations(): Promise<string | null> {
    for (const location of COMMON_LOCATIONS) {
        if (await isExecutable(location)) {
            return location;
        }
    }
    return null;
}

/**
 * Detect the loki CLI installation
 * @returns Path to loki CLI or null if not found
 */
export async function detectLokiCli(): Promise<string | null> {
    // First, try PATH
    const pathResult = await findInPath();
    if (pathResult) {
        return pathResult;
    }

    // Then, try common locations
    const commonResult = await findInCommonLocations();
    if (commonResult) {
        return commonResult;
    }

    return null;
}

/**
 * Detect the loki CLI with detailed result
 * @returns Detection result with path, version, and source
 */
export async function detectLokiCliDetailed(): Promise<DetectionResult> {
    // First, try PATH
    const pathResult = await findInPath();
    if (pathResult) {
        const version = await getLokiVersion(pathResult);
        return {
            found: true,
            path: pathResult,
            version,
            source: 'path',
        };
    }

    // Then, try common locations
    const commonResult = await findInCommonLocations();
    if (commonResult) {
        const version = await getLokiVersion(commonResult);
        return {
            found: true,
            path: commonResult,
            version,
            source: 'common',
        };
    }

    return {
        found: false,
        path: null,
        version: null,
        source: 'not_found',
    };
}

/**
 * Get the version of the loki CLI
 * @param cliPath - Path to the loki executable
 * @returns Version string or null if unable to determine
 */
export async function getLokiVersion(cliPath: string): Promise<string | null> {
    try {
        const { stdout } = await execFileAsync(cliPath, ['--version'], {
            timeout: 5000,
        });

        // Parse version from output
        // Expected formats: "loki-mode v5.4.0", "5.4.0", "v5.4.0"
        const output = stdout.trim();
        const versionMatch = output.match(/v?(\d+\.\d+\.\d+(?:-[\w.]+)?)/);

        if (versionMatch) {
            return versionMatch[1];
        }

        // Return raw output if no version pattern found
        return output || null;
    } catch {
        return null;
    }
}

/**
 * Get detailed version info
 * @param cliPath - Path to the loki executable
 * @returns Version info with parsed version and full output
 */
export async function getLokiVersionInfo(cliPath: string): Promise<VersionInfo | null> {
    try {
        const { stdout } = await execFileAsync(cliPath, ['--version'], {
            timeout: 5000,
        });

        const output = stdout.trim();
        const versionMatch = output.match(/v?(\d+\.\d+\.\d+(?:-[\w.]+)?)/);

        return {
            version: versionMatch ? versionMatch[1] : output,
            fullOutput: output,
        };
    } catch {
        return null;
    }
}

/**
 * Check if a TCP port is in use (server is running)
 * @param port - Port number to check
 * @param host - Host to check (default: localhost)
 * @returns true if port is in use, false otherwise
 */
export async function isServerRunning(port: number, host: string = 'localhost'): Promise<boolean> {
    return new Promise((resolve) => {
        const socket = new net.Socket();
        let resolved = false;

        const cleanup = () => {
            socket.removeAllListeners();
            socket.destroy();
        };

        socket.setTimeout(2000);

        socket.on('connect', () => {
            if (!resolved) {
                resolved = true;
                cleanup();
                resolve(true);
            }
        });

        socket.on('timeout', () => {
            if (!resolved) {
                resolved = true;
                cleanup();
                resolve(false);
            }
        });

        socket.on('error', () => {
            if (!resolved) {
                resolved = true;
                cleanup();
                resolve(false);
            }
        });

        socket.connect(port, host);
    });
}

/**
 * Check if the Loki server is running on the default port
 * @param port - Port to check (default: DEFAULT_API_PORT)
 * @returns true if server is running
 */
export async function isLokiServerRunning(port: number = DEFAULT_API_PORT): Promise<boolean> {
    // First check if port is in use
    const portInUse = await isServerRunning(port);
    if (!portInUse) {
        return false;
    }

    // Then verify it's actually a Loki server by hitting health endpoint
    try {
        const response = await fetch(`http://localhost:${port}/health`, {
            method: 'GET',
            signal: AbortSignal.timeout(2000),
        });

        if (response.ok) {
            const rawData = await response.json();
            const data = parseHealthResponse(rawData);
            return data.status === 'ok';
        }
    } catch {
        // Not a Loki server or server not responding to HTTP
    }

    return false;
}

/**
 * Wait for the server to become available
 * @param port - Port to check
 * @param timeout - Maximum time to wait in ms (default: 30000)
 * @param interval - Check interval in ms (default: 500)
 * @returns true if server became available, false if timeout
 */
export async function waitForServer(
    port: number = DEFAULT_API_PORT,
    timeout: number = 30000,
    interval: number = 500
): Promise<boolean> {
    const startTime = Date.now();

    while (Date.now() - startTime < timeout) {
        if (await isLokiServerRunning(port)) {
            return true;
        }
        await new Promise(resolve => setTimeout(resolve, interval));
    }

    return false;
}

/**
 * Validate the CLI is working correctly
 * @param cliPath - Path to the loki executable
 * @returns true if CLI is functional
 */
export async function validateCli(cliPath: string): Promise<boolean> {
    try {
        // Try to run --help to verify CLI is functional
        const { stdout, stderr } = await execFileAsync(cliPath, ['--help'], {
            timeout: 5000,
        });

        // Check for expected help output keywords
        const output = (stdout + stderr).toLowerCase();
        return output.includes('loki') || output.includes('usage') || output.includes('help');
    } catch {
        return false;
    }
}

/**
 * Get available loki subcommands
 * @param cliPath - Path to the loki executable
 * @returns Array of available subcommands
 */
export async function getAvailableCommands(cliPath: string): Promise<string[]> {
    try {
        const { stdout } = await execFileAsync(cliPath, ['--help'], {
            timeout: 5000,
        });

        // Parse commands from help output
        // Look for patterns like "  command    description" or "command:"
        const commands: string[] = [];
        const lines = stdout.split('\n');

        for (const line of lines) {
            // Match command patterns in help output
            const match = line.match(/^\s{2,4}(\w+(?:-\w+)*)\s{2,}/);
            if (match && match[1]) {
                commands.push(match[1]);
            }
        }

        return commands;
    } catch {
        return [];
    }
}

export default {
    detectLokiCli,
    detectLokiCliDetailed,
    getLokiVersion,
    getLokiVersionInfo,
    isServerRunning,
    isLokiServerRunning,
    waitForServer,
    validateCli,
    getAvailableCommands,
};

/**
 * Loki CLI Executor
 * Class to execute Loki CLI commands and manage the server process
 */

import { spawn, ChildProcess, SpawnOptions, execFile } from 'child_process';
import { promisify } from 'util';
import { EventEmitter } from 'events';
import { detectLokiCli, waitForServer, isLokiServerRunning } from './detector';
import { DEFAULT_API_PORT } from '../utils/constants';

const execFileAsync = promisify(execFile);

/**
 * Command execution result
 */
export interface ExecutionResult {
    stdout: string;
    stderr: string;
    code: number | null;
    signal: NodeJS.Signals | null;
    success: boolean;
}

/**
 * Server process state
 */
export type ServerState = 'stopped' | 'starting' | 'running' | 'stopping' | 'error';

/**
 * Executor configuration options
 */
export interface ExecutorConfig {
    cliPath?: string;
    serverPort?: number;
    startupTimeout?: number;
    commandTimeout?: number;
    env?: Record<string, string>;
    cwd?: string;
}

/**
 * Default configuration
 */
const DEFAULT_CONFIG: Required<Omit<ExecutorConfig, 'env' | 'cwd'>> = {
    cliPath: '',
    serverPort: DEFAULT_API_PORT,
    startupTimeout: 30000,
    commandTimeout: 60000,
};

/**
 * Events emitted by CliExecutor
 */
export interface CliExecutorEvents {
    'server:starting': () => void;
    'server:started': (port: number) => void;
    'server:stopping': () => void;
    'server:stopped': (code: number | null) => void;
    'server:error': (error: Error) => void;
    'server:output': (data: string) => void;
    'server:stderr': (data: string) => void;
}

/**
 * CliExecutor - Execute Loki CLI commands and manage the server
 */
export class CliExecutor extends EventEmitter {
    private config: Required<Omit<ExecutorConfig, 'env' | 'cwd'>> & Pick<ExecutorConfig, 'env' | 'cwd'>;
    private serverProcess: ChildProcess | null = null;
    private _serverState: ServerState = 'stopped';
    private _cliPath: string | null = null;
    private outputBuffer: string = '';
    private stderrBuffer: string = '';

    /**
     * Create a new CLI executor
     * @param config - Configuration options
     */
    constructor(config?: ExecutorConfig) {
        super();
        this.config = {
            ...DEFAULT_CONFIG,
            ...config,
        };
    }

    /**
     * Get current server state
     */
    get serverState(): ServerState {
        return this._serverState;
    }

    /**
     * Get CLI path (cached after first detection)
     */
    get cliPath(): string | null {
        return this._cliPath;
    }

    /**
     * Get collected server output
     */
    get serverOutput(): string {
        return this.outputBuffer;
    }

    /**
     * Get collected server stderr
     */
    get serverStderr(): string {
        return this.stderrBuffer;
    }

    /**
     * Set server state and emit event
     */
    private setServerState(state: ServerState): void {
        this._serverState = state;
    }

    /**
     * Ensure CLI path is available
     */
    private async ensureCliPath(): Promise<string> {
        if (this._cliPath) {
            return this._cliPath;
        }

        if (this.config.cliPath) {
            this._cliPath = this.config.cliPath;
            return this._cliPath;
        }

        const detectedPath = await detectLokiCli();
        if (!detectedPath) {
            throw new Error(
                'Loki CLI not found. Please install it via npm (npm install -g loki-mode), ' +
                'Homebrew (brew install loki-mode), or specify the path in settings.'
            );
        }

        this._cliPath = detectedPath;
        return this._cliPath;
    }

    /**
     * Build spawn options
     */
    private buildSpawnOptions(timeout?: number): SpawnOptions {
        return {
            cwd: this.config.cwd,
            env: {
                ...process.env,
                ...this.config.env,
                FORCE_COLOR: '0', // Disable color codes for parsing
            },
            timeout: timeout || this.config.commandTimeout,
            shell: process.platform === 'win32',
            windowsHide: true,
        };
    }

    /**
     * Start the Loki server
     * @returns Promise that resolves when server is ready
     */
    async startServer(): Promise<void> {
        // Check if already running
        if (this._serverState === 'running') {
            return;
        }

        // Check if server is already running (from another process)
        if (await isLokiServerRunning(this.config.serverPort)) {
            this.setServerState('running');
            this.emit('server:started', this.config.serverPort);
            return;
        }

        if (this._serverState === 'starting') {
            throw new Error('Server is already starting');
        }

        const cliPath = await this.ensureCliPath();

        this.setServerState('starting');
        this.emit('server:starting');
        this.outputBuffer = '';
        this.stderrBuffer = '';

        return new Promise((resolve, reject) => {
            const args = ['serve', '--port', String(this.config.serverPort)];

            this.serverProcess = spawn(cliPath, args, {
                ...this.buildSpawnOptions(),
                detached: false,
                stdio: ['pipe', 'pipe', 'pipe'],
            });

            // Handle stdout
            this.serverProcess.stdout?.on('data', (data: Buffer) => {
                const output = data.toString();
                this.outputBuffer += output;
                this.emit('server:output', output);
            });

            // Handle stderr
            this.serverProcess.stderr?.on('data', (data: Buffer) => {
                const output = data.toString();
                this.stderrBuffer += output;
                this.emit('server:stderr', output);
            });

            // Handle process exit
            this.serverProcess.on('exit', (code, _signal) => {
                this.serverProcess = null;
                this.setServerState('stopped');
                this.emit('server:stopped', code);

                // If we're still waiting for startup, reject
                if (this._serverState === 'starting') {
                    reject(new Error(`Server exited during startup with code ${code}`));
                }
            });

            // Handle process error
            this.serverProcess.on('error', (error) => {
                this.serverProcess = null;
                this.setServerState('error');
                this.emit('server:error', error);
                reject(error);
            });

            // Wait for server to be ready
            waitForServer(this.config.serverPort, this.config.startupTimeout)
                .then((ready) => {
                    if (ready) {
                        this.setServerState('running');
                        this.emit('server:started', this.config.serverPort);
                        resolve();
                    } else {
                        this.setServerState('error');
                        const error = new Error('Server failed to start within timeout');
                        this.emit('server:error', error);
                        // Try to kill the process
                        this.serverProcess?.kill();
                        reject(error);
                    }
                })
                .catch(reject);
        });
    }

    /**
     * Stop the Loki server
     * @param force - Force kill if graceful shutdown fails
     */
    async stopServer(force: boolean = false): Promise<void> {
        if (this._serverState === 'stopped') {
            return;
        }

        if (!this.serverProcess) {
            // Server might be running from another process
            // Just update our state
            this.setServerState('stopped');
            return;
        }

        this.setServerState('stopping');
        this.emit('server:stopping');

        return new Promise((resolve) => {
            if (!this.serverProcess) {
                this.setServerState('stopped');
                resolve();
                return;
            }

            const killTimeout = setTimeout(() => {
                if (this.serverProcess) {
                    this.serverProcess.kill('SIGKILL');
                }
            }, force ? 0 : 5000);

            this.serverProcess.once('exit', (code) => {
                clearTimeout(killTimeout);
                this.serverProcess = null;
                this.setServerState('stopped');
                this.emit('server:stopped', code);
                resolve();
            });

            // Send graceful shutdown signal
            this.serverProcess.kill(force ? 'SIGKILL' : 'SIGTERM');
        });
    }

    /**
     * Execute a CLI command
     * @param command - Subcommand to execute
     * @param args - Arguments for the command
     * @param timeout - Command timeout in ms
     * @returns Execution result
     */
    async executeCommand(
        command: string,
        args: string[] = [],
        timeout?: number
    ): Promise<ExecutionResult> {
        const cliPath = await this.ensureCliPath();
        const fullArgs = [command, ...args];

        try {
            const { stdout, stderr } = await execFileAsync(
                cliPath,
                fullArgs,
                {
                    cwd: this.config.cwd,
                    env: {
                        ...process.env,
                        ...this.config.env,
                        FORCE_COLOR: '0',
                    },
                    timeout: timeout || this.config.commandTimeout,
                    maxBuffer: 10 * 1024 * 1024, // 10MB buffer
                }
            );

            return {
                stdout,
                stderr,
                code: 0,
                signal: null,
                success: true,
            };
        } catch (error: unknown) {
            const execError = error as { stdout?: string; stderr?: string; code?: number; signal?: NodeJS.Signals };
            return {
                stdout: execError.stdout || '',
                stderr: execError.stderr || (error as Error).message,
                code: execError.code ?? 1,
                signal: execError.signal || null,
                success: false,
            };
        }
    }

    /**
     * Execute a command and stream output
     * @param command - Subcommand to execute
     * @param args - Arguments for the command
     * @param onOutput - Callback for stdout data
     * @param onError - Callback for stderr data
     * @returns Promise that resolves with exit code
     */
    async executeCommandStreaming(
        command: string,
        args: string[] = [],
        onOutput?: (data: string) => void,
        onError?: (data: string) => void
    ): Promise<number> {
        const cliPath = await this.ensureCliPath();
        const fullArgs = [command, ...args];

        return new Promise((resolve, reject) => {
            const proc = spawn(cliPath, fullArgs, {
                ...this.buildSpawnOptions(),
                stdio: ['pipe', 'pipe', 'pipe'],
            });

            proc.stdout?.on('data', (data: Buffer) => {
                onOutput?.(data.toString());
            });

            proc.stderr?.on('data', (data: Buffer) => {
                onError?.(data.toString());
            });

            proc.on('exit', (code, _signal) => {
                resolve(code ?? 0);
            });

            proc.on('error', (error) => {
                reject(error);
            });
        });
    }

    /**
     * Get CLI help text
     * @param command - Optional subcommand to get help for
     */
    async getHelp(command?: string): Promise<string> {
        const args = command ? [command, '--help'] : ['--help'];
        const result = await this.executeCommand(args[0], args.slice(1));
        return result.stdout || result.stderr;
    }

    /**
     * Get CLI version
     */
    async getVersion(): Promise<string> {
        const result = await this.executeCommand('--version', []);
        const output = result.stdout || result.stderr;
        const match = output.match(/v?(\d+\.\d+\.\d+(?:-[\w.]+)?)/);
        return match ? match[1] : output.trim();
    }

    /**
     * Check if server is currently managed by this executor
     */
    isServerManaged(): boolean {
        return this.serverProcess !== null;
    }

    /**
     * Send input to the server process stdin
     * @param input - Input string to send
     */
    async sendInput(input: string): Promise<void> {
        if (!this.serverProcess || !this.serverProcess.stdin) {
            throw new Error('Server process is not running or stdin is not available');
        }

        return new Promise((resolve, reject) => {
            this.serverProcess!.stdin!.write(input + '\n', (error) => {
                if (error) {
                    reject(error);
                } else {
                    resolve();
                }
            });
        });
    }

    /**
     * Clean up resources
     */
    async dispose(): Promise<void> {
        await this.stopServer(true);
        this.removeAllListeners();
    }
}

/**
 * Create a new CLI executor
 * @param config - Configuration options
 */
export function createExecutor(config?: ExecutorConfig): CliExecutor {
    return new CliExecutor(config);
}

/**
 * Default export
 */
export default CliExecutor;

/**
 * CLI Module Exports
 * Re-exports all CLI detector and executor functionality
 */

// Detector
export {
    detectLokiCli,
    detectLokiCliDetailed,
    getLokiVersion,
    getLokiVersionInfo,
    isServerRunning,
    isLokiServerRunning,
    waitForServer,
    validateCli,
    getAvailableCommands,
} from './detector';
export type { VersionInfo, DetectionResult } from './detector';

// Executor
export { CliExecutor, createExecutor } from './executor';
export type { ExecutionResult, ServerState, ExecutorConfig, CliExecutorEvents } from './executor';
export { default as Executor } from './executor';

import * as vscode from 'vscode';
import { TaskTreeProvider } from '../providers/taskTreeProvider';
import { SessionTreeProvider } from '../providers/sessionTreeProvider';
import { StatusBarManager, showQuickPickMenu } from '../views/statusBarItem';

/**
 * Provider options for starting a session
 * Maps display labels to provider values
 */
const PROVIDER_MAP: Record<string, 'claude' | 'codex' | 'gemini'> = {
    'Claude Code': 'claude',
    'OpenAI Codex': 'codex',
    'Google Gemini': 'gemini'
};

const PROVIDER_OPTIONS: vscode.QuickPickItem[] = [
    {
        label: 'Claude Code',
        description: 'Full features (recommended)'
    },
    {
        label: 'OpenAI Codex',
        description: 'Degraded mode - sequential only'
    },
    {
        label: 'Google Gemini',
        description: 'Degraded mode - sequential only'
    }
];

/**
 * Command handler dependencies
 */
export interface CommandDependencies {
    taskTreeProvider: TaskTreeProvider;
    sessionTreeProvider: SessionTreeProvider;
    statusBarManager: StatusBarManager;
    apiEndpoint: string;
    outputChannel: vscode.OutputChannel;
}

/**
 * Register all Loki Mode commands
 */
export function registerCommands(
    context: vscode.ExtensionContext,
    deps: CommandDependencies
): void {
    const { taskTreeProvider, sessionTreeProvider, statusBarManager, outputChannel } = deps;

    // loki.start - Start a new session
    context.subscriptions.push(
        vscode.commands.registerCommand('loki.start', async () => {
            await startSession(deps);
        })
    );

    // loki.stop - Stop the current session
    context.subscriptions.push(
        vscode.commands.registerCommand('loki.stop', async () => {
            await stopSession(deps);
        })
    );

    // loki.pause - Pause the current session
    context.subscriptions.push(
        vscode.commands.registerCommand('loki.pause', async () => {
            await pauseSession(deps);
        })
    );

    // loki.resume - Resume a paused session
    context.subscriptions.push(
        vscode.commands.registerCommand('loki.resume', async () => {
            await resumeSession(deps);
        })
    );

    // loki.status - Show status notification
    context.subscriptions.push(
        vscode.commands.registerCommand('loki.status', async () => {
            await showStatus(deps);
        })
    );

    // loki.injectInput - Send human input to the session
    context.subscriptions.push(
        vscode.commands.registerCommand('loki.injectInput', async () => {
            await injectInput(deps);
        })
    );

    // loki.refreshTasks - Refresh task and session views
    context.subscriptions.push(
        vscode.commands.registerCommand('loki.refreshTasks', async () => {
            outputChannel.appendLine('Refreshing tasks and session...');
            await Promise.all([
                taskTreeProvider.refresh(),
                sessionTreeProvider.refresh()
            ]);
            const counts = taskTreeProvider.getTaskCounts();
            statusBarManager.setTaskCounts(counts.completed, counts.total);
            vscode.window.showInformationMessage('Loki Mode: Status refreshed');
        })
    );

    // loki.showQuickPick - Show the quick pick menu
    context.subscriptions.push(
        vscode.commands.registerCommand('loki.showQuickPick', async () => {
            const command = await showQuickPickMenu(statusBarManager);
            if (command) {
                vscode.commands.executeCommand(command);
            }
        })
    );

    // loki.openPrd - Open the current PRD file
    context.subscriptions.push(
        vscode.commands.registerCommand('loki.openPrd', async () => {
            const session = sessionTreeProvider.getSession();
            if (session.prdPath) {
                const doc = await vscode.workspace.openTextDocument(session.prdPath);
                await vscode.window.showTextDocument(doc);
            } else {
                vscode.window.showWarningMessage('No PRD file associated with current session');
            }
        })
    );

    outputChannel.appendLine('All Loki Mode commands registered');
}

/**
 * Start a new Loki Mode session
 */
async function startSession(deps: CommandDependencies): Promise<void> {
    const { sessionTreeProvider, statusBarManager, apiEndpoint, outputChannel } = deps;

    // Check if session is already active
    if (sessionTreeProvider.isActive()) {
        const choice = await vscode.window.showWarningMessage(
            'A Loki Mode session is already active. Stop it and start a new one?',
            'Stop and Start',
            'Cancel'
        );
        if (choice !== 'Stop and Start') {
            return;
        }
        await stopSession(deps);
    }

    // Step 1: Select PRD file
    const prdUri = await vscode.window.showOpenDialog({
        canSelectFiles: true,
        canSelectFolders: false,
        canSelectMany: false,
        filters: {
            'PRD Files': ['md', 'txt', 'json'],
            'All Files': ['*']
        },
        title: 'Select PRD File',
        openLabel: 'Select PRD'
    });

    if (!prdUri || prdUri.length === 0) {
        return;
    }

    const prdPath = prdUri[0].fsPath;
    outputChannel.appendLine(`Selected PRD: ${prdPath}`);

    // Step 2: Select provider
    const providerPick = await vscode.window.showQuickPick(
        PROVIDER_OPTIONS,
        {
            placeHolder: 'Select AI Provider',
            title: 'Choose Provider for Loki Mode'
        }
    );

    if (!providerPick) {
        return;
    }

    // Map the label back to the provider value
    const provider = PROVIDER_MAP[providerPick.label] || 'claude';
    outputChannel.appendLine(`Selected provider: ${provider}`);

    // Step 3: Start the session
    try {
        statusBarManager.updateStatus({
            state: 'running',
            phase: 'Starting',
            provider: provider
        });

        const response = await fetch(`${apiEndpoint}/start`, {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json'
            },
            body: JSON.stringify({
                prd: prdPath,
                provider
            })
        });

        if (!response.ok) {
            const error = await response.text();
            throw new Error(`Failed to start session: ${error}`);
        }

        const data = await response.json();
        outputChannel.appendLine(`Session started: ${JSON.stringify(data)}`);

        // Update UI
        await sessionTreeProvider.refresh();
        await deps.taskTreeProvider.refresh();

        vscode.window.showInformationMessage(
            `Loki Mode session started with ${providerPick.label}`
        );

    } catch (error) {
        const errorMessage = error instanceof Error ? error.message : 'Unknown error';
        const errorCode = (error as { code?: string }).code;
        outputChannel.appendLine(`Error starting session: ${errorMessage} (code: ${errorCode})`);
        statusBarManager.setState('error');

        // Show user-friendly error with action button for connection issues
        if (errorCode === 'CONNECTION_REFUSED' || errorMessage.includes('server is not running')) {
            const action = await vscode.window.showErrorMessage(
                'Loki Mode dashboard server is not running. Start it with "loki start" or "loki dashboard start" first.',
                'Open Terminal',
                'Copy Command'
            );

            if (action === 'Open Terminal') {
                const terminal = vscode.window.createTerminal('Loki Mode Server');
                terminal.show();
                terminal.sendText('loki start || ./autonomy/run.sh');
            } else if (action === 'Copy Command') {
                await vscode.env.clipboard.writeText('loki start');
                vscode.window.showInformationMessage('Command copied: loki start');
            }
        } else {
            vscode.window.showErrorMessage(`Failed to start Loki Mode: ${errorMessage}`);
        }
    }
}

/**
 * Stop the current session
 */
async function stopSession(deps: CommandDependencies): Promise<void> {
    const { sessionTreeProvider, taskTreeProvider, statusBarManager, apiEndpoint, outputChannel } = deps;

    if (!sessionTreeProvider.isActive()) {
        vscode.window.showInformationMessage('No active Loki Mode session to stop');
        return;
    }

    // Confirm stop
    const confirm = await vscode.window.showWarningMessage(
        'Are you sure you want to stop the Loki Mode session?',
        'Stop Session',
        'Cancel'
    );

    if (confirm !== 'Stop Session') {
        return;
    }

    try {
        const response = await fetch(`${apiEndpoint}/stop`, {
            method: 'POST'
        });

        if (!response.ok) {
            const error = await response.text();
            throw new Error(`Failed to stop session: ${error}`);
        }

        outputChannel.appendLine('Session stopped');

        // Update UI
        statusBarManager.setState('idle');
        await sessionTreeProvider.refresh();
        await taskTreeProvider.refresh();

        vscode.window.showInformationMessage('Loki Mode session stopped');

    } catch (error) {
        const errorMessage = error instanceof Error ? error.message : 'Unknown error';
        outputChannel.appendLine(`Error stopping session: ${errorMessage}`);
        vscode.window.showErrorMessage(`Failed to stop session: ${errorMessage}`);
    }
}

/**
 * Pause the current session
 */
async function pauseSession(deps: CommandDependencies): Promise<void> {
    const { sessionTreeProvider, statusBarManager, apiEndpoint, outputChannel } = deps;

    const session = sessionTreeProvider.getSession();
    if (!session.active || session.status !== 'running') {
        vscode.window.showInformationMessage('No running session to pause');
        return;
    }

    try {
        const response = await fetch(`${apiEndpoint}/pause`, {
            method: 'POST'
        });

        if (!response.ok) {
            const error = await response.text();
            throw new Error(`Failed to pause session: ${error}`);
        }

        outputChannel.appendLine('Session paused');

        // Update UI
        statusBarManager.setState('paused');
        await sessionTreeProvider.refresh();

        vscode.window.showInformationMessage('Loki Mode session paused');

    } catch (error) {
        const errorMessage = error instanceof Error ? error.message : 'Unknown error';
        outputChannel.appendLine(`Error pausing session: ${errorMessage}`);
        vscode.window.showErrorMessage(`Failed to pause session: ${errorMessage}`);
    }
}

/**
 * Resume a paused session
 */
async function resumeSession(deps: CommandDependencies): Promise<void> {
    const { sessionTreeProvider, statusBarManager, apiEndpoint, outputChannel } = deps;

    const session = sessionTreeProvider.getSession();
    if (!session.active || session.status !== 'paused') {
        vscode.window.showInformationMessage('No paused session to resume');
        return;
    }

    try {
        const response = await fetch(`${apiEndpoint}/resume`, {
            method: 'POST'
        });

        if (!response.ok) {
            const error = await response.text();
            throw new Error(`Failed to resume session: ${error}`);
        }

        outputChannel.appendLine('Session resumed');

        // Update UI
        statusBarManager.setState('running');
        await sessionTreeProvider.refresh();

        vscode.window.showInformationMessage('Loki Mode session resumed');

    } catch (error) {
        const errorMessage = error instanceof Error ? error.message : 'Unknown error';
        outputChannel.appendLine(`Error resuming session: ${errorMessage}`);
        vscode.window.showErrorMessage(`Failed to resume session: ${errorMessage}`);
    }
}

/**
 * Show detailed status notification
 */
async function showStatus(deps: CommandDependencies): Promise<void> {
    const { sessionTreeProvider, taskTreeProvider, outputChannel } = deps;

    await Promise.all([
        sessionTreeProvider.refresh(),
        taskTreeProvider.refresh()
    ]);

    const session = sessionTreeProvider.getSession();
    const counts = taskTreeProvider.getTaskCounts();

    if (!session.active) {
        vscode.window.showInformationMessage(
            'Loki Mode: No active session. Use "Start Session" to begin.'
        );
        return;
    }

    const formatProvider = (provider: string): string => {
        switch (provider) {
            case 'claude': return 'Claude Code';
            case 'codex': return 'OpenAI Codex';
            case 'gemini': return 'Google Gemini';
            default: return provider;
        }
    };

    const statusLines = [
        `Status: ${session.status}`,
        `Provider: ${formatProvider(session.provider)}`,
        `Phase: ${session.phase}`,
        `Tasks: ${counts.completed}/${counts.total} completed`,
        `In Progress: ${counts.inProgress}`
    ];

    if (session.currentTask) {
        statusLines.push(`Current: ${session.currentTask}`);
    }

    outputChannel.appendLine('Status requested:');
    statusLines.forEach(line => outputChannel.appendLine(`  ${line}`));

    const message = `Loki Mode: ${session.status} - ${session.phase} (${counts.completed}/${counts.total} tasks)`;

    if (session.status === 'error') {
        vscode.window.showErrorMessage(message, 'View Details').then(choice => {
            if (choice === 'View Details') {
                outputChannel.show();
            }
        });
    } else {
        vscode.window.showInformationMessage(message);
    }
}

/**
 * Inject human input into the session
 */
async function injectInput(deps: CommandDependencies): Promise<void> {
    const { sessionTreeProvider, apiEndpoint, outputChannel } = deps;

    if (!sessionTreeProvider.isActive()) {
        vscode.window.showWarningMessage('No active session to send input to');
        return;
    }

    // Show input box for human input
    const input = await vscode.window.showInputBox({
        placeHolder: 'Enter guidance or corrections for the AI...',
        prompt: 'Human Input for Loki Mode',
        title: 'Inject Human Input',
        ignoreFocusOut: true
    });

    if (!input || input.trim() === '') {
        return;
    }

    try {
        const response = await fetch(`${apiEndpoint}/input`, {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json'
            },
            body: JSON.stringify({
                input: input.trim()
            })
        });

        if (!response.ok) {
            const error = await response.text();
            throw new Error(`Failed to inject input: ${error}`);
        }

        outputChannel.appendLine(`Human input injected: ${input}`);
        vscode.window.showInformationMessage('Input sent to Loki Mode session');

    } catch (error) {
        const errorMessage = error instanceof Error ? error.message : 'Unknown error';
        outputChannel.appendLine(`Error injecting input: ${errorMessage}`);
        vscode.window.showErrorMessage(`Failed to send input: ${errorMessage}`);
    }
}

import * as vscode from 'vscode';
import * as path from 'path';
import * as fs from 'fs';
import { spawn } from 'child_process';
import { Config } from './utils/config';
import { Logger, logger } from './utils/logger';
import { ChatViewProvider } from './views/chatViewProvider';
import { LogsViewProvider } from './views/logsViewProvider';
import { MemoryViewProvider } from './views/memoryViewProvider';
import { DashboardWebviewProvider } from './views/dashboardWebview';
import { CheckpointProvider } from './views/checkpointProvider';
import { LokiApiClient } from './api/client';
import { parseStatusResponse, isValidTaskStatus } from './api/validators';
import { LokiEvent, Disposable } from './api/types';
import { getLearningCollector, disposeLearningCollector, LearningCollector, Outcome } from './services/learning-collector';
import { getFileEditMemoryIntegration, disposeFileEditMemoryIntegration, FileEditMemoryIntegration } from './services/memory-integration';

// State tracking
let isRunning = false;
let isPaused = false;
let statusBarItem: vscode.StatusBarItem | undefined;
let statusSubscription: Disposable | undefined;
let learningCollector: LearningCollector | undefined;
let memoryIntegration: FileEditMemoryIntegration | undefined;

/**
 * Session item for the sessions tree view
 */
class SessionItem extends vscode.TreeItem {
    constructor(
        public readonly label: string,
        public readonly status: 'running' | 'paused' | 'stopped',
        public readonly provider: string,
        public readonly startTime: Date,
        public readonly collapsibleState: vscode.TreeItemCollapsibleState = vscode.TreeItemCollapsibleState.None
    ) {
        super(label, collapsibleState);
        this.tooltip = `${provider} - ${status} - Started: ${startTime.toLocaleTimeString()}`;
        this.description = `${provider} (${status})`;

        switch (status) {
            case 'running':
                this.iconPath = new vscode.ThemeIcon('play-circle', new vscode.ThemeColor('charts.green'));
                break;
            case 'paused':
                this.iconPath = new vscode.ThemeIcon('debug-pause', new vscode.ThemeColor('charts.yellow'));
                break;
            case 'stopped':
                this.iconPath = new vscode.ThemeIcon('stop-circle', new vscode.ThemeColor('charts.red'));
                break;
        }
    }
}

/**
 * Task item for the tasks tree view
 */
class TaskItem extends vscode.TreeItem {
    constructor(
        public readonly label: string,
        public readonly taskId: string,
        public readonly status: 'pending' | 'in_progress' | 'completed',
        public readonly description?: string
    ) {
        super(label, vscode.TreeItemCollapsibleState.None);
        this.tooltip = description || label;

        switch (status) {
            case 'pending':
                this.iconPath = new vscode.ThemeIcon('circle-outline');
                this.description = 'pending';
                break;
            case 'in_progress':
                this.iconPath = new vscode.ThemeIcon('loading~spin', new vscode.ThemeColor('charts.blue'));
                this.description = 'in progress';
                break;
            case 'completed':
                this.iconPath = new vscode.ThemeIcon('check', new vscode.ThemeColor('charts.green'));
                this.description = 'completed';
                break;
        }
    }
}

/**
 * Tree data provider for Loki sessions
 */
class SessionsProvider implements vscode.TreeDataProvider<SessionItem> {
    private _onDidChangeTreeData: vscode.EventEmitter<SessionItem | undefined | null | void> = new vscode.EventEmitter<SessionItem | undefined | null | void>();
    readonly onDidChangeTreeData: vscode.Event<SessionItem | undefined | null | void> = this._onDidChangeTreeData.event;

    private sessions: SessionItem[] = [];

    refresh(): void {
        this._onDidChangeTreeData.fire();
    }

    addSession(session: SessionItem): void {
        this.sessions.push(session);
        this.refresh();
    }

    updateSession(label: string, status: 'running' | 'paused' | 'stopped'): void {
        const session = this.sessions.find(s => s.label === label);
        if (session) {
            const index = this.sessions.indexOf(session);
            this.sessions[index] = new SessionItem(
                session.label,
                status,
                session.provider,
                session.startTime
            );
            this.refresh();
        }
    }

    clearSessions(): void {
        this.sessions = [];
        this.refresh();
    }

    getTreeItem(element: SessionItem): vscode.TreeItem {
        return element;
    }

    getChildren(): Thenable<SessionItem[]> {
        return Promise.resolve(this.sessions);
    }
}

/**
 * Tree data provider for Loki tasks
 */
class TasksProvider implements vscode.TreeDataProvider<TaskItem> {
    private _onDidChangeTreeData: vscode.EventEmitter<TaskItem | undefined | null | void> = new vscode.EventEmitter<TaskItem | undefined | null | void>();
    readonly onDidChangeTreeData: vscode.Event<TaskItem | undefined | null | void> = this._onDidChangeTreeData.event;

    private tasks: TaskItem[] = [];

    refresh(): void {
        this._onDidChangeTreeData.fire();
    }

    setTasks(tasks: TaskItem[]): void {
        this.tasks = tasks;
        this.refresh();
    }

    clearTasks(): void {
        this.tasks = [];
        this.refresh();
    }

    getTreeItem(element: TaskItem): vscode.TreeItem {
        return element;
    }

    getChildren(): Thenable<TaskItem[]> {
        return Promise.resolve(this.tasks);
    }
}

// Tree providers
let sessionsProvider: SessionsProvider;
let tasksProvider: TasksProvider;
let checkpointProvider: CheckpointProvider;
let chatViewProvider: ChatViewProvider;
let logsViewProvider: LogsViewProvider;
let memoryViewProvider: MemoryViewProvider;
let dashboardWebviewProvider: DashboardWebviewProvider;
let apiClient: LokiApiClient;

/**
 * Check if the workspace has a .loki directory
 */
function hasLokiDirectory(): boolean {
    const workspaceFolders = vscode.workspace.workspaceFolders;
    if (!workspaceFolders || workspaceFolders.length === 0) {
        return false;
    }

    const lokiPath = path.join(workspaceFolders[0].uri.fsPath, '.loki');
    return fs.existsSync(lokiPath);
}

/**
 * Get the .loki directory path for the current workspace
 */
function getLokiPath(): string | undefined {
    const workspaceFolders = vscode.workspace.workspaceFolders;
    if (!workspaceFolders || workspaceFolders.length === 0) {
        return undefined;
    }
    return path.join(workspaceFolders[0].uri.fsPath, '.loki');
}

/**
 * Check session state from filesystem (fallback when API unavailable).
 * Checks .loki/loki.pid, .loki/session.json, and .loki/PAUSE files.
 */
function getFilesystemState(): { running: boolean; paused: boolean } {
    const lokiPath = getLokiPath();
    if (!lokiPath) {
        return { running: false, paused: false };
    }

    let running = false;

    // Check PID file (run.sh-invoked sessions)
    const pidFile = path.join(lokiPath, 'loki.pid');
    if (fs.existsSync(pidFile)) {
        try {
            const pidStr = fs.readFileSync(pidFile, 'utf-8').trim();
            const pid = parseInt(pidStr, 10);
            if (!isNaN(pid)) {
                try {
                    process.kill(pid, 0);
                    running = true;
                } catch {
                    // Process not running, stale PID
                }
            }
        } catch {
            // Can't read PID file
        }
    }

    // Check session.json (skill-invoked sessions)
    if (!running) {
        const sessionFile = path.join(lokiPath, 'session.json');
        if (fs.existsSync(sessionFile)) {
            try {
                const data = JSON.parse(fs.readFileSync(sessionFile, 'utf-8'));
                if (data.status === 'running') {
                    running = true;
                }
            } catch {
                // Can't parse session file
            }
        }
    }

    // Check PAUSE file
    const paused = running && fs.existsSync(path.join(lokiPath, 'PAUSE'));

    return { running, paused };
}

/**
 * Make an API request to the Loki server
 */
async function apiRequest(endpoint: string, method: string = 'GET', body?: unknown): Promise<unknown> {
    const baseUrl = Config.apiBaseUrl;
    const url = `${baseUrl}${endpoint}`;

    logger.debug(`API request: ${method} ${url}`);

    try {
        const options: RequestInit = {
            method,
            headers: {
                'Content-Type': 'application/json',
            },
        };

        if (body) {
            options.body = JSON.stringify(body);
        }

        const response = await fetch(url, options);

        if (!response.ok) {
            throw new Error(`HTTP ${response.status}: ${response.statusText}`);
        }

        const data = await response.json();
        logger.debug(`API response:`, data);
        return data;
    } catch (error) {
        logger.error(`API request failed: ${endpoint}`, error);
        throw error;
    }
}

/**
 * Update the status bar item
 */
function updateStatusBar(): void {
    if (!statusBarItem) {
        return;
    }

    if (!Config.showStatusBar) {
        statusBarItem.hide();
        return;
    }

    if (isRunning) {
        if (isPaused) {
            statusBarItem.text = '$(debug-pause) Loki: Paused';
            statusBarItem.backgroundColor = new vscode.ThemeColor('statusBarItem.warningBackground');
        } else {
            statusBarItem.text = '$(play) Loki: Running';
            statusBarItem.backgroundColor = new vscode.ThemeColor('statusBarItem.prominentBackground');
        }
    } else {
        statusBarItem.text = '$(stop) Loki: Stopped';
        statusBarItem.backgroundColor = undefined;
    }

    statusBarItem.show();
}

/**
 * Update VS Code context for menu visibility
 */
function updateContext(): void {
    vscode.commands.executeCommand('setContext', 'loki.isRunning', isRunning);
    vscode.commands.executeCommand('setContext', 'loki.isPaused', isPaused);
}

/**
 * Manually refresh status from API (for user-triggered refresh)
 */
async function refreshStatus(): Promise<void> {
    try {
        const rawStatus = await apiRequest('/status');
        const status = parseStatusResponse(rawStatus);

        if (status.running !== undefined) {
            isRunning = status.running;
        }
        if (status.paused !== undefined) {
            isPaused = status.paused;
        }
        updateStatusBar();
        updateContext();

        if (status.tasks && Array.isArray(status.tasks)) {
            const taskItems = status.tasks.map(t => new TaskItem(
                t.title,
                t.id,
                mapTaskStatus(t.status),
                t.description
            ));
            tasksProvider.setTasks(taskItems);
        }
    } catch {
        logger.debug('Manual status refresh failed');
    }
}

/**
 * Map TaskStatus to the subset accepted by TaskItem
 */
function mapTaskStatus(status: string): 'pending' | 'in_progress' | 'completed' {
    if (!isValidTaskStatus(status)) {
        return 'pending';
    }
    // Map 'failed' and 'skipped' to 'completed' for UI display
    if (status === 'failed' || status === 'skipped') {
        return 'completed';
    }
    return status as 'pending' | 'in_progress' | 'completed';
}

/**
 * Handle status events from the API client
 */
function handleStatusEvent(event: LokiEvent): void {
    if (event.type !== 'status') {
        return;
    }

    try {
        const status = parseStatusResponse(event.data);

        if (status.running !== undefined && status.running !== isRunning) {
            isRunning = status.running;
            updateStatusBar();
            updateContext();
        }

        if (status.paused !== undefined && status.paused !== isPaused) {
            isPaused = status.paused;
            updateStatusBar();
            updateContext();
        }

        if (status.tasks && Array.isArray(status.tasks)) {
            const taskItems = status.tasks.map(t => new TaskItem(
                t.title,
                t.id,
                mapTaskStatus(t.status),
                t.description
            ));
            tasksProvider.setTasks(taskItems);
        }
    } catch {
        // API not available - fall back to filesystem state
        logger.debug('API status unavailable, checking filesystem');
        const fsState = getFilesystemState();
        if (fsState.running !== isRunning) {
            isRunning = fsState.running;
            updateStatusBar();
            updateContext();
        }
        if (fsState.paused !== isPaused) {
            isPaused = fsState.paused;
            updateStatusBar();
            updateContext();
        }
    }
}

/**
 * Start polling the API (via client subscription)
 */
function startPolling(): void {
    if (statusSubscription) {
        return;
    }

    // Subscribe to status events from the API client
    statusSubscription = apiClient.subscribeToEvents(handleStatusEvent);
    logger.info(`Started API polling (interval: ${Config.pollingInterval}ms)`);
}

/**
 * Stop polling the API
 */
function stopPolling(): void {
    if (statusSubscription) {
        statusSubscription.dispose();
        statusSubscription = undefined;
        logger.info('Stopped API polling');
    }
}

/**
 * Ensure the dashboard server is running.
 * Checks health endpoint first; if unreachable, spawns `loki dashboard start`
 * as a detached child process and waits up to 5 seconds for it to become healthy.
 * Returns true if the server is reachable, false otherwise.
 */
async function ensureDashboardRunning(): Promise<boolean> {
    // Check if already running via health endpoint
    try {
        await apiRequest('/health');
        logger.info('Dashboard server is already running');
        return true;
    } catch {
        logger.info('Dashboard server not running, attempting to start...');
    }

    // Spawn the dashboard server in detached mode
    const lokiPath = getLokiPath();
    const env: Record<string, string> = { ...process.env as Record<string, string> };
    if (lokiPath) {
        env.LOKI_DIR = lokiPath;
    }

    try {
        const child = spawn('loki', ['dashboard', 'start'], {
            detached: true,
            stdio: 'ignore',
            env,
        });

        // Allow the child to outlive the extension process
        child.unref();

        child.on('error', (err) => {
            logger.error('Failed to spawn loki dashboard process', err);
        });

        logger.info('Spawned loki dashboard start process');
    } catch (error) {
        logger.error('Failed to spawn dashboard server', error);
        return false;
    }

    // Poll health endpoint for up to 5 seconds (500ms intervals)
    const maxAttempts = 10;
    const intervalMs = 500;

    for (let attempt = 1; attempt <= maxAttempts; attempt++) {
        await new Promise(resolve => setTimeout(resolve, intervalMs));
        try {
            await apiRequest('/health');
            logger.info(`Dashboard server became healthy after ${attempt * intervalMs}ms`);
            return true;
        } catch {
            logger.debug(`Health check attempt ${attempt}/${maxAttempts} failed`);
        }
    }

    logger.error('Dashboard server did not become healthy within 5 seconds');
    return false;
}

/**
 * Connect to the Loki API
 */
async function connectToApi(): Promise<boolean> {
    logger.info(`Connecting to Loki API at ${Config.apiBaseUrl}`);

    try {
        await apiRequest('/health');
        logger.info('Successfully connected to Loki API');
        startPolling();
        return true;
    } catch {
        logger.warn('Could not connect to Loki API - attempting to start dashboard server');
        const started = await ensureDashboardRunning();
        if (started) {
            logger.info('Dashboard server started, connected to Loki API');
            startPolling();
            return true;
        }
        logger.warn('Could not start dashboard server');
        return false;
    }
}

/**
 * Start Loki Mode command handler
 */
async function startLokiMode(): Promise<void> {
    if (isRunning) {
        vscode.window.showWarningMessage('Loki Mode is already running');
        return;
    }

    logger.info('Starting Loki Mode...');

    // Ensure the dashboard API server is running before making API calls
    const dashboardReady = await ensureDashboardRunning();
    if (!dashboardReady) {
        vscode.window.showErrorMessage('Failed to start Loki dashboard server. Cannot start Loki Mode.');
        logger.error('Dashboard server not available, aborting start');
        return;
    }

    // Track command and start workflow
    learningCollector?.trackCommand('loki.start', ['loki.stop', 'loki.pause']);
    learningCollector?.startWorkflow('loki_session_start');
    learningCollector?.addWorkflowStep('loki_session_start', 'initiate_start');

    // Check for PRD file
    let prdPath = Config.prdPath;

    if (!prdPath) {
        learningCollector?.addWorkflowStep('loki_session_start', 'select_prd');
        const result = await vscode.window.showOpenDialog({
            canSelectFiles: true,
            canSelectFolders: false,
            canSelectMany: false,
            filters: {
                'PRD Files': ['md', 'txt', 'json'],
                'All Files': ['*']
            },
            title: 'Select PRD File (optional)'
        });

        if (result && result.length > 0) {
            prdPath = result[0].fsPath;
            // Track PRD file selection preference
            learningCollector?.emitUserPreference(
                'prd_file_type',
                path.extname(prdPath),
                ['.md', '.txt', '.json'].filter(ext => ext !== path.extname(prdPath)),
                { prdPath }
            );
        }
    }

    try {
        learningCollector?.addWorkflowStep('loki_session_start', 'api_request');
        await apiRequest('/api/control/start', 'POST', {
            provider: Config.provider,
            prd: prdPath || undefined
        });

        isRunning = true;
        isPaused = false;
        updateStatusBar();
        updateContext();

        // Add session to tree view
        const sessionName = `Session ${new Date().toLocaleTimeString()}`;
        sessionsProvider.addSession(new SessionItem(
            sessionName,
            'running',
            Config.provider,
            new Date()
        ));

        // Track provider preference
        learningCollector?.emitUserPreference(
            'provider_choice',
            Config.provider,
            ['claude', 'codex', 'gemini'].filter(p => p !== Config.provider),
            { sessionName }
        );

        vscode.window.showInformationMessage(`Loki Mode started with provider: ${Config.provider}`);
        logger.info(`Loki Mode started (provider: ${Config.provider}, prd: ${prdPath || 'none'})`);

        startPolling();

        // Complete workflow successfully
        learningCollector?.addWorkflowStep('loki_session_start', 'session_active');
        learningCollector?.completeWorkflow('loki_session_start', {
            context: { provider: Config.provider, hasPrd: !!prdPath }
        });

    } catch (error) {
        const errorMessage = error instanceof Error ? error.message : String(error);
        vscode.window.showErrorMessage(`Failed to start Loki Mode: ${errorMessage}`);
        logger.error('Failed to start Loki Mode', error);

        // Emit error pattern
        learningCollector?.emitErrorPattern(
            'session_start_failed',
            errorMessage,
            {
                stackTrace: error instanceof Error ? error.stack : undefined,
                context: { provider: Config.provider, hasPrd: !!prdPath }
            }
        );

        // Complete workflow with failure
        learningCollector?.completeWorkflow('loki_session_start', { outcome: Outcome.FAILURE });
    }
}

/**
 * Stop Loki Mode command handler
 */
async function stopLokiMode(): Promise<void> {
    if (!isRunning) {
        vscode.window.showWarningMessage('Loki Mode is not running');
        return;
    }

    logger.info('Stopping Loki Mode...');
    learningCollector?.trackCommand('loki.stop', ['loki.pause', 'loki.resume']);

    try {
        await apiRequest('/api/control/stop', 'POST');

        isRunning = false;
        isPaused = false;
        updateStatusBar();
        updateContext();

        sessionsProvider.clearSessions();
        tasksProvider.clearTasks();
        stopPolling();

        // Emit success pattern for clean stop
        learningCollector?.emitSuccessPattern(
            'session_stop',
            ['initiate_stop', 'api_request', 'cleanup_ui'],
            { postconditions: ['session_inactive', 'ui_cleared'] }
        );

        vscode.window.showInformationMessage('Loki Mode stopped');
        logger.info('Loki Mode stopped');
    } catch (error) {
        const errorMessage = error instanceof Error ? error.message : String(error);
        vscode.window.showErrorMessage(`Failed to stop Loki Mode: ${errorMessage}`);
        logger.error('Failed to stop Loki Mode', error);

        // Emit error pattern
        learningCollector?.emitErrorPattern(
            'session_stop_failed',
            errorMessage,
            { stackTrace: error instanceof Error ? error.stack : undefined }
        );
    }
}

