/**
 * Show Loki status command handler
 */
async function showStatus(): Promise<void> {
    logger.info('Fetching Loki status...');
    learningCollector?.trackCommand('loki.status', ['loki.refreshTasks']);

    try {
        const rawStatus = await apiRequest('/status');
        const status = parseStatusResponse(rawStatus);

        const statusMessage = [
            `Running: ${status.running ? 'Yes' : 'No'}`,
            `Paused: ${status.paused ? 'Yes' : 'No'}`,
            `Provider: ${status.provider || Config.provider}`,
            `Uptime: ${status.uptime || 0}s`,
            `Tasks Completed: ${status.tasksCompleted || 0}`,
            `Tasks Pending: ${status.tasksPending || 0}`
        ].join('\n');

        vscode.window.showInformationMessage(statusMessage, { modal: true });
        logger.info('Status displayed', status);
    } catch (error) {
        const localStatus = [
            `Running: ${isRunning ? 'Yes' : 'No'}`,
            `Paused: ${isPaused ? 'Yes' : 'No'}`,
            `Provider: ${Config.provider}`,
            `API: Not connected`
        ].join('\n');

        vscode.window.showInformationMessage(localStatus, { modal: true });
        logger.warn('Could not fetch remote status, showing local state');
    }
}

/**
 * Inject input command handler
 */
async function injectInput(): Promise<void> {
    if (!isRunning) {
        vscode.window.showWarningMessage('Loki Mode is not running');
        return;
    }

    learningCollector?.trackCommand('loki.injectInput', []);

    const input = await vscode.window.showInputBox({
        prompt: 'Enter input to inject into Loki Mode',
        placeHolder: 'Type your message...'
    });

    if (!input) {
        return;
    }

    logger.info('Injecting input...');

    try {
        await apiRequest('/input', 'POST', { input });

        // Track input injection as a success pattern
        learningCollector?.emitSuccessPattern(
            'input_injection',
            ['open_input_box', 'enter_text', 'submit'],
            {
                context: { inputLength: input.length },
                postconditions: ['input_queued']
            }
        );

        vscode.window.showInformationMessage('Input injected successfully');
        logger.info(`Input injected: ${input.substring(0, 50)}...`);
    } catch (error) {
        const errorMessage = error instanceof Error ? error.message : String(error);
        vscode.window.showErrorMessage(`Failed to inject input: ${errorMessage}`);
        logger.error('Failed to inject input', error);

        learningCollector?.emitErrorPattern(
            'input_injection_failed',
            errorMessage,
            { stackTrace: error instanceof Error ? error.stack : undefined }
        );
    }
}

/**
 * Show quick pick menu for Loki commands
 */
async function showQuickPick(): Promise<void> {
    learningCollector?.trackCommand('loki.showQuickPick', []);

    const items: vscode.QuickPickItem[] = [
        { label: '$(play) Start Loki Mode', description: 'Start autonomous mode' },
        { label: '$(stop) Stop Loki Mode', description: 'Stop autonomous mode' },
        { label: '$(debug-pause) Pause Loki Mode', description: 'Pause current session' },
        { label: '$(debug-continue) Resume Loki Mode', description: 'Resume paused session' },
        { label: '$(info) Show Status', description: 'Display current status' },
        { label: '$(file) Open PRD', description: 'Open PRD file' },
        { label: '$(terminal) Inject Input', description: 'Send input to Loki Mode' },
        { label: '$(outline-view-icon) Analyze PRD', description: 'Run loki plan' },
        { label: '$(checklist) Review Code', description: 'Run loki review' },
        { label: '$(book) Onboard Project', description: 'Run loki onboard' },
        { label: '$(pass) CI Quality Gates', description: 'Run loki ci' },
    ];

    const selected = await vscode.window.showQuickPick(items, {
        placeHolder: 'Select a Loki Mode command',
    });

    if (!selected) {
        return;
    }

    // Track menu selection as user preference
    const allLabels = items.map(i => i.label);
    learningCollector?.emitUserPreference(
        'quick_pick_selection',
        selected.label,
        allLabels.filter(l => l !== selected.label),
        { menuType: 'command_palette' }
    );

    switch (selected.label) {
        case '$(play) Start Loki Mode':
            await startLokiMode();
            break;
        case '$(stop) Stop Loki Mode':
            await stopLokiMode();
            break;
        case '$(debug-pause) Pause Loki Mode':
            await pauseLokiMode();
            break;
        case '$(debug-continue) Resume Loki Mode':
            await resumeLokiMode();
            break;
        case '$(info) Show Status':
            await showStatus();
            break;
        case '$(file) Open PRD':
            await openPrd();
            break;
        case '$(terminal) Inject Input':
            await injectInput();
            break;
        case '$(outline-view-icon) Analyze PRD':
            vscode.commands.executeCommand('loki.plan');
            break;
        case '$(checklist) Review Code':
            vscode.commands.executeCommand('loki.review');
            break;
        case '$(book) Onboard Project':
            vscode.commands.executeCommand('loki.onboard');
            break;
        case '$(pass) CI Quality Gates':
            vscode.commands.executeCommand('loki.ci');
            break;
    }
}

/**
 * Open PRD file command handler
 */
async function openPrd(): Promise<void> {
    learningCollector?.trackCommand('loki.openPrd', []);

    let prdPath = Config.prdPath;

    if (!prdPath) {
        const result = await vscode.window.showOpenDialog({
            canSelectFiles: true,
            canSelectFolders: false,
            canSelectMany: false,
            filters: {
                'PRD Files': ['md', 'txt', 'json'],
                'All Files': ['*']
            },
            title: 'Select PRD File'
        });

        if (result && result.length > 0) {
            prdPath = result[0].fsPath;
        }
    }

    if (prdPath) {
        const doc = await vscode.workspace.openTextDocument(prdPath);
        await vscode.window.showTextDocument(doc);
        logger.info(`Opened PRD file: ${prdPath}`);

        // Track PRD file open as user preference
        learningCollector?.emitUserPreference(
            'prd_file_opened',
            path.extname(prdPath),
            [],
            { prdPath }
        );
    }
}

/**
 * Extension activation
 */
export function activate(context: vscode.ExtensionContext): void {
    logger.info('Activating Loki Mode extension...');

    // Initialize learning collector for signal emission
    learningCollector = getLearningCollector();
    logger.info('Learning collector initialized');

    // Initialize file edit memory integration for episodic memory
    memoryIntegration = getFileEditMemoryIntegration();
    logger.info('File edit memory integration initialized');

    // Initialize API client with configurable polling interval
    apiClient = new LokiApiClient(Config.apiBaseUrl, { pollingInterval: Config.pollingInterval });

    // Initialize tree providers
    sessionsProvider = new SessionsProvider();
    tasksProvider = new TasksProvider();
    checkpointProvider = new CheckpointProvider();

    // Initialize webview providers
    chatViewProvider = new ChatViewProvider(context.extensionUri, apiClient);
    logsViewProvider = new LogsViewProvider(context.extensionUri, apiClient);
    // TODO: Remove MemoryViewProvider in v6.0.0 - deprecated in favor of dashboard Memory tab
    memoryViewProvider = new MemoryViewProvider(context.extensionUri, apiClient);
    dashboardWebviewProvider = new DashboardWebviewProvider(context.extensionUri, apiClient);

    // Register tree views
    const sessionsView = vscode.window.createTreeView('loki-sessions', {
        treeDataProvider: sessionsProvider,
        showCollapseAll: false
    });

    const tasksView = vscode.window.createTreeView('loki-tasks', {
        treeDataProvider: tasksProvider,
        showCollapseAll: false
    });

    const checkpointsView = vscode.window.createTreeView('loki-checkpoints', {
        treeDataProvider: checkpointProvider,
        showCollapseAll: false
    });

    // Register webview providers
    const chatView = vscode.window.registerWebviewViewProvider(
        ChatViewProvider.viewType,
        chatViewProvider
    );

    const logsView = vscode.window.registerWebviewViewProvider(
        LogsViewProvider.viewType,
        logsViewProvider
    );

    // TODO: Remove memoryView registration in v6.0.0 - deprecated in favor of dashboard Memory tab
    const memoryView = vscode.window.registerWebviewViewProvider(
        MemoryViewProvider.viewType,
        memoryViewProvider
    );

    const dashboardView = vscode.window.registerWebviewViewProvider(
        DashboardWebviewProvider.viewType,
        dashboardWebviewProvider
    );

    // Create status bar item
    statusBarItem = vscode.window.createStatusBarItem(vscode.StatusBarAlignment.Left, 100);
    statusBarItem.command = 'loki.status';
    statusBarItem.tooltip = 'Loki Mode Status (click for details)';
    updateStatusBar();

    // Register commands
    const commands = [
        vscode.commands.registerCommand('loki.start', startLokiMode),
        vscode.commands.registerCommand('loki.stop', stopLokiMode),
        vscode.commands.registerCommand('loki.pause', pauseLokiMode),
        vscode.commands.registerCommand('loki.resume', resumeLokiMode),
        vscode.commands.registerCommand('loki.status', showStatus),
        vscode.commands.registerCommand('loki.injectInput', injectInput),
        vscode.commands.registerCommand('loki.refreshSessions', () => {
            sessionsProvider.refresh();
            logger.debug('Sessions refreshed');
        }),
        vscode.commands.registerCommand('loki.refreshTasks', async () => {
            tasksProvider.refresh();
            await refreshStatus();
            logger.debug('Tasks refreshed');
        }),
        vscode.commands.registerCommand('loki.showQuickPick', showQuickPick),
        vscode.commands.registerCommand('loki.openPrd', openPrd),
        vscode.commands.registerCommand('loki.openDashboard', () => {
            // Focus the dashboard view in the sidebar
            vscode.commands.executeCommand('workbench.view.extension.loki-mode');
            logger.info('Dashboard opened');
        }),
        vscode.commands.registerCommand('loki.refreshCheckpoints', async () => {
            await checkpointProvider.refresh();
            logger.debug('Checkpoints refreshed');
        }),
        vscode.commands.registerCommand('loki.createCheckpoint', async () => {
            await checkpointProvider.createCheckpoint();
        }),
        vscode.commands.registerCommand('loki.rollbackCheckpoint', async (item) => {
            await checkpointProvider.rollbackCheckpoint(item);
        }),
        vscode.commands.registerCommand('loki.plan', async () => {
            const prdUri = await vscode.window.showOpenDialog({
                canSelectFiles: true,
                canSelectFolders: false,
                canSelectMany: false,
                filters: {
                    'PRD Files': ['md', 'txt', 'json'],
                    'All Files': ['*']
                },
                title: 'Select PRD File to Analyze'
            });
            const prdArg = prdUri && prdUri.length > 0 ? ` "${prdUri[0].fsPath}"` : '';
            const terminal = vscode.window.createTerminal('Loki Plan');
            terminal.show();
            terminal.sendText(`loki plan${prdArg}`);
            logger.info(`Running loki plan${prdArg}`);
        }),
        vscode.commands.registerCommand('loki.review', () => {
            const terminal = vscode.window.createTerminal('Loki Review');
            terminal.show();
            terminal.sendText('loki review');
            logger.info('Running loki review');
        }),
        vscode.commands.registerCommand('loki.onboard', () => {
            const terminal = vscode.window.createTerminal('Loki Onboard');
            terminal.show();
            terminal.sendText('loki onboard');
            logger.info('Running loki onboard');
        }),
        vscode.commands.registerCommand('loki.ci', () => {
            const terminal = vscode.window.createTerminal('Loki CI');
            terminal.show();
            terminal.sendText('loki ci');
            logger.info('Running loki ci');
        })
    ];

    // Register configuration change listener
    const configListener = Config.onDidChange((e) => {
        logger.info('Configuration changed');

        if (Config.didChange(e, 'showStatusBar')) {
            updateStatusBar();
        }

        if (Config.didChange(e, 'pollingInterval')) {
            if (statusSubscription) {
                stopPolling();
                startPolling();
            }
        }

        if (Config.didChange(e, 'apiPort') || Config.didChange(e, 'apiHost')) {
            logger.info(`API endpoint changed to ${Config.apiBaseUrl}`);
            stopPolling();
            apiClient.dispose();
            apiClient = new LokiApiClient(Config.apiBaseUrl, { pollingInterval: Config.pollingInterval });
            startPolling();
        }
    });

    // Add disposables to context
    context.subscriptions.push(
        sessionsView,
        tasksView,
        checkpointsView,
        chatView,
        logsView,
        memoryView,
        dashboardView,
        statusBarItem,
        configListener,
        ...commands
    );

    // Auto-connect if workspace has .loki directory
    if (Config.autoConnect && hasLokiDirectory()) {
        logger.info('Found .loki directory, attempting to connect to API...');
        connectToApi().then(connected => {
            if (connected) {
                vscode.window.showInformationMessage('Connected to Loki Mode API');
            }
        });
    }

    // Initialize context
    updateContext();

    logger.info('Loki Mode extension activated');
}

/**
 * Extension deactivation
 */
export function deactivate(): void {
    logger.info('Deactivating Loki Mode extension...');
    stopPolling();
    if (logsViewProvider) {
        logsViewProvider.dispose();
    }
    if (chatViewProvider) {
        chatViewProvider.dispose();
    }
    if (memoryViewProvider) {
        memoryViewProvider.dispose();
    }
    if (dashboardWebviewProvider) {
        dashboardWebviewProvider.dispose();
    }
    if (apiClient) {
        apiClient.dispose();
    }
    // Dispose learning collector
    disposeLearningCollector();
    // Dispose file edit memory integration
    disposeFileEditMemoryIntegration();
    logger.info('Loki Mode extension deactivated');
    Logger.dispose();
}

import * as vscode from 'vscode';
import { DEFAULT_API_BASE_URL } from '../utils/constants';

/**
 * Represents the current Loki Mode session state
 */
export interface LokiSession {
    active: boolean;
    prdPath?: string;
    prdName?: string;
    provider: 'claude' | 'codex' | 'gemini';
    phase: string;
    startedAt?: string;
    pausedAt?: string;
    status: 'idle' | 'running' | 'paused' | 'error';
    errorMessage?: string;
    currentTask?: string;
    completedTasks: number;
    totalTasks: number;
}

/**
 * Tree item representing session information
 */
export class SessionItem extends vscode.TreeItem {
    constructor(
        public readonly label: string,
        public readonly value: string,
        public readonly icon?: string,
        public readonly contextValue?: string
    ) {
        super(label, vscode.TreeItemCollapsibleState.None);
        this.description = value;
        if (icon) {
            this.iconPath = new vscode.ThemeIcon(icon);
        }
        if (contextValue) {
            this.contextValue = contextValue;
        }
    }
}

/**
 * Tree data provider for Loki Mode session information
 * Shows PRD, provider, phase, duration, and current status
 */
export class SessionTreeProvider implements vscode.TreeDataProvider<SessionItem> {
    private _onDidChangeTreeData: vscode.EventEmitter<SessionItem | undefined | null | void> = new vscode.EventEmitter<SessionItem | undefined | null | void>();
    readonly onDidChangeTreeData: vscode.Event<SessionItem | undefined | null | void> = this._onDidChangeTreeData.event;

    private session: LokiSession = {
        active: false,
        provider: 'claude',
        phase: 'Idle',
        status: 'idle',
        completedTasks: 0,
        totalTasks: 0
    };

    private apiEndpoint: string;
    private durationInterval?: NodeJS.Timeout;

    constructor(apiEndpoint?: string) {
        this.apiEndpoint = apiEndpoint || DEFAULT_API_BASE_URL;
    }

    /**
     * Refresh session data from API
     */
    async refresh(): Promise<void> {
        try {
            await this.fetchSession();
        } catch (error) {
            console.error('Failed to fetch session:', error);
        }
        this._onDidChangeTreeData.fire();
    }

    /**
     * Update session directly (for use with WebSocket updates)
     */
    updateSession(session: Partial<LokiSession>): void {
        this.session = { ...this.session, ...session };
        this._onDidChangeTreeData.fire();
        this.updateDurationTimer();
    }

    /**
     * Get the current session state
     */
    getSession(): LokiSession {
        return { ...this.session };
    }

    /**
     * Check if a session is active
     */
    isActive(): boolean {
        return this.session.active;
    }

    /**
     * Set the API endpoint
     */
    setApiEndpoint(endpoint: string): void {
        this.apiEndpoint = endpoint;
    }

    getTreeItem(element: SessionItem): vscode.TreeItem {
        return element;
    }

    getChildren(element?: SessionItem): Thenable<SessionItem[]> {
        if (element) {
            return Promise.resolve([]);
        }

        if (!this.session.active) {
            return Promise.resolve(this.getWelcomeView());
        }

        return Promise.resolve(this.getSessionItems());
    }

    private getWelcomeView(): SessionItem[] {
        const items: SessionItem[] = [];

        const welcomeItem = new SessionItem(
            'No Active Session',
            'Start a session to begin',
            'play',
            'welcome'
        );
        items.push(welcomeItem);

        const startItem = new SessionItem(
            'Start Session',
            'Select a PRD file',
            'rocket',
            'start-action'
        );
        startItem.command = {
            command: 'loki.start',
            title: 'Start Loki Mode Session'
        };
        items.push(startItem);

        return items;
    }

    private getSessionItems(): SessionItem[] {
        const items: SessionItem[] = [];

        // Status with appropriate icon
        const statusIcon = this.getStatusIcon();
        const statusItem = new SessionItem(
            'Status',
            this.formatStatus(),
            statusIcon,
            `session-${this.session.status}`
        );
        items.push(statusItem);

        // PRD file
        if (this.session.prdName || this.session.prdPath) {
            const prdItem = new SessionItem(
                'PRD',
                this.session.prdName || this.session.prdPath || 'Unknown',
                'file-text',
                'session-prd'
            );
            if (this.session.prdPath) {
                prdItem.command = {
                    command: 'vscode.open',
                    title: 'Open PRD',
                    arguments: [vscode.Uri.file(this.session.prdPath)]
                };
            }
            items.push(prdItem);
        }

        // Provider
        const providerIcon = this.getProviderIcon();
        const providerItem = new SessionItem(
            'Provider',
            this.formatProvider(),
            providerIcon,
            'session-provider'
        );
        items.push(providerItem);

        // Current phase
        const phaseItem = new SessionItem(
            'Phase',
            this.session.phase || 'Starting',
            'layers',
            'session-phase'
        );
        items.push(phaseItem);

        // Task progress
        const progressItem = new SessionItem(
            'Progress',
            `${this.session.completedTasks}/${this.session.totalTasks} tasks`,
            'checklist',
            'session-progress'
        );
        items.push(progressItem);

        // Duration
        if (this.session.startedAt) {
            const durationItem = new SessionItem(
                'Duration',
                this.formatDuration(),
                'clock',
                'session-duration'
            );
            items.push(durationItem);
        }

        // Current task
        if (this.session.currentTask) {
            const taskItem = new SessionItem(
                'Current Task',
                this.session.currentTask,
                'sync~spin',
                'session-current-task'
            );
            items.push(taskItem);
        }

        // Error message if present
        if (this.session.errorMessage) {
            const errorItem = new SessionItem(
                'Error',
                this.session.errorMessage,
                'error',
                'session-error'
            );
            items.push(errorItem);
        }

        // Actions separator
        const actionsHeader = new SessionItem(
            '---',
            'Actions',
            undefined,
            undefined
        );
        items.push(actionsHeader);

        // Action buttons based on status
        if (this.session.status === 'running') {
            const pauseItem = new SessionItem(
                'Pause Session',
                '',
                'debug-pause',
                'pause-action'
            );
            pauseItem.command = {
                command: 'loki.pause',
                title: 'Pause Session'
            };
            items.push(pauseItem);
        }

        if (this.session.status === 'paused') {
            const resumeItem = new SessionItem(
                'Resume Session',
                '',
                'debug-continue',
                'resume-action'
            );
            resumeItem.command = {
                command: 'loki.resume',
                title: 'Resume Session'
            };
            items.push(resumeItem);
        }

        if (this.session.active) {
            const stopItem = new SessionItem(
                'Stop Session',
                '',
                'debug-stop',
                'stop-action'
            );
            stopItem.command = {
                command: 'loki.stop',
                title: 'Stop Session'
            };
            items.push(stopItem);
        }

        return items;
    }

    private getStatusIcon(): string {
        switch (this.session.status) {
            case 'running':
                return 'sync~spin';
            case 'paused':
                return 'debug-pause';
            case 'error':
                return 'error';
            case 'idle':
            default:
                return 'circle-outline';
        }
    }

    private formatStatus(): string {
        switch (this.session.status) {
            case 'running':
                return 'Running';
            case 'paused':
                return 'Paused';
            case 'error':
                return 'Error';
            case 'idle':
            default:
                return 'Idle';
        }
    }

    private getProviderIcon(): string {
        switch (this.session.provider) {
            case 'claude':
                return 'hubot';
            case 'codex':
                return 'beaker';
            case 'gemini':
                return 'sparkle';
            default:
                return 'robot';
        }
    }

    private formatProvider(): string {
        switch (this.session.provider) {
            case 'claude':
                return 'Claude Code';
            case 'codex':
                return 'OpenAI Codex';
            case 'gemini':
                return 'Google Gemini';
            default:
                return this.session.provider;
        }
    }

    private formatDuration(): string {
        if (!this.session.startedAt) {
            return '0:00';
        }

        const start = new Date(this.session.startedAt).getTime();
        const now = Date.now();
        const diffMs = now - start;

        const seconds = Math.floor(diffMs / 1000);
        const minutes = Math.floor(seconds / 60);
        const hours = Math.floor(minutes / 60);

        if (hours > 0) {
            return `${hours}:${String(minutes % 60).padStart(2, '0')}:${String(seconds % 60).padStart(2, '0')}`;
        }
        return `${minutes}:${String(seconds % 60).padStart(2, '0')}`;
    }

    private updateDurationTimer(): void {
        // Clear existing timer
        if (this.durationInterval) {
            clearInterval(this.durationInterval);
            this.durationInterval = undefined;
        }

        // Start new timer if session is running
        if (this.session.active && this.session.status === 'running') {
            this.durationInterval = setInterval(() => {
                this._onDidChangeTreeData.fire();
            }, 1000);
        }
    }

    private async fetchSession(): Promise<void> {
        try {
            const response = await fetch(`${this.apiEndpoint}/api/status`);
            if (response.ok) {
                const rawData = await response.json() as Record<string, unknown>;
                // server.py /api/status returns: status, version, uptime_seconds,
                // active_sessions, running_agents, pending_tasks, phase, iteration,
                // complexity, mode, provider, current_task
                const serverStatus = typeof rawData.status === 'string' ? rawData.status : '';
                const isRunning = serverStatus === 'running' || serverStatus === 'autonomous';
                const isPaused = serverStatus === 'paused';
                let status: 'idle' | 'running' | 'paused' | 'error' = 'idle';
                if (isPaused) { status = 'paused'; }
                else if (isRunning) { status = 'running'; }
                else if (serverStatus === 'stopped') { status = 'idle'; }
                const pendingTasks = typeof rawData.pending_tasks === 'number' ? rawData.pending_tasks : 0;
                const provider = typeof rawData.provider === 'string' ? rawData.provider : 'claude';
                const phase = typeof rawData.phase === 'string' && rawData.phase ? rawData.phase : 'Idle';
                const currentTask = typeof rawData.current_task === 'string' ? rawData.current_task : undefined;
                this.session = {
                    active: isRunning || isPaused,
                    provider: (provider as 'claude' | 'codex' | 'gemini') ?? 'claude',
                    phase,
                    status,
                    currentTask,
                    completedTasks: 0,
                    totalTasks: pendingTasks
                };
                this.updateDurationTimer();
            } else {
                // API returned error - session may not exist
                this.session = {
                    active: false,
                    provider: 'claude',
                    phase: 'Idle',
                    status: 'idle',
                    completedTasks: 0,
                    totalTasks: 0
                };
            }
        } catch (error) {
            // API not available - this is normal when no session is running
            console.debug('Session API not available:', error);
            this.session = {
                active: false,
                provider: 'claude',
                phase: 'Idle',
                status: 'idle',
                completedTasks: 0,
                totalTasks: 0
            };
        }
    }

    /**
     * Dispose of resources
     */
    dispose(): void {
        if (this.durationInterval) {
            clearInterval(this.durationInterval);
        }
    }
}

import * as vscode from 'vscode';
import { DEFAULT_API_BASE_URL } from '../utils/constants';
import { parseTasksResponse } from '../api/validators';

/**
 * Represents a task in the Loki Mode task tree
 */
export interface LokiTask {
    id: string;
    title: string;
    description: string;
    status: 'in_progress' | 'pending' | 'completed';
    startedAt?: string;
    completedAt?: string;
}

/**
 * Tree item representing a task or status group
 */
export class TaskItem extends vscode.TreeItem {
    constructor(
        public readonly label: string,
        public readonly collapsibleState: vscode.TreeItemCollapsibleState,
        public readonly task?: LokiTask,
        public readonly isGroup: boolean = false
    ) {
        super(label, collapsibleState);

        if (task) {
            this.tooltip = task.description;
            this.description = this.getStatusDescription(task.status);
            this.contextValue = `task-${task.status}`;
            this.iconPath = this.getStatusIcon(task.status);
            this.id = task.id;
        } else if (isGroup) {
            this.contextValue = 'taskGroup';
        }
    }

    private getStatusIcon(status: string): vscode.ThemeIcon {
        switch (status) {
            case 'in_progress':
                return new vscode.ThemeIcon('sync~spin', new vscode.ThemeColor('charts.yellow'));
            case 'pending':
                return new vscode.ThemeIcon('circle-outline', new vscode.ThemeColor('charts.blue'));
            case 'completed':
                return new vscode.ThemeIcon('check', new vscode.ThemeColor('charts.green'));
            default:
                return new vscode.ThemeIcon('circle-outline');
        }
    }

    private getStatusDescription(status: string): string {
        switch (status) {
            case 'in_progress':
                return 'Running';
            case 'pending':
                return 'Waiting';
            case 'completed':
                return 'Done';
            default:
                return '';
        }
    }
}

/**
 * Tree data provider for Loki Mode tasks
 * Groups tasks by status: In Progress, Pending, Completed
 */
export class TaskTreeProvider implements vscode.TreeDataProvider<TaskItem> {
    private _onDidChangeTreeData: vscode.EventEmitter<TaskItem | undefined | null | void> = new vscode.EventEmitter<TaskItem | undefined | null | void>();
    readonly onDidChangeTreeData: vscode.Event<TaskItem | undefined | null | void> = this._onDidChangeTreeData.event;

    private tasks: LokiTask[] = [];
    private apiEndpoint: string;

    constructor(apiEndpoint?: string) {
        this.apiEndpoint = apiEndpoint || DEFAULT_API_BASE_URL;
    }

    /**
     * Refresh the task tree by fetching latest data from API
     */
    async refresh(): Promise<void> {
        try {
            await this.fetchTasks();
        } catch (error) {
            console.error('Failed to fetch tasks:', error);
        }
        this._onDidChangeTreeData.fire();
    }

    /**
     * Update tasks directly (for use with WebSocket updates)
     */
    updateTasks(tasks: LokiTask[]): void {
        this.tasks = tasks;
        this._onDidChangeTreeData.fire();
    }

    /**
     * Set the API endpoint
     */
    setApiEndpoint(endpoint: string): void {
        this.apiEndpoint = endpoint;
    }

    /**
     * Get the count of tasks by status
     */
    getTaskCounts(): { inProgress: number; pending: number; completed: number; total: number } {
        const inProgress = this.tasks.filter(t => t.status === 'in_progress').length;
        const pending = this.tasks.filter(t => t.status === 'pending').length;
        const completed = this.tasks.filter(t => t.status === 'completed').length;
        return {
            inProgress,
            pending,
            completed,
            total: this.tasks.length
        };
    }

    getTreeItem(element: TaskItem): vscode.TreeItem {
        return element;
    }

    getChildren(element?: TaskItem): Thenable<TaskItem[]> {
        if (!element) {
            // Root level - return status groups
            return Promise.resolve(this.getStatusGroups());
        }

        // Return tasks for this status group
        return Promise.resolve(this.getTasksForGroup(element.label as string));
    }

    private getStatusGroups(): TaskItem[] {
        const groups: TaskItem[] = [];
        const counts = this.getTaskCounts();

        // Only show groups that have tasks
        if (counts.inProgress > 0) {
            const item = new TaskItem(
                'In Progress',
                vscode.TreeItemCollapsibleState.Expanded,
                undefined,
                true
            );
            item.iconPath = new vscode.ThemeIcon('sync~spin', new vscode.ThemeColor('charts.yellow'));
            item.description = `${counts.inProgress}`;
            groups.push(item);
        }

        if (counts.pending > 0) {
            const item = new TaskItem(
                'Pending',
                vscode.TreeItemCollapsibleState.Expanded,
                undefined,
                true
            );
            item.iconPath = new vscode.ThemeIcon('circle-outline', new vscode.ThemeColor('charts.blue'));
            item.description = `${counts.pending}`;
            groups.push(item);
        }

        if (counts.completed > 0) {
            const item = new TaskItem(
                'Completed',
                vscode.TreeItemCollapsibleState.Collapsed,
                undefined,
                true
            );
            item.iconPath = new vscode.ThemeIcon('check', new vscode.ThemeColor('charts.green'));
            item.description = `${counts.completed}`;
            groups.push(item);
        }

        // Show empty state if no tasks
        if (groups.length === 0) {
            const emptyItem = new TaskItem(
                'No tasks yet',
                vscode.TreeItemCollapsibleState.None,
                undefined,
                false
            );
            emptyItem.iconPath = new vscode.ThemeIcon('info');
            emptyItem.description = 'Start a session to see tasks';
            groups.push(emptyItem);
        }

        return groups;
    }

    private getTasksForGroup(groupLabel: string): TaskItem[] {
        let statusFilter: string;

        switch (groupLabel) {
            case 'In Progress':
                statusFilter = 'in_progress';
                break;
            case 'Pending':
                statusFilter = 'pending';
                break;
            case 'Completed':
                statusFilter = 'completed';
                break;
            default:
                return [];
        }

        return this.tasks
            .filter(task => task.status === statusFilter)
            .map(task => new TaskItem(
                task.title,
                vscode.TreeItemCollapsibleState.None,
                task,
                false
            ));
    }

    private async fetchTasks(): Promise<void> {
        try {
            const response = await fetch(`${this.apiEndpoint}/tasks`);
            if (response.ok) {
                const rawData = await response.json();
                const data = parseTasksResponse(rawData);
                this.tasks = (data.tasks || []) as LokiTask[];
            } else {
                // API not available or error - keep existing tasks
                console.warn('Task API returned non-OK status:', response.status);
            }
        } catch (error) {
            // API not available - this is normal when no session is running
            console.debug('Task API not available:', error);
        }
    }
}

/**
 * Loki Mode Learning Collector Service
 *
 * Collects learning signals from VS Code extension operations and
 * writes them to .loki/learning/signals/ for cross-tool learning.
 *
 * Implements SYN-020 from the SYNERGY-ROADMAP.
 */

import * as vscode from 'vscode';
import * as fs from 'fs';
import * as path from 'path';
import { logger } from '../utils/logger';

// -----------------------------------------------------------------------------
// Signal Types (matches learning/signals.ts)
// -----------------------------------------------------------------------------

export const SignalType = {
  USER_PREFERENCE: 'user_preference',
  ERROR_PATTERN: 'error_pattern',
  SUCCESS_PATTERN: 'success_pattern',
  WORKFLOW_PATTERN: 'workflow_pattern',
} as const;

export type SignalType = (typeof SignalType)[keyof typeof SignalType];

export const SignalSource = {
  VSCODE: 'vscode',
} as const;

export type SignalSource = (typeof SignalSource)[keyof typeof SignalSource];

export const Outcome = {
  SUCCESS: 'success',
  FAILURE: 'failure',
  PARTIAL: 'partial',
  UNKNOWN: 'unknown',
} as const;

export type Outcome = (typeof Outcome)[keyof typeof Outcome];

// -----------------------------------------------------------------------------
// Signal Interfaces
// -----------------------------------------------------------------------------

interface LearningSignal {
  id: string;
  type: SignalType;
  source: SignalSource;
  action: string;
  context: Record<string, unknown>;
  outcome: Outcome;
  confidence: number;
  timestamp: string;
  metadata: Record<string, unknown>;
}

interface UserPreferenceSignal extends LearningSignal {
  type: typeof SignalType.USER_PREFERENCE;
  preference_key: string;
  preference_value: unknown;
  alternatives_rejected: unknown[];
}

interface ErrorPatternSignal extends LearningSignal {
  type: typeof SignalType.ERROR_PATTERN;
  error_type: string;
  error_message: string;
  resolution: string;
  stack_trace?: string;
  recovery_steps: string[];
}

interface SuccessPatternSignal extends LearningSignal {
  type: typeof SignalType.SUCCESS_PATTERN;
  pattern_name: string;
  action_sequence: string[];
  preconditions: string[];
  postconditions: string[];
  duration_seconds: number;
}

interface WorkflowPatternSignal extends LearningSignal {
  type: typeof SignalType.WORKFLOW_PATTERN;
  workflow_name: string;
  steps: string[];
  parallel_steps: string[][];
  branching_conditions: Record<string, string>;
  total_duration_seconds: number;
}

// -----------------------------------------------------------------------------
// Utility Functions
// -----------------------------------------------------------------------------

function generateId(): string {
  return 'sig-' + Math.random().toString(36).substring(2, 10);
}

function getTimestamp(): string {
  return new Date().toISOString();
}

// -----------------------------------------------------------------------------
// Learning Collector Class
// -----------------------------------------------------------------------------

/**
 * LearningCollector service for VS Code extension.
 *
 * Tracks user behaviors and emits learning signals:
 * - Command usage (most used commands)
 * - File edits (which files are edited)
 * - Panel views (which views are opened)
 * - Error patterns (extension errors)
 * - Success patterns (successful operations)
 * - Workflow patterns (multi-step workflows)
 */
export class LearningCollector implements vscode.Disposable {
  private lokiDir: string | null = null;
  private commandUsage: Map<string, number> = new Map();
  private fileEdits: Map<string, number> = new Map();
  private panelViews: Map<string, number> = new Map();
  private workflowStartTimes: Map<string, number> = new Map();
  private workflowSteps: Map<string, string[]> = new Map();
  private disposables: vscode.Disposable[] = [];
  private writeQueue: LearningSignal[] = [];
  private isWriting = false;

  constructor() {
    this.initializeLokiDir();
    this.setupEventListeners();
  }

  /**
   * Initialize the .loki directory path from workspace
   */
  private initializeLokiDir(): void {
    const workspaceFolders = vscode.workspace.workspaceFolders;
    if (workspaceFolders && workspaceFolders.length > 0) {
      this.lokiDir = path.join(workspaceFolders[0].uri.fsPath, '.loki');
    }
  }

  /**
   * Setup VS Code event listeners for automatic signal collection
   */
  private setupEventListeners(): void {
    // Track document changes (file edits)
    this.disposables.push(
      vscode.workspace.onDidChangeTextDocument((event) => {
        if (event.document.uri.scheme === 'file') {
          this.trackFileEdit(event.document.uri.fsPath);
        }
      })
    );

    // Track active editor changes (panel views)
    this.disposables.push(
      vscode.window.onDidChangeActiveTextEditor((editor) => {
        if (editor && editor.document.uri.scheme === 'file') {
          this.trackPanelView(editor.document.uri.fsPath);
        }
      })
    );

    // Track workspace folder changes
    this.disposables.push(
      vscode.workspace.onDidChangeWorkspaceFolders(() => {
        this.initializeLokiDir();
      })
    );

    logger.debug('LearningCollector: Event listeners initialized');
  }

  /**
   * Get the signals directory, creating it if necessary
   */
  private getSignalsDir(): string | null {
    if (!this.lokiDir) {
      return null;
    }

    const signalsDir = path.join(this.lokiDir, 'learning', 'signals');

    try {
      if (!fs.existsSync(signalsDir)) {
        fs.mkdirSync(signalsDir, { recursive: true });
      }
      return signalsDir;
    } catch (error) {
      logger.error('LearningCollector: Failed to create signals directory', error);
      return null;
    }
  }

  /**
   * Non-blocking async signal emission
   */
  private async emitSignalAsync(signal: LearningSignal): Promise<void> {
    this.writeQueue.push(signal);
    this.processWriteQueue();
  }

  /**
   * Process the write queue without blocking
   */
  private async processWriteQueue(): Promise<void> {
    if (this.isWriting || this.writeQueue.length === 0) {
      return;
    }

    this.isWriting = true;

    try {
      while (this.writeQueue.length > 0) {
        const signal = this.writeQueue.shift();
        if (signal) {
          await this.writeSignal(signal);
        }
      }
    } finally {
      this.isWriting = false;
    }
  }

  /**
   * Write a signal to disk
   */
  private async writeSignal(signal: LearningSignal): Promise<void> {
    const signalsDir = this.getSignalsDir();
    if (!signalsDir) {
      logger.debug('LearningCollector: No signals directory available');
      return;
    }

    const timestampStr = signal.timestamp.replace(/:/g, '-');
    const signalFile = path.join(signalsDir, `${timestampStr}_${signal.id}.json`);

    try {
      await fs.promises.writeFile(signalFile, JSON.stringify(signal, null, 2));
      logger.debug(`LearningCollector: Signal emitted ${signal.id} (${signal.type})`);
    } catch (error) {
      logger.error(`LearningCollector: Failed to write signal ${signal.id}`, error);
    }
  }

  // ---------------------------------------------------------------------------
  // Public Signal Emission Methods
  // ---------------------------------------------------------------------------

  /**
   * Track command execution and emit UserPreferenceSignal
   */
  trackCommand(commandId: string, alternatives: string[] = []): void {
    const count = (this.commandUsage.get(commandId) || 0) + 1;
    this.commandUsage.set(commandId, count);

    const signal: UserPreferenceSignal = {
      id: generateId(),
      type: SignalType.USER_PREFERENCE,
      source: SignalSource.VSCODE,
      action: 'command_executed',
      context: {
        commandId,
        executionCount: count,
        editor: vscode.window.activeTextEditor?.document.languageId || 'unknown',
      },
      outcome: Outcome.SUCCESS,
      confidence: 0.9,
      timestamp: getTimestamp(),
      metadata: {
        vscodeVersion: vscode.version,
      },
      preference_key: 'command_choice',
      preference_value: commandId,
      alternatives_rejected: alternatives,
    };

    this.emitSignalAsync(signal);
  }

  /**
   * Emit UserPreferenceSignal for user settings changes
   */
  emitUserPreference(
    preferenceKey: string,
    preferenceValue: unknown,
    alternativesRejected: unknown[] = [],
    context: Record<string, unknown> = {}
  ): void {
    const signal: UserPreferenceSignal = {
      id: generateId(),
      type: SignalType.USER_PREFERENCE,
      source: SignalSource.VSCODE,
      action: 'preference_set',
      context: {
        ...context,
        editor: vscode.window.activeTextEditor?.document.languageId || 'unknown',
      },
      outcome: Outcome.SUCCESS,
      confidence: 0.9,
      timestamp: getTimestamp(),
      metadata: {
        vscodeVersion: vscode.version,
      },
      preference_key: preferenceKey,
      preference_value: preferenceValue,
      alternatives_rejected: alternativesRejected,
    };

    this.emitSignalAsync(signal);
  }

  /**
   * Track file edits
   */
  private trackFileEdit(filePath: string): void {
    const relativePath = this.getRelativePath(filePath);
    const count = (this.fileEdits.get(relativePath) || 0) + 1;
    this.fileEdits.set(relativePath, count);

    // Only emit signals for significant edit counts to reduce noise
    if (count % 10 === 0) {
      this.emitUserPreference(
        'file_edit_frequency',
        { path: relativePath, editCount: count },
        [],
        { fileType: path.extname(filePath) }
      );
    }
  }

  /**
   * Track panel/view opens
   */
  private trackPanelView(filePath: string): void {
    const relativePath = this.getRelativePath(filePath);
    const count = (this.panelViews.get(relativePath) || 0) + 1;
    this.panelViews.set(relativePath, count);
  }

  /**
   * Track custom panel view (for webviews and custom views)
   */
  trackPanelViewCustom(panelId: string): void {
    const count = (this.panelViews.get(panelId) || 0) + 1;
    this.panelViews.set(panelId, count);

    this.emitUserPreference(
      'panel_view',
      { panelId, viewCount: count },
      [],
      { panelType: 'custom' }
    );
  }

  /**
   * Emit ErrorPatternSignal for extension errors
   */
  emitErrorPattern(
    errorType: string,
    errorMessage: string,
    options: {
      resolution?: string;
      stackTrace?: string;
      recoverySteps?: string[];
      context?: Record<string, unknown>;
    } = {}
  ): void {
    const signal: ErrorPatternSignal = {
      id: generateId(),
      type: SignalType.ERROR_PATTERN,
      source: SignalSource.VSCODE,
      action: 'error_occurred',
      context: {
        ...options.context,
        editor: vscode.window.activeTextEditor?.document.languageId || 'unknown',
      },
      outcome: options.resolution ? Outcome.SUCCESS : Outcome.FAILURE,
      confidence: 0.8,
      timestamp: getTimestamp(),
      metadata: {
        vscodeVersion: vscode.version,
      },
      error_type: errorType,
      error_message: errorMessage,
      resolution: options.resolution || '',
      stack_trace: options.stackTrace,
      recovery_steps: options.recoverySteps || [],
    };

    this.emitSignalAsync(signal);
  }

  /**
   * Emit SuccessPatternSignal for successful operations
   */
  emitSuccessPattern(
    patternName: string,
    actionSequence: string[],
    options: {
      preconditions?: string[];
      postconditions?: string[];
      durationSeconds?: number;
      context?: Record<string, unknown>;
    } = {}
  ): void {
    const signal: SuccessPatternSignal = {
      id: generateId(),
      type: SignalType.SUCCESS_PATTERN,
      source: SignalSource.VSCODE,
      action: 'operation_succeeded',
      context: {
        ...options.context,
        editor: vscode.window.activeTextEditor?.document.languageId || 'unknown',
      },
      outcome: Outcome.SUCCESS,
      confidence: 0.85,
      timestamp: getTimestamp(),
      metadata: {
        vscodeVersion: vscode.version,
      },
      pattern_name: patternName,
      action_sequence: actionSequence,
      preconditions: options.preconditions || [],
      postconditions: options.postconditions || [],
      duration_seconds: options.durationSeconds || 0,
    };

    this.emitSignalAsync(signal);
  }

  /**
   * Start tracking a multi-step workflow
   */
  startWorkflow(workflowName: string): void {
    this.workflowStartTimes.set(workflowName, Date.now());
    this.workflowSteps.set(workflowName, []);
    logger.debug(`LearningCollector: Started workflow ${workflowName}`);
  }

  /**
   * Add a step to an active workflow
   */
  addWorkflowStep(workflowName: string, stepName: string): void {
    const steps = this.workflowSteps.get(workflowName);
    if (steps) {
      steps.push(stepName);
    }
  }

  /**
   * Complete a workflow and emit WorkflowPatternSignal
   */
  completeWorkflow(
    workflowName: string,
    options: {
      outcome?: Outcome;
      parallelSteps?: string[][];
      branchingConditions?: Record<string, string>;
      context?: Record<string, unknown>;
    } = {}
  ): void {
    const startTime = this.workflowStartTimes.get(workflowName);
    const steps = this.workflowSteps.get(workflowName);

    if (!startTime || !steps) {
      logger.warn(`LearningCollector: Unknown workflow ${workflowName}`);
      return;
    }

    const durationSeconds = (Date.now() - startTime) / 1000;

    const signal: WorkflowPatternSignal = {
      id: generateId(),
      type: SignalType.WORKFLOW_PATTERN,
      source: SignalSource.VSCODE,
      action: 'workflow_completed',
      context: {
        ...options.context,
        editor: vscode.window.activeTextEditor?.document.languageId || 'unknown',
      },
      outcome: options.outcome || Outcome.SUCCESS,
      confidence: 0.85,
      timestamp: getTimestamp(),
      metadata: {
        vscodeVersion: vscode.version,
      },
      workflow_name: workflowName,
      steps,
      parallel_steps: options.parallelSteps || [],
      branching_conditions: options.branchingConditions || {},
      total_duration_seconds: durationSeconds,
    };

    this.emitSignalAsync(signal);

    // Clean up workflow tracking
    this.workflowStartTimes.delete(workflowName);
    this.workflowSteps.delete(workflowName);

    logger.debug(`LearningCollector: Completed workflow ${workflowName} (${durationSeconds}s)`);
  }

  /**
   * Cancel a workflow without emitting a signal
   */
  cancelWorkflow(workflowName: string): void {
    this.workflowStartTimes.delete(workflowName);
    this.workflowSteps.delete(workflowName);
    logger.debug(`LearningCollector: Cancelled workflow ${workflowName}`);
  }

  // ---------------------------------------------------------------------------
  // Utility Methods
  // ---------------------------------------------------------------------------

  /**
   * Get relative path from workspace root
   */
  private getRelativePath(filePath: string): string {
    const workspaceFolders = vscode.workspace.workspaceFolders;
    if (workspaceFolders && workspaceFolders.length > 0) {
      const workspaceRoot = workspaceFolders[0].uri.fsPath;
      if (filePath.startsWith(workspaceRoot)) {
        return filePath.substring(workspaceRoot.length + 1);
      }
    }
    return path.basename(filePath);
  }

  /**
   * Get usage statistics
   */
  getStatistics(): {
    commandUsage: Record<string, number>;
    fileEdits: Record<string, number>;
    panelViews: Record<string, number>;
  } {
    return {
      commandUsage: Object.fromEntries(this.commandUsage),
      fileEdits: Object.fromEntries(this.fileEdits),
      panelViews: Object.fromEntries(this.panelViews),
    };
  }

  /**
   * Get most used commands
   */
  getMostUsedCommands(limit = 10): Array<{ command: string; count: number }> {
    return Array.from(this.commandUsage.entries())
      .sort((a, b) => b[1] - a[1])
      .slice(0, limit)
      .map(([command, count]) => ({ command, count }));
  }

  /**
   * Get most edited files
   */
  getMostEditedFiles(limit = 10): Array<{ file: string; count: number }> {
    return Array.from(this.fileEdits.entries())
      .sort((a, b) => b[1] - a[1])
      .slice(0, limit)
      .map(([file, count]) => ({ file, count }));
  }

  /**
   * Dispose and clean up resources
   */
  dispose(): void {
    this.disposables.forEach((d) => d.dispose());
    this.disposables = [];
    logger.debug('LearningCollector: Disposed');
  }
}

// -----------------------------------------------------------------------------
// Singleton Instance
// -----------------------------------------------------------------------------

let instance: LearningCollector | null = null;

/**
 * Get the singleton LearningCollector instance
 */
export function getLearningCollector(): LearningCollector {
  if (!instance) {
    instance = new LearningCollector();
  }
  return instance;
}

/**
 * Dispose the singleton instance
 */
export function disposeLearningCollector(): void {
  if (instance) {
    instance.dispose();
    instance = null;
  }
}

/**
 * Loki Mode Memory Integration Service
 *
 * Integrates VS Code file edits with the Loki memory system.
 * Records meaningful code changes as episodic memories for cross-tool learning.
 *
 * Implements SYN-011 from the SYNERGY-ROADMAP.
 */

import * as vscode from 'vscode';
import * as fs from 'fs';
import * as path from 'path';
import { logger } from '../utils/logger';

// -----------------------------------------------------------------------------
// Types and Interfaces
// -----------------------------------------------------------------------------

/**
 * Change types for file edits
 */
export const ChangeType = {
  ADDITION: 'addition',
  DELETION: 'deletion',
  MODIFICATION: 'modification',
  REFACTOR: 'refactor',
} as const;

export type ChangeType = (typeof ChangeType)[keyof typeof ChangeType];

/**
 * A single code change within a file edit
 */
interface CodeChange {
  rangeOffset: number;
  rangeLength: number;
  text: string;
  lineNumber: number;
  changeType: ChangeType;
}

/**
 * Aggregated edit for a file within the debounce window
 */
interface AggregatedEdit {
  filePath: string;
  relativePath: string;
  languageId: string;
  changes: CodeChange[];
  firstChangeTime: number;
  lastChangeTime: number;
  linesAdded: number;
  linesDeleted: number;
  charactersAdded: number;
  charactersDeleted: number;
}

/**
 * Episode trace format for memory storage (matches memory/schemas.py)
 */
interface EpisodeTrace {
  id: string;
  task_id: string;
  timestamp: string;
  duration_seconds: number;
  agent: string;
  context: {
    phase: string;
    goal: string;
    files_involved: string[];
  };
  action_log: Array<{
    t: number;
    action: string;
    target: string;
    result: string;
  }>;
  outcome: 'success' | 'failure' | 'partial';
  errors_encountered: Array<{
    type: string;
    message: string;
    resolution: string;
  }>;
  artifacts_produced: string[];
  files_read: string[];
  files_modified: string[];
  importance: number;
  access_count: number;
  // Extension-specific fields for code edits
  task_type?: string;
  edit_summary?: {
    change_type: ChangeType;
    lines_added: number;
    lines_deleted: number;
    characters_added: number;
    characters_deleted: number;
    patterns_detected: string[];
  };
  surrounding_context?: {
    before: string;
    after: string;
  };
}

/**
 * Edit pattern statistics
 */
interface EditPatternStats {
  fileEditCounts: Map<string, number>;
  changeTypeCounts: Map<ChangeType, number>;
  hourlyActivity: Map<number, number>;
  languageEditCounts: Map<string, number>;
  lastUpdated: number;
}

// -----------------------------------------------------------------------------
// Utility Functions
// -----------------------------------------------------------------------------

function generateId(): string {
  const timestamp = new Date().toISOString().slice(0, 10).replace(/-/g, '');
  const random = Math.random().toString(36).substring(2, 10);
  return `ep-${timestamp}-${random}`;
}

function getTimestamp(): string {
  return new Date().toISOString();
}

/**
 * Determine the change type based on content changes
 */
function detectChangeType(
  addedChars: number,
  deletedChars: number,
  addedLines: number,
  deletedLines: number
): ChangeType {
  // Pure addition
  if (deletedChars === 0 && addedChars > 0) {
    return ChangeType.ADDITION;
  }

  // Pure deletion
  if (addedChars === 0 && deletedChars > 0) {
    return ChangeType.DELETION;
  }

  // Refactor: similar amount of content changed (within 20% ratio)
  if (addedChars > 0 && deletedChars > 0) {
    const ratio = Math.min(addedChars, deletedChars) / Math.max(addedChars, deletedChars);
    if (ratio > 0.8 && (addedLines === deletedLines || Math.abs(addedLines - deletedLines) <= 2)) {
      return ChangeType.REFACTOR;
    }
  }

  return ChangeType.MODIFICATION;
}

/**
 * Detect code patterns in the edited content
 */
function detectCodePatterns(changes: CodeChange[], languageId: string): string[] {
  const patterns: string[] = [];
  const allText = changes.map((c) => c.text).join('\n');

  // Language-specific patterns
  if (languageId === 'typescript' || languageId === 'javascript') {
    if (/\bfunction\s+\w+/.test(allText)) patterns.push('function_definition');
    if (/\bclass\s+\w+/.test(allText)) patterns.push('class_definition');
    if (/\basync\b/.test(allText)) patterns.push('async_code');
    if (/\bawait\b/.test(allText)) patterns.push('await_usage');
    if (/\bimport\s+/.test(allText)) patterns.push('import_statement');
    if (/\bexport\s+/.test(allText)) patterns.push('export_statement');
    if (/\btry\s*\{/.test(allText)) patterns.push('error_handling');
    if (/\bcatch\s*\(/.test(allText)) patterns.push('error_handling');
    if (/\bthrow\s+/.test(allText)) patterns.push('error_throwing');
    if (/\binterface\s+\w+/.test(allText)) patterns.push('interface_definition');
    if (/\btype\s+\w+\s*=/.test(allText)) patterns.push('type_alias');
    if (/\b(describe|it|test)\s*\(/.test(allText)) patterns.push('test_code');
  }

  if (languageId === 'python') {
    if (/\bdef\s+\w+/.test(allText)) patterns.push('function_definition');
    if (/\bclass\s+\w+/.test(allText)) patterns.push('class_definition');
    if (/\basync\s+def\b/.test(allText)) patterns.push('async_code');
    if (/\bawait\b/.test(allText)) patterns.push('await_usage');
    if (/\bimport\s+/.test(allText)) patterns.push('import_statement');
    if (/\bfrom\s+\w+\s+import/.test(allText)) patterns.push('import_statement');
    if (/\btry\s*:/.test(allText)) patterns.push('error_handling');
    if (/\bexcept\s+/.test(allText)) patterns.push('error_handling');
    if (/\braise\s+/.test(allText)) patterns.push('error_throwing');
    if (/\bdef\s+test_/.test(allText)) patterns.push('test_code');
    if (/@\w+/.test(allText)) patterns.push('decorator_usage');
  }

  // Generic patterns
  if (/TODO|FIXME|HACK|XXX/.test(allText)) patterns.push('todo_comment');
  if (/\bconsole\.(log|error|warn|debug)/.test(allText)) patterns.push('debug_logging');
  if (/\bprint\s*\(/.test(allText) && languageId === 'python') patterns.push('debug_logging');

  return [...new Set(patterns)]; // Remove duplicates
}

/**
 * Check if a change is meaningful (not just whitespace)
 */
function isMeaningfulChange(change: CodeChange): boolean {
  const text = change.text;

  // Empty change
  if (text.length === 0 && change.rangeLength === 0) {
    return false;
  }

  // Pure whitespace
  if (/^\s*$/.test(text) && change.rangeLength === 0) {
    return false;
  }

  // Single character (likely typing)
  if (text.length === 1 && change.rangeLength === 0) {
    return false;
  }

  return true;
}

// -----------------------------------------------------------------------------
// FileEditMemoryIntegration Class
// -----------------------------------------------------------------------------

/**
 * FileEditMemoryIntegration service for VS Code extension.
 *
 * Tracks meaningful file edits and stores them as episodic memories:
 * - Debounces rapid edits (aggregates within 5s window)
 * - Filters out whitespace-only changes
 * - Detects code patterns and change types
 * - Tracks edit statistics for pattern analysis
 */
export class FileEditMemoryIntegration implements vscode.Disposable {
  private lokiDir: string | null = null;
  private disposables: vscode.Disposable[] = [];
  private pendingEdits: Map<string, AggregatedEdit> = new Map();
  private debounceTimers: Map<string, ReturnType<typeof setTimeout>> = new Map();
  private stats: EditPatternStats;
  private writeQueue: EpisodeTrace[] = [];
  private isWriting = false;

  // Configuration
  private readonly DEBOUNCE_MS = 5000; // 5 second debounce window
  private readonly MIN_CHANGES_TO_RECORD = 1; // Minimum number of meaningful changes
  private readonly CONTEXT_LINES = 3; // Lines of context to capture

  constructor() {
    this.stats = {
      fileEditCounts: new Map(),
      changeTypeCounts: new Map(),
      hourlyActivity: new Map(),
      languageEditCounts: new Map(),
      lastUpdated: Date.now(),
    };

    this.initializeLokiDir();
    this.setupEventListeners();
  }

  /**
   * Initialize the .loki directory path from workspace
   */
  private initializeLokiDir(): void {
    const workspaceFolders = vscode.workspace.workspaceFolders;
    if (workspaceFolders && workspaceFolders.length > 0) {
      this.lokiDir = path.join(workspaceFolders[0].uri.fsPath, '.loki');
    }
  }

  /**
   * Setup VS Code event listeners for text document changes
   */
  private setupEventListeners(): void {
    // Track document changes
    this.disposables.push(
      vscode.workspace.onDidChangeTextDocument((event) => {
        if (event.document.uri.scheme === 'file') {
          this.handleDocumentChange(event);
        }
      })
    );

    // Track document saves (trigger flush for that file)
    this.disposables.push(
      vscode.workspace.onDidSaveTextDocument((document) => {
        if (document.uri.scheme === 'file') {
          this.flushPendingEdit(document.uri.fsPath);
        }
      })
    );

    // Track workspace folder changes
    this.disposables.push(
      vscode.workspace.onDidChangeWorkspaceFolders(() => {
        this.initializeLokiDir();
      })
    );

    logger.debug('FileEditMemoryIntegration: Event listeners initialized');
  }

  /**
   * Handle a text document change event
   */
  private handleDocumentChange(event: vscode.TextDocumentChangeEvent): void {
    const filePath = event.document.uri.fsPath;
    const relativePath = this.getRelativePath(filePath);

    // Skip non-workspace files and certain file types
    if (this.shouldSkipFile(filePath)) {
      return;
    }

    // Process each content change
    for (const change of event.contentChanges) {
      const lineNumber = change.range.start.line + 1;
      const addedText = change.text;
      const deletedLength = change.rangeLength;

      // Determine change type for this individual change
      const changeType: ChangeType =
        deletedLength === 0
          ? ChangeType.ADDITION
          : addedText.length === 0
            ? ChangeType.DELETION
            : ChangeType.MODIFICATION;

      const codeChange: CodeChange = {
        rangeOffset: change.rangeOffset,
        rangeLength: change.rangeLength,
        text: change.text,
        lineNumber,
        changeType,
      };

      // Skip non-meaningful changes
      if (!isMeaningfulChange(codeChange)) {
        continue;
      }

      // Aggregate the edit
      this.aggregateEdit(filePath, relativePath, event.document.languageId, codeChange);
    }
  }

  /**
   * Aggregate an edit into the pending edits map
   */
  private aggregateEdit(
    filePath: string,
    relativePath: string,
    languageId: string,
    change: CodeChange
  ): void {
    const now = Date.now();

    let aggregated = this.pendingEdits.get(filePath);
    if (!aggregated) {
      aggregated = {
        filePath,
        relativePath,
        languageId,
        changes: [],
        firstChangeTime: now,
        lastChangeTime: now,
        linesAdded: 0,
        linesDeleted: 0,
        charactersAdded: 0,
        charactersDeleted: 0,
      };
      this.pendingEdits.set(filePath, aggregated);
    }

    // Add the change
    aggregated.changes.push(change);
    aggregated.lastChangeTime = now;

    // Update statistics
    const newLines = (change.text.match(/\n/g) || []).length;
    if (change.changeType === ChangeType.ADDITION) {
      aggregated.linesAdded += newLines;
      aggregated.charactersAdded += change.text.length;
    } else if (change.changeType === ChangeType.DELETION) {
      aggregated.linesDeleted += change.rangeLength > 0 ? 1 : 0; // Approximate
      aggregated.charactersDeleted += change.rangeLength;
    } else {
      aggregated.linesAdded += newLines;
      aggregated.charactersAdded += change.text.length;
      aggregated.charactersDeleted += change.rangeLength;
    }

    // Reset or set debounce timer
    this.resetDebounceTimer(filePath);
  }

  /**
   * Reset the debounce timer for a file
   */
  private resetDebounceTimer(filePath: string): void {
    // Clear existing timer
    const existingTimer = this.debounceTimers.get(filePath);
    if (existingTimer) {
      clearTimeout(existingTimer);
    }

    // Set new timer
    const timer = setTimeout(() => {
      this.flushPendingEdit(filePath);
    }, this.DEBOUNCE_MS);

    this.debounceTimers.set(filePath, timer);
  }

  /**
   * Flush pending edits for a file and create an episode
   */
  private flushPendingEdit(filePath: string): void {
    const aggregated = this.pendingEdits.get(filePath);
    if (!aggregated || aggregated.changes.length < this.MIN_CHANGES_TO_RECORD) {
      this.pendingEdits.delete(filePath);
      this.debounceTimers.delete(filePath);
      return;
    }

    // Clear the pending edit
    this.pendingEdits.delete(filePath);
    const timer = this.debounceTimers.get(filePath);
    if (timer) {
      clearTimeout(timer);
      this.debounceTimers.delete(filePath);
    }

    // Create and save the episode
    this.createAndSaveEpisode(aggregated);

    // Update global statistics
    this.updateStats(aggregated);
  }

  /**
   * Create an episode trace from aggregated edits
   */
  private async createAndSaveEpisode(aggregated: AggregatedEdit): Promise<void> {
    const now = new Date();
    const durationSeconds = Math.round((aggregated.lastChangeTime - aggregated.firstChangeTime) / 1000);

    // Determine overall change type
    const changeType = detectChangeType(
      aggregated.charactersAdded,
      aggregated.charactersDeleted,
      aggregated.linesAdded,
      aggregated.linesDeleted
    );

    // Detect code patterns
    const patterns = detectCodePatterns(aggregated.changes, aggregated.languageId);

    // Get surrounding context
    const context = await this.getSurroundingContext(aggregated.filePath, aggregated.changes);

    // Build action log
    const actionLog = aggregated.changes.map((change, index) => ({
      t: index,
      action: `${change.changeType}_code`,
      target: `line ${change.lineNumber}`,
      result: change.text.substring(0, 100) + (change.text.length > 100 ? '...' : ''),
    }));

    const episode: EpisodeTrace = {
      id: generateId(),
      task_id: `edit-${aggregated.relativePath.replace(/[/\\]/g, '-')}`,
      timestamp: new Date(aggregated.firstChangeTime).toISOString(),
      duration_seconds: durationSeconds,
      agent: 'vscode',
      context: {
        phase: 'ACT',
        goal: `Edit ${aggregated.relativePath}`,
        files_involved: [aggregated.relativePath],
      },
      action_log: actionLog,
      outcome: 'success',
      errors_encountered: [],
      artifacts_produced: [],
      files_read: [],
      files_modified: [aggregated.relativePath],
      importance: this.calculateImportance(aggregated, patterns),
      access_count: 0,
      task_type: 'code_edit',
      edit_summary: {
        change_type: changeType,
        lines_added: aggregated.linesAdded,
        lines_deleted: aggregated.linesDeleted,
        characters_added: aggregated.charactersAdded,
        characters_deleted: aggregated.charactersDeleted,
        patterns_detected: patterns,
      },
      surrounding_context: context,
    };

    // Queue for writing
    this.writeQueue.push(episode);
    this.processWriteQueue();

    logger.debug(
      `FileEditMemoryIntegration: Created episode for ${aggregated.relativePath} ` +
        `(${aggregated.changes.length} changes, ${changeType})`
    );
  }

  /**
   * Get surrounding code context for the changes
   */
  private async getSurroundingContext(
    filePath: string,
    changes: CodeChange[]
  ): Promise<{ before: string; after: string }> {
    try {
      const document = await vscode.workspace.openTextDocument(filePath);
      const lines = document.getText().split('\n');

      // Find the range of affected lines
      const affectedLines = changes.map((c) => c.lineNumber);
      const minLine = Math.max(0, Math.min(...affectedLines) - this.CONTEXT_LINES);
      const maxLine = Math.min(lines.length, Math.max(...affectedLines) + this.CONTEXT_LINES);

      // Get context (limit to avoid huge episodes)
      const before = lines.slice(minLine, Math.min(...affectedLines) - 1).join('\n');
      const after = lines.slice(Math.max(...affectedLines), maxLine).join('\n');

      return {
        before: before.substring(0, 500),
        after: after.substring(0, 500),
      };
    } catch {
      return { before: '', after: '' };
    }
  }

  /**
   * Calculate importance score for an edit episode
   */
  private calculateImportance(aggregated: AggregatedEdit, patterns: string[]): number {
    let importance = 0.3; // Base importance for any edit

    // Boost for amount of change
    if (aggregated.linesAdded + aggregated.linesDeleted > 10) {
      importance += 0.1;
    }
    if (aggregated.linesAdded + aggregated.linesDeleted > 50) {
      importance += 0.1;
    }

    // Boost for detected patterns
    if (patterns.includes('function_definition') || patterns.includes('class_definition')) {
      importance += 0.15;
    }
    if (patterns.includes('test_code')) {
      importance += 0.1;
    }
    if (patterns.includes('error_handling')) {
      importance += 0.05;
    }

    // Boost for certain file types
    if (/\.(ts|tsx|py|js|jsx)$/.test(aggregated.filePath)) {
      importance += 0.05;
    }

    // Cap at 0.9
    return Math.min(0.9, importance);
  }

  /**
   * Process the write queue
   */
  private async processWriteQueue(): Promise<void> {
    if (this.isWriting || this.writeQueue.length === 0) {
      return;
    }

    this.isWriting = true;

    try {
      while (this.writeQueue.length > 0) {
        const episode = this.writeQueue.shift();
        if (episode) {
          await this.writeEpisode(episode);
        }
      }
    } finally {
      this.isWriting = false;
    }
  }

  /**
   * Write an episode to disk
   */
  private async writeEpisode(episode: EpisodeTrace): Promise<void> {
    if (!this.lokiDir) {
      logger.debug('FileEditMemoryIntegration: No loki directory available');
      return;
    }

    // Determine storage path
    const dateStr = episode.timestamp.slice(0, 10); // YYYY-MM-DD
    const episodicDir = path.join(this.lokiDir, 'memory', 'episodic', dateStr);

    try {
      // Create directory if needed
      if (!fs.existsSync(episodicDir)) {
        fs.mkdirSync(episodicDir, { recursive: true });
      }

      const filePath = path.join(episodicDir, `task-${episode.id}.json`);
      await fs.promises.writeFile(filePath, JSON.stringify(episode, null, 2));

      logger.debug(`FileEditMemoryIntegration: Episode saved ${episode.id}`);
    } catch (error) {
      logger.error(`FileEditMemoryIntegration: Failed to write episode ${episode.id}`, error);
    }
  }

  /**
   * Update global edit statistics
   */
  private updateStats(aggregated: AggregatedEdit): void {
    const now = new Date();

    // File edit counts
    const currentCount = this.stats.fileEditCounts.get(aggregated.relativePath) || 0;
    this.stats.fileEditCounts.set(aggregated.relativePath, currentCount + 1);

    // Change type counts
    const changeType = detectChangeType(
      aggregated.charactersAdded,
      aggregated.charactersDeleted,
      aggregated.linesAdded,
      aggregated.linesDeleted
    );
    const typeCount = this.stats.changeTypeCounts.get(changeType) || 0;
    this.stats.changeTypeCounts.set(changeType, typeCount + 1);

    // Hourly activity
    const hour = now.getHours();
    const hourCount = this.stats.hourlyActivity.get(hour) || 0;
    this.stats.hourlyActivity.set(hour, hourCount + 1);

    // Language edit counts
    const langCount = this.stats.languageEditCounts.get(aggregated.languageId) || 0;
    this.stats.languageEditCounts.set(aggregated.languageId, langCount + 1);

    this.stats.lastUpdated = Date.now();
  }

  /**
   * Check if a file should be skipped
   */
  private shouldSkipFile(filePath: string): boolean {
    // Skip node_modules
    if (filePath.includes('node_modules')) {
      return true;
    }

    // Skip .git directory
    if (filePath.includes('.git')) {
      return true;
    }

    // Skip .loki directory (avoid recursion)
    if (filePath.includes('.loki')) {
      return true;
    }

    // Skip common build/cache directories
    if (/\/(dist|build|out|coverage|__pycache__|\.cache|\.vscode|\.idea)\//i.test(filePath)) {
      return true;
    }

    // Skip lock files and generated files
    if (/\.(lock|lockb|min\.js|min\.css|bundle\.)/.test(filePath)) {
      return true;
    }

    return false;
  }

  /**
   * Get relative path from workspace root
   */
  private getRelativePath(filePath: string): string {
    const workspaceFolders = vscode.workspace.workspaceFolders;
    if (workspaceFolders && workspaceFolders.length > 0) {
      const workspaceRoot = workspaceFolders[0].uri.fsPath;
      if (filePath.startsWith(workspaceRoot)) {
        return filePath.substring(workspaceRoot.length + 1);
      }
    }
    return path.basename(filePath);
  }

  // ---------------------------------------------------------------------------
  // Public API
  // ---------------------------------------------------------------------------

  /**
   * Get files most frequently edited
   */
  getMostEditedFiles(limit = 10): Array<{ file: string; count: number }> {
    return Array.from(this.stats.fileEditCounts.entries())
      .sort((a, b) => b[1] - a[1])
      .slice(0, limit)
      .map(([file, count]) => ({ file, count }));
  }

  /**
   * Get change type distribution
   */
  getChangeTypeDistribution(): Record<ChangeType, number> {
    const result: Record<string, number> = {};
    for (const type of Object.values(ChangeType)) {
      result[type] = this.stats.changeTypeCounts.get(type) || 0;
    }
    return result as Record<ChangeType, number>;
  }

  /**
   * Get hourly activity pattern
   */
  getHourlyActivityPattern(): Array<{ hour: number; edits: number }> {
    return Array.from({ length: 24 }, (_, hour) => ({
      hour,
      edits: this.stats.hourlyActivity.get(hour) || 0,
    }));
  }

  /**
   * Get language edit distribution
   */
  getLanguageEditDistribution(): Array<{ language: string; count: number }> {
    return Array.from(this.stats.languageEditCounts.entries())
      .sort((a, b) => b[1] - a[1])
      .map(([language, count]) => ({ language, count }));
  }

  /**
   * Get all statistics
   */
  getStatistics(): {
    mostEditedFiles: Array<{ file: string; count: number }>;
    changeTypes: Record<ChangeType, number>;
    hourlyActivity: Array<{ hour: number; edits: number }>;
    languageDistribution: Array<{ language: string; count: number }>;
    lastUpdated: number;
  } {
    return {
      mostEditedFiles: this.getMostEditedFiles(),
      changeTypes: this.getChangeTypeDistribution(),
      hourlyActivity: this.getHourlyActivityPattern(),
      languageDistribution: this.getLanguageEditDistribution(),
      lastUpdated: this.stats.lastUpdated,
    };
  }

  /**
   * Flush all pending edits immediately
   */
  flushAll(): void {
    for (const filePath of this.pendingEdits.keys()) {
      this.flushPendingEdit(filePath);
    }
  }

  /**
   * Dispose and clean up resources
   */
  dispose(): void {
    // Flush any remaining edits
    this.flushAll();

    // Clear timers
    for (const timer of this.debounceTimers.values()) {
      clearTimeout(timer);
    }
    this.debounceTimers.clear();

    // Dispose event listeners
    this.disposables.forEach((d) => d.dispose());
    this.disposables = [];

    logger.debug('FileEditMemoryIntegration: Disposed');
  }
}

