import * as vscode from 'vscode';
import { DEFAULT_API_PORT, DEFAULT_API_HOST, DEFAULT_POLLING_INTERVAL_MS } from './constants';

export type Provider = 'claude' | 'codex' | 'gemini';
export type LogLevel = 'debug' | 'info' | 'warn' | 'error';

export interface LokiConfig {
    provider: Provider;
    apiPort: number;
    apiHost: string;
    autoConnect: boolean;
    showStatusBar: boolean;
    logLevel: LogLevel;
    pollingInterval: number;
    prdPath: string;
}

/**
 * Configuration wrapper for Loki Mode settings.
 * Provides type-safe access to vscode.workspace.getConfiguration('loki')
 */
export class Config {
    private static readonly SECTION = 'loki';

    /**
     * Get the full configuration object
     */
    static getAll(): LokiConfig {
        const config = vscode.workspace.getConfiguration(this.SECTION);
        return {
            provider: config.get<Provider>('provider', 'claude'),
            apiPort: config.get<number>('apiPort', DEFAULT_API_PORT),
            apiHost: config.get<string>('apiHost', DEFAULT_API_HOST),
            autoConnect: config.get<boolean>('autoConnect', true),
            showStatusBar: config.get<boolean>('showStatusBar', true),
            logLevel: config.get<LogLevel>('logLevel', 'info'),
            pollingInterval: config.get<number>('pollingInterval', DEFAULT_POLLING_INTERVAL_MS),
            prdPath: config.get<string>('prdPath', ''),
        };
    }

    /**
     * Get the AI provider setting
     */
    static get provider(): Provider {
        return vscode.workspace.getConfiguration(this.SECTION).get<Provider>('provider', 'claude');
    }

    /**
     * Get the API port setting
     */
    static get apiPort(): number {
        return vscode.workspace.getConfiguration(this.SECTION).get<number>('apiPort', DEFAULT_API_PORT);
    }

    /**
     * Get the API host setting
     */
    static get apiHost(): string {
        return vscode.workspace.getConfiguration(this.SECTION).get<string>('apiHost', DEFAULT_API_HOST);
    }

    /**
     * Get the full API base URL
     */
    static get apiBaseUrl(): string {
        return `http://${this.apiHost}:${this.apiPort}`;
    }

    /**
     * Get the auto-connect setting
     */
    static get autoConnect(): boolean {
        return vscode.workspace.getConfiguration(this.SECTION).get<boolean>('autoConnect', true);
    }

    /**
     * Get the show status bar setting
     */
    static get showStatusBar(): boolean {
        return vscode.workspace.getConfiguration(this.SECTION).get<boolean>('showStatusBar', true);
    }

    /**
     * Get the log level setting
     */
    static get logLevel(): LogLevel {
        return vscode.workspace.getConfiguration(this.SECTION).get<LogLevel>('logLevel', 'info');
    }

    /**
     * Get the polling interval setting (in milliseconds)
     */
    static get pollingInterval(): number {
        return vscode.workspace.getConfiguration(this.SECTION).get<number>('pollingInterval', DEFAULT_POLLING_INTERVAL_MS);
    }

    /**
     * Get the default PRD path setting
     */
    static get prdPath(): string {
        return vscode.workspace.getConfiguration(this.SECTION).get<string>('prdPath', '');
    }

    /**
     * Update a configuration value
     * @param key The configuration key
     * @param value The new value
     * @param target The configuration target (default: Workspace)
     */
    static async update<K extends keyof LokiConfig>(
        key: K,
        value: LokiConfig[K],
        target: vscode.ConfigurationTarget = vscode.ConfigurationTarget.Workspace
    ): Promise<void> {
        const config = vscode.workspace.getConfiguration(this.SECTION);
        await config.update(key, value, target);
    }

    /**
     * Register a listener for configuration changes
     * @param callback Function to call when configuration changes
     * @returns Disposable to unregister the listener
     */
    static onDidChange(callback: (e: vscode.ConfigurationChangeEvent) => void): vscode.Disposable {
        return vscode.workspace.onDidChangeConfiguration((e) => {
            if (e.affectsConfiguration(this.SECTION)) {
                callback(e);
            }
        });
    }

    /**
     * Check if a specific configuration key changed
     * @param event The configuration change event
     * @param key The key to check
     */
    static didChange(event: vscode.ConfigurationChangeEvent, key: keyof LokiConfig): boolean {
        return event.affectsConfiguration(`${this.SECTION}.${key}`);
    }
}

/**
 * Shared constants for the Loki Mode extension
 */

/**
 * Default API server port
 */
export const DEFAULT_API_PORT = 57374;

/**
 * Default API host
 */
export const DEFAULT_API_HOST = 'localhost';

/**
 * Default API base URL
 */
export const DEFAULT_API_BASE_URL = `http://${DEFAULT_API_HOST}:${DEFAULT_API_PORT}`;

/**
 * Default polling interval in milliseconds
 */
export const DEFAULT_POLLING_INTERVAL_MS = 2000;

import * as vscode from 'vscode';
import { Config, LogLevel } from './config';

/**
 * Log level priorities for comparison
 */
const LOG_LEVEL_PRIORITY: Record<LogLevel, number> = {
    debug: 0,
    info: 1,
    warn: 2,
    error: 3,
};

/**
 * Logger wrapper around VS Code OutputChannel.
 * Provides leveled logging with timestamps and configurable log levels.
 */
export class Logger {
    private static instance: Logger | null = null;
    private outputChannel: vscode.OutputChannel;
    private logLevel: LogLevel;

    private constructor() {
        this.outputChannel = vscode.window.createOutputChannel('Loki Mode');
        this.logLevel = Config.logLevel;

        // Listen for configuration changes
        Config.onDidChange((e) => {
            if (Config.didChange(e, 'logLevel')) {
                this.logLevel = Config.logLevel;
                this.info(`Log level changed to: ${this.logLevel}`);
            }
        });
    }

    /**
     * Get the singleton Logger instance
     */
    static getInstance(): Logger {
        if (!Logger.instance) {
            Logger.instance = new Logger();
        }
        return Logger.instance;
    }

    /**
     * Dispose the logger and release resources
     */
    static dispose(): void {
        if (Logger.instance) {
            Logger.instance.outputChannel.dispose();
            Logger.instance = null;
        }
    }

    /**
     * Check if a message at the given level should be logged
     */
    private shouldLog(level: LogLevel): boolean {
        return LOG_LEVEL_PRIORITY[level] >= LOG_LEVEL_PRIORITY[this.logLevel];
    }

    /**
     * Format a log message with timestamp and level
     */
    private formatMessage(level: LogLevel, message: string): string {
        const timestamp = new Date().toISOString();
        const levelStr = level.toUpperCase().padEnd(5);
        return `[${timestamp}] [${levelStr}] ${message}`;
    }

    /**
     * Log a message at the specified level
     */
    private log(level: LogLevel, message: string, ...args: unknown[]): void {
        if (!this.shouldLog(level)) {
            return;
        }

        let formattedMessage = message;
        if (args.length > 0) {
            formattedMessage = `${message} ${args.map(arg =>
                typeof arg === 'object' ? JSON.stringify(arg, null, 2) : String(arg)
            ).join(' ')}`;
        }

        this.outputChannel.appendLine(this.formatMessage(level, formattedMessage));
    }

    /**
     * Log a debug message
     */
    debug(message: string, ...args: unknown[]): void {
        this.log('debug', message, ...args);
    }

    /**
     * Log an info message
     */
    info(message: string, ...args: unknown[]): void {
        this.log('info', message, ...args);
    }

    /**
     * Log a warning message
     */
    warn(message: string, ...args: unknown[]): void {
        this.log('warn', message, ...args);
    }

    /**
     * Log an error message
     */
    error(message: string, ...args: unknown[]): void {
        this.log('error', message, ...args);
    }

    /**
     * Log an error with stack trace
     */
    errorWithStack(message: string, error: Error): void {
        this.error(`${message}: ${error.message}`);
        if (error.stack) {
            this.error(`Stack trace:\n${error.stack}`);
        }
    }

    /**
     * Show the output channel in the VS Code panel
     */
    show(preserveFocus: boolean = true): void {
        this.outputChannel.show(preserveFocus);
    }

    /**
     * Hide the output channel
     */
    hide(): void {
        this.outputChannel.hide();
    }

    /**
     * Clear all log messages
     */
    clear(): void {
        this.outputChannel.clear();
    }

    /**
     * Get the underlying OutputChannel for disposal
     */
    getOutputChannel(): vscode.OutputChannel {
        return this.outputChannel;
    }
}

// Export convenience functions for direct logging
export const logger = {
    debug: (message: string, ...args: unknown[]) => Logger.getInstance().debug(message, ...args),
    info: (message: string, ...args: unknown[]) => Logger.getInstance().info(message, ...args),
    warn: (message: string, ...args: unknown[]) => Logger.getInstance().warn(message, ...args),
    error: (message: string, ...args: unknown[]) => Logger.getInstance().error(message, ...args),
    errorWithStack: (message: string, error: Error) => Logger.getInstance().errorWithStack(message, error),
    show: (preserveFocus?: boolean) => Logger.getInstance().show(preserveFocus),
    hide: () => Logger.getInstance().hide(),
    clear: () => Logger.getInstance().clear(),
};

/**
 * Shared webview utilities
 */

/**
 * Generate a nonce string for Content Security Policy
 * Used to allow inline scripts in webviews while maintaining security
 * @returns A random 32-character alphanumeric string
 */
export function getNonce(): string {
    let text = '';
    const possible = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789';
    for (let i = 0; i < 32; i++) {
        text += possible.charAt(Math.floor(Math.random() * possible.length));
    }
    return text;
}

/**
 * Chat View Provider
 * Provides a webview panel for chatting with AI while Loki Mode runs
 */

import * as vscode from 'vscode';
import { LokiApiClient } from '../api/client';
import { Provider } from '../api/types';
import { logger } from '../utils/logger';
import { getNonce } from '../utils/webview';

interface ChatMessage {
    id: string;
    role: 'user' | 'assistant' | 'system';
    content: string;
    timestamp: Date;
    provider?: Provider;
}

export class ChatViewProvider implements vscode.WebviewViewProvider, vscode.Disposable {
    public static readonly viewType = 'loki-chat';
    private static readonly MAX_MESSAGES = 100;

    private _view?: vscode.WebviewView;
    private _messages: ChatMessage[] = [];
    private _currentProvider: Provider = 'claude';

    constructor(
        private readonly _extensionUri: vscode.Uri,
        private readonly _apiClient: LokiApiClient
    ) {}

    /**
     * Dispose of resources when extension deactivates
     */
    public dispose(): void {
        // Clean up resources
        this._messages = [];
    }

    public resolveWebviewView(
        webviewView: vscode.WebviewView,
        _context: vscode.WebviewViewResolveContext,
        _token: vscode.CancellationToken
    ) {
        this._view = webviewView;

        webviewView.webview.options = {
            enableScripts: true,
            localResourceRoots: [this._extensionUri]
        };

        webviewView.webview.html = this._getHtmlForWebview(webviewView.webview);

        // Handle messages from the webview
        webviewView.webview.onDidReceiveMessage(async (data) => {
            switch (data.type) {
                case 'sendMessage':
                    await this._handleSendMessage(data.message);
                    break;
                case 'setProvider':
                    // Validate provider to prevent injection
                    const validProviders: Provider[] = ['claude', 'codex', 'gemini'];
                    if (validProviders.includes(data.provider)) {
                        this._currentProvider = data.provider;
                        this._addSystemMessage(`Switched to ${data.provider} provider`);
                    }
                    break;
                case 'clearHistory':
                    this._messages = [];
                    this._updateWebview();
                    break;
                case 'ready':
                    this._updateWebview();
                    break;
            }
        });

        // Add welcome message
        if (this._messages.length === 0) {
            this._addSystemMessage('Welcome to Loki Mode Chat! You can interact with the AI while Loki Mode runs in the background.');
        }
    }

    private async _handleSendMessage(message: string) {
        if (!message.trim()) return;

        // Add user message
        const userMsg: ChatMessage = {
            id: this._generateId(),
            role: 'user',
            content: message,
            timestamp: new Date(),
            provider: this._currentProvider
        };
        this._pushMessage(userMsg);
        this._updateWebview();

        try {
            // Check if server is running
            const isHealthy = await this._apiClient.health();
            if (!isHealthy) {
                this._addSystemMessage('Loki Mode server is not running. Start it first with "loki start" command.');
                return;
            }

            // Send to the chat endpoint
            const response = await this._sendChatMessage(message);

            // Add assistant response
            const assistantMsg: ChatMessage = {
                id: this._generateId(),
                role: 'assistant',
                content: response,
                timestamp: new Date(),
                provider: this._currentProvider
            };
            this._pushMessage(assistantMsg);
            this._updateWebview();

        } catch (error) {
            logger.error('Chat error:', error);
            this._addSystemMessage(`Error: ${error instanceof Error ? error.message : 'Failed to send message'}`);
        }
    }

    private async _sendChatMessage(message: string): Promise<string> {
        // Try the chat endpoint first
        try {
            const baseUrl = this._apiClient.baseUrl;
            const response = await fetch(`${baseUrl}/chat`, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify({
                    message,
                    provider: this._currentProvider
                })
            });

            if (response.ok) {
                const data = await response.json() as { response?: string; message?: string };
                return data.response || data.message || 'Response received';
            }

            // Check for prompt injection disabled error
            if (response.status === 500) {
                try {
                    const errorData = await response.json() as { error?: string };
                    if (errorData.error?.includes('Prompt injection is disabled')) {
                        return this._handlePromptInjectionDisabled();
                    }
                } catch {
                    // Ignore JSON parse errors
                }
            }

            // Check for 404 (endpoint not available) - fall back to input injection
            if (response.status === 404) {
                await this._apiClient.injectInput(message);
                return 'Message sent to Loki Mode. The AI will process it in the current session.';
            }

            throw new Error(`Chat request failed with status ${response.status}`);
        } catch (error) {
            // Check if error is about prompt injection
            if (error instanceof Error && error.message.includes('Prompt injection is disabled')) {
                return this._handlePromptInjectionDisabled();
            }
            throw error;
        }
    }

    /**
     * Handle case when prompt injection is disabled on the server
     * Shows a helpful message with option to enable it
     */
    private _handlePromptInjectionDisabled(): string {
        // Send a special message type to the webview to show the enable option
        if (this._view) {
            this._view.webview.postMessage({
                type: 'showPromptInjectionWarning'
            });
        }
        return 'Chat requires prompt injection to be enabled on the server. ' +
               'This allows sending messages to the AI during an active session. ' +
               'To enable, start the server with: loki start --allow-injection';
    }

    private _addSystemMessage(content: string) {
        const msg: ChatMessage = {
            id: this._generateId(),
            role: 'system',
            content,
            timestamp: new Date()
        };
        this._pushMessage(msg);
        this._updateWebview();
    }

    /**
     * Push a message and enforce the max message limit
     */
    private _pushMessage(msg: ChatMessage): void {
        this._messages.push(msg);
        // Enforce max message limit
        while (this._messages.length > ChatViewProvider.MAX_MESSAGES) {
            this._messages.shift();
        }
    }

    private _updateWebview() {
        if (this._view) {
            this._view.webview.postMessage({
                type: 'updateMessages',
                messages: this._messages,
                provider: this._currentProvider
            });
        }
    }

    private _generateId(): string {
        return `msg_${Date.now()}_${Math.random().toString(36).substring(2, 11)}`;
    }

    public addMessage(role: 'user' | 'assistant' | 'system', content: string) {
        const msg: ChatMessage = {
            id: this._generateId(),
            role,
            content,
            timestamp: new Date()
        };
        this._pushMessage(msg);
        this._updateWebview();
    }

    private _getHtmlForWebview(webview: vscode.Webview): string {
        const nonce = getNonce();

        return `<!DOCTYPE html>
