    <script nonce="${nonce}">
        const vscode = acquireVsCodeApi();
        const messagesContainer = document.getElementById('messages');
        const messageInput = document.getElementById('messageInput');
        const sendBtn = document.getElementById('sendBtn');
        const clearBtn = document.getElementById('clearBtn');
        const providerSelect = document.getElementById('provider');

        let messages = [];

        // Auto-resize textarea
        messageInput.addEventListener('input', () => {
            messageInput.style.height = 'auto';
            messageInput.style.height = Math.min(messageInput.scrollHeight, 120) + 'px';
        });

        // Send message
        function sendMessage() {
            const message = messageInput.value.trim();
            if (message) {
                vscode.postMessage({ type: 'sendMessage', message });
                messageInput.value = '';
                messageInput.style.height = 'auto';
            }
        }

        sendBtn.addEventListener('click', sendMessage);
        messageInput.addEventListener('keydown', (e) => {
            if (e.key === 'Enter' && !e.shiftKey) {
                e.preventDefault();
                sendMessage();
            }
        });

        // Clear history
        clearBtn.addEventListener('click', () => {
            vscode.postMessage({ type: 'clearHistory' });
        });

        // Provider change
        providerSelect.addEventListener('change', () => {
            vscode.postMessage({ type: 'setProvider', provider: providerSelect.value });
        });

        // Handle messages from extension
        window.addEventListener('message', event => {
            const data = event.data;
            switch (data.type) {
                case 'updateMessages':
                    messages = data.messages;
                    providerSelect.value = data.provider;
                    renderMessages();
                    break;
                case 'showPromptInjectionWarning':
                    showInjectionWarning();
                    break;
            }
        });

        function showInjectionWarning() {
            messagesContainer.innerHTML = \`
                <div class="injection-warning">
                    <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" style="width: 48px; height: 48px; margin-bottom: 12px; color: var(--vscode-editorWarning-foreground);">
                        <path d="M10.29 3.86L1.82 18a2 2 0 0 0 1.71 3h16.94a2 2 0 0 0 1.71-3L13.71 3.86a2 2 0 0 0-3.42 0z"></path>
                        <line x1="12" y1="9" x2="12" y2="13"></line>
                        <line x1="12" y1="17" x2="12.01" y2="17"></line>
                    </svg>
                    <h3 style="margin-bottom: 8px;">Chat Requires Prompt Injection</h3>
                    <p style="margin-bottom: 16px; color: var(--vscode-descriptionForeground);">
                        The server has prompt injection disabled. Chat allows sending messages directly to the AI during an active session.
                    </p>
                    <div style="background: var(--vscode-textCodeBlock-background); padding: 12px; border-radius: 6px; margin-bottom: 16px; text-align: left;">
                        <p style="font-size: 12px; margin-bottom: 8px; color: var(--vscode-descriptionForeground);">To enable chat, restart the server with:</p>
                        <code style="font-family: var(--vscode-editor-font-family);">loki start --allow-injection</code>
                    </div>
                    <p style="font-size: 11px; color: var(--vscode-descriptionForeground);">
                        Note: Prompt injection allows external input during AI execution. Only enable in trusted environments.
                    </p>
                </div>
            \`;
        }

        function renderMessages() {
            if (messages.length === 0) {
                messagesContainer.innerHTML = \`
                    <div class="empty-state">
                        <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                            <path d="M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z"></path>
                        </svg>
                        <p>Start a conversation with the AI</p>
                        <p style="font-size: 12px; margin-top: 8px;">Messages are sent to the active Loki session</p>
                    </div>
                \`;
                return;
            }

            messagesContainer.innerHTML = messages.map(msg => {
                const time = new Date(msg.timestamp).toLocaleTimeString();
                const content = escapeHtml(msg.content)
                    .replace(/\`\`\`([\\s\\S]*?)\`\`\`/g, '<pre><code>$1</code></pre>')
                    .replace(/\`([^\`]+)\`/g, '<code>$1</code>')
                    .replace(/\\n/g, '<br>');

                // Escape role and provider to prevent XSS
                const safeRole = escapeHtml(msg.role || 'user');
                const safeProvider = msg.provider ? escapeHtml(msg.provider) : '';

                return \`
                    <div class="message \${safeRole}">
                        <div>\${content}</div>
                        <div class="message-meta">\${time}\${safeProvider ? ' - ' + safeProvider : ''}</div>
                    </div>
                \`;
            }).join('');

            messagesContainer.scrollTop = messagesContainer.scrollHeight;
        }

        function escapeHtml(text) {
            const div = document.createElement('div');
            div.textContent = text;
            return div.innerHTML;
        }

        // Notify extension that webview is ready
        vscode.postMessage({ type: 'ready' });
    </script>
</body>
</html>`;
    }
}

/**
 * Loki Mode Checkpoint Tree View Provider
 * Displays checkpoint history, supports creation and rollback.
 *
 * API endpoints:
 *   GET  /api/checkpoints              - List checkpoints
 *   POST /api/checkpoints              - Create checkpoint (body: { message })
 *   POST /api/checkpoints/{id}/rollback - Rollback to checkpoint
 */

import * as vscode from 'vscode';
import { logger } from '../utils/logger';
import { Config } from '../utils/config';

/**
 * Checkpoint data returned by the API
 */
interface Checkpoint {
    id: string;
    created_at: string;
    git_sha: string;
    message: string;
    files: string[];
}

/**
 * Tree item representing a single checkpoint
 */
class CheckpointItem extends vscode.TreeItem {
    constructor(
        public readonly checkpoint: Checkpoint
    ) {
        super(
            checkpoint.message || checkpoint.id,
            vscode.TreeItemCollapsibleState.None
        );

        const shortSha = checkpoint.git_sha
            ? checkpoint.git_sha.substring(0, 7)
            : 'no-sha';
        const relativeTime = CheckpointItem.formatRelativeTime(checkpoint.created_at);

        this.description = `${shortSha} - ${relativeTime}`;
        this.tooltip = [
            `ID: ${checkpoint.id}`,
            `Message: ${checkpoint.message || '(none)'}`,
            `SHA: ${checkpoint.git_sha || 'unknown'}`,
            `Created: ${checkpoint.created_at}`,
            `Files: ${Array.isArray(checkpoint.files) ? checkpoint.files.join(', ') : 'none'}`,
        ].join('\n');

        this.iconPath = new vscode.ThemeIcon('git-commit');
        this.contextValue = 'checkpoint';
    }

    /**
     * Format an ISO timestamp as a human-readable relative time string
     */
    private static formatRelativeTime(isoTimestamp: string): string {
        try {
            const then = new Date(isoTimestamp).getTime();
            const now = Date.now();
            const diffMs = now - then;

            if (diffMs < 0) {
                return 'just now';
            }

            const seconds = Math.floor(diffMs / 1000);
            if (seconds < 60) {
                return `${seconds}s ago`;
            }

            const minutes = Math.floor(seconds / 60);
            if (minutes < 60) {
                return `${minutes}m ago`;
            }

            const hours = Math.floor(minutes / 60);
            if (hours < 24) {
                return `${hours}h ago`;
            }

            const days = Math.floor(hours / 24);
            return `${days}d ago`;
        } catch {
            return isoTimestamp;
        }
    }
}

/**
 * Tree data provider for Loki checkpoints
 */
export class CheckpointProvider implements vscode.TreeDataProvider<CheckpointItem> {
    private _onDidChangeTreeData: vscode.EventEmitter<CheckpointItem | undefined | null | void> =
        new vscode.EventEmitter<CheckpointItem | undefined | null | void>();
    readonly onDidChangeTreeData: vscode.Event<CheckpointItem | undefined | null | void> =
        this._onDidChangeTreeData.event;

    private checkpoints: CheckpointItem[] = [];

    /**
     * Refresh the tree view by re-fetching checkpoints from the API
     */
    async refresh(): Promise<void> {
        try {
            const data = await this.apiGet<Checkpoint[]>('/api/checkpoints');
            if (Array.isArray(data)) {
                this.checkpoints = data.map(cp => new CheckpointItem(cp));
            }
        } catch (error) {
            logger.debug('Failed to fetch checkpoints', error);
            // Keep existing data on failure so the view does not flash empty
        }
        this._onDidChangeTreeData.fire();
    }

    /**
     * Create a new checkpoint via the API
     */
    async createCheckpoint(): Promise<void> {
        const message = await vscode.window.showInputBox({
            prompt: 'Enter a message for this checkpoint',
            placeHolder: 'e.g. Before refactoring auth module',
        });

        // User pressed Escape
        if (message === undefined) {
            return;
        }

        try {
            await this.apiPost('/api/checkpoints', { message });
            vscode.window.showInformationMessage(`Checkpoint created${message ? ': ' + message : ''}`);
            logger.info(`Checkpoint created: ${message || '(no message)'}`);
            await this.refresh();
        } catch (error) {
            const errorMessage = error instanceof Error ? error.message : String(error);
            vscode.window.showErrorMessage(`Failed to create checkpoint: ${errorMessage}`);
            logger.error('Failed to create checkpoint', error);
        }
    }

    /**
     * Rollback to a specific checkpoint (with confirmation).
     * Accepts the tree item passed by VS Code command handler.
     */
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    async rollbackCheckpoint(item: any): Promise<void> {
        const checkpoint: Checkpoint | undefined = item?.checkpoint;
        if (!checkpoint) {
            return;
        }

        const label = checkpoint.message || checkpoint.id;
        const sha = checkpoint.git_sha
            ? ` (${checkpoint.git_sha.substring(0, 7)})`
            : '';

        const confirm = await vscode.window.showWarningMessage(
            `Rollback to checkpoint "${label}"${sha}? This will restore saved state files.`,
            { modal: true },
            'Rollback'
        );

        if (confirm !== 'Rollback') {
            return;
        }

        try {
            await this.apiPost(`/api/checkpoints/${checkpoint.id}/rollback`);
            vscode.window.showInformationMessage(`Rolled back to checkpoint: ${label}`);
            logger.info(`Rolled back to checkpoint: ${checkpoint.id}`);
            await this.refresh();
        } catch (error) {
            const errorMessage = error instanceof Error ? error.message : String(error);
            vscode.window.showErrorMessage(`Failed to rollback: ${errorMessage}`);
            logger.error('Failed to rollback checkpoint', error);
        }
    }

    // =========================================================================
    // TreeDataProvider interface
    // =========================================================================

    getTreeItem(element: CheckpointItem): vscode.TreeItem {
        return element;
    }

    getChildren(): Thenable<CheckpointItem[]> {
        return Promise.resolve(this.checkpoints);
    }

    // =========================================================================
    // HTTP helpers (mirrors apiRequest pattern in extension.ts)
    // =========================================================================

    private async apiGet<T>(endpoint: string): Promise<T> {
        const url = `${Config.apiBaseUrl}${endpoint}`;
        logger.debug(`Checkpoint API GET: ${url}`);

        const response = await fetch(url, {
            method: 'GET',
            headers: { 'Content-Type': 'application/json' },
        });

        if (!response.ok) {
            throw new Error(`HTTP ${response.status}: ${response.statusText}`);
        }

        return await response.json() as T;
    }

    private async apiPost(endpoint: string, body?: unknown): Promise<unknown> {
        const url = `${Config.apiBaseUrl}${endpoint}`;
        logger.debug(`Checkpoint API POST: ${url}`);

        const options: RequestInit = {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
        };

        if (body) {
            options.body = JSON.stringify(body);
        }

        const response = await fetch(url, options);

        if (!response.ok) {
            throw new Error(`HTTP ${response.status}: ${response.statusText}`);
        }

        const contentType = response.headers.get('content-type');
        if (contentType?.includes('application/json')) {
            return await response.json();
        }

        return {};
    }
}

/**
 * Dashboard Webview Provider
 * Embeds the Loki Mode dashboard Web Components in a VS Code sidebar panel
 * Provides task board, session control, log stream, memory browser, and learning dashboard
 *
 * Refactored in v5.19.0 to use dashboard-ui Web Components
 * Reduced from 1,339 lines to ~390 lines (71% reduction) by delegating UI to reusable components
 */

import * as vscode from 'vscode';
import { LokiApiClient } from '../api/client';
import { logger } from '../utils/logger';
import { getNonce } from '../utils/webview';

export class DashboardWebviewProvider implements vscode.WebviewViewProvider, vscode.Disposable {
    public static readonly viewType = 'loki-dashboard';

    private _view?: vscode.WebviewView;
    private _disposables: vscode.Disposable[] = [];
    private _apiUrl: string;

    constructor(
        private readonly _extensionUri: vscode.Uri,
        private readonly _apiClient: LokiApiClient
    ) {
        this._apiUrl = _apiClient.baseUrl;
    }

    public dispose(): void {
        this._disposables.forEach(d => d.dispose());
        this._disposables = [];
    }

    public resolveWebviewView(
        webviewView: vscode.WebviewView,
        _context: vscode.WebviewViewResolveContext,
        _token: vscode.CancellationToken
    ): void {
        this._view = webviewView;

        webviewView.webview.options = {
            enableScripts: true,
            localResourceRoots: [
                this._extensionUri,
                vscode.Uri.joinPath(this._extensionUri, 'media'),
                vscode.Uri.joinPath(this._extensionUri, 'dist')
            ]
        };

        webviewView.webview.html = this._getHtmlForWebview(webviewView.webview);

        // Handle messages from the webview
        const messageHandler = webviewView.webview.onDidReceiveMessage(
            async (message) => this._handleMessage(message),
            undefined,
            this._disposables
        );
        this._disposables.push(messageHandler);

        // Cleanup on dispose
        webviewView.onDidDispose(() => {
            // Web Components handle their own cleanup
        });
    }

    private async _handleMessage(message: { type: string; [key: string]: unknown }): Promise<void> {
        switch (message.type) {
            case 'ready':
                // Components initialize themselves, just acknowledge
                logger.info('Dashboard webview ready');
                break;

            case 'startSession':
                await this._startSession(message.provider as string);
                break;

            case 'stopSession':
                await this._stopSession();
                break;

            case 'pauseSession':
                await this._pauseSession();
                break;

            case 'resumeSession':
                await this._resumeSession();
                break;

            case 'viewTaskDetails':
                await this._showTaskDetails(message.taskId as string);
                break;

            case 'viewPatternDetails':
                await this._showPatternDetails(message.patternId as string);
                break;

            case 'viewEpisodeDetails':
                await this._showEpisodeDetails(message.episodeId as string);
                break;

            case 'openExternal':
                if (message.url) {
                    vscode.env.openExternal(vscode.Uri.parse(message.url as string));
                }
                break;

            case 'showInfo':
                vscode.window.showInformationMessage(message.message as string);
                break;

            case 'showError':
                vscode.window.showErrorMessage(message.message as string);
                break;
        }
    }

    private async _startSession(provider: string): Promise<void> {
        try {
            const baseUrl = this._apiClient.baseUrl;
            await fetch(`${baseUrl}/start`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ provider })
            });
            vscode.window.showInformationMessage(`Loki Mode started with ${provider}`);
        } catch (error) {
            logger.error('Failed to start session:', error);
            vscode.window.showErrorMessage('Failed to start Loki Mode session');
        }
    }

    private async _stopSession(): Promise<void> {
        try {
            const baseUrl = this._apiClient.baseUrl;
            await fetch(`${baseUrl}/stop`, { method: 'POST' });
            vscode.window.showInformationMessage('Loki Mode stopped');
        } catch (error) {
            logger.error('Failed to stop session:', error);
            vscode.window.showErrorMessage('Failed to stop Loki Mode session');
        }
    }

    private async _pauseSession(): Promise<void> {
        try {
            const baseUrl = this._apiClient.baseUrl;
            await fetch(`${baseUrl}/pause`, { method: 'POST' });
            vscode.window.showInformationMessage('Loki Mode paused');
        } catch (error) {
            logger.error('Failed to pause session:', error);
            vscode.window.showErrorMessage('Failed to pause Loki Mode session');
        }
    }

    private async _resumeSession(): Promise<void> {
        try {
            const baseUrl = this._apiClient.baseUrl;
            await fetch(`${baseUrl}/resume`, { method: 'POST' });
            vscode.window.showInformationMessage('Loki Mode resumed');
        } catch (error) {
            logger.error('Failed to resume session:', error);
            vscode.window.showErrorMessage('Failed to resume Loki Mode session');
        }
    }

    private async _showTaskDetails(taskId: string): Promise<void> {
        try {
            const baseUrl = this._apiClient.baseUrl;
            const response = await fetch(`${baseUrl}/api/tasks/${taskId}`);
            if (response.ok) {
                const task = await response.json();
                const content = JSON.stringify(task, null, 2);
                const doc = await vscode.workspace.openTextDocument({
                    content,
                    language: 'json'
                });
                await vscode.window.showTextDocument(doc, { preview: true });
            }
        } catch (error) {
            logger.error('Failed to fetch task details:', error);
        }
    }

    private async _showPatternDetails(patternId: string): Promise<void> {
        try {
            const baseUrl = this._apiClient.baseUrl;
            const response = await fetch(`${baseUrl}/api/memory/patterns/${patternId}`);
            if (response.ok) {
                const pattern = await response.json();
                const content = JSON.stringify(pattern, null, 2);
                const doc = await vscode.workspace.openTextDocument({
                    content,
                    language: 'json'
                });
                await vscode.window.showTextDocument(doc, { preview: true });
            }
        } catch (error) {
            logger.error('Failed to fetch pattern details:', error);
        }
    }

    private async _showEpisodeDetails(episodeId: string): Promise<void> {
        try {
            const baseUrl = this._apiClient.baseUrl;
            const response = await fetch(`${baseUrl}/api/memory/episodes/${episodeId}`);
            if (response.ok) {
                const episode = await response.json();
                const content = JSON.stringify(episode, null, 2);
                const doc = await vscode.workspace.openTextDocument({
                    content,
                    language: 'json'
                });
                await vscode.window.showTextDocument(doc, { preview: true });
            }
        } catch (error) {
            logger.error('Failed to fetch episode details:', error);
        }
    }

    private _getHtmlForWebview(webview: vscode.Webview): string {
        const nonce = getNonce();
        const dashboardUri = webview.asWebviewUri(
            vscode.Uri.joinPath(this._extensionUri, 'media', 'loki-dashboard.js')
        );

        return `<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <meta http-equiv="Content-Security-Policy"
          content="default-src 'none';
                   style-src ${webview.cspSource} 'unsafe-inline';
                   script-src 'nonce-${nonce}';
                   connect-src ${this._apiUrl};">
    <title>Loki Dashboard</title>
    <style>
        :root {
            --loki-accent: #d97757;
        }
        * { box-sizing: border-box; margin: 0; padding: 0; }
        body {
            font-family: var(--vscode-font-family);
            font-size: var(--vscode-font-size);
            color: var(--vscode-foreground);
            background: var(--vscode-editor-background);
            height: 100vh;
            display: flex;
            flex-direction: column;
            overflow: hidden;
        }
        .dashboard-tabs {
            display: flex;
            border-bottom: 1px solid var(--vscode-panel-border);
            background: var(--vscode-sideBar-background);
            flex-shrink: 0;
        }
        .tab-btn {
            flex: 1;
            padding: 8px 4px;
            text-align: center;
            font-size: 11px;
            font-weight: 500;
            cursor: pointer;
            border: none;
            border-bottom: 2px solid transparent;
            background: transparent;
            color: var(--vscode-descriptionForeground);
            transition: all 0.15s;
        }
        .tab-btn:hover {
            background: var(--vscode-list-hoverBackground);
        }
        .tab-btn.active {
            color: var(--loki-accent);
            border-bottom-color: var(--loki-accent);
        }
        .tab-content {
            display: none;
            flex: 1;
            overflow: auto;
            padding: 8px;
        }
        .tab-content.active {
            display: block;
        }
        /* Ensure Web Components fill their container */
        loki-task-board, loki-session-control, loki-log-stream,
        loki-memory-browser, loki-learning-dashboard, loki-council-dashboard {
            display: block;
            width: 100%;
        }
    </style>
</head>
<body>
    <div class="dashboard-tabs">
        <button class="tab-btn active" data-tab="tasks">Tasks</button>
        <button class="tab-btn" data-tab="sessions">Sessions</button>
        <button class="tab-btn" data-tab="logs">Logs</button>
        <button class="tab-btn" data-tab="memory">Memory</button>
        <button class="tab-btn" data-tab="learning">Learning</button>
        <button class="tab-btn" data-tab="council">Council</button>
    </div>

    <div id="tasks" class="tab-content active">
        <loki-task-board api-url="${this._apiUrl}" theme="vscode-dark"></loki-task-board>
    </div>
    <div id="sessions" class="tab-content">
        <loki-session-control api-url="${this._apiUrl}" theme="vscode-dark"></loki-session-control>
    </div>
    <div id="logs" class="tab-content">
        <loki-log-stream api-url="${this._apiUrl}" theme="vscode-dark" auto-scroll max-lines="500"></loki-log-stream>
    </div>
    <div id="memory" class="tab-content">
        <loki-memory-browser api-url="${this._apiUrl}" theme="vscode-dark"></loki-memory-browser>
    </div>
    <div id="learning" class="tab-content">
        <loki-learning-dashboard api-url="${this._apiUrl}" theme="vscode-dark"></loki-learning-dashboard>
    </div>
    <div id="council" class="tab-content">
        <loki-council-dashboard api-url="${this._apiUrl}" theme="vscode-dark"></loki-council-dashboard>
    </div>

    <script nonce="${nonce}" src="${dashboardUri}"></script>
    <script nonce="${nonce}">
        // Initialize Loki Dashboard Web Components
        if (typeof LokiDashboard !== 'undefined') {
            LokiDashboard.init({
                theme: 'vscode-dark',
                apiUrl: '${this._apiUrl}',
                autoDetectContext: true
            });
        }

        // Tab switching
        document.querySelectorAll('.tab-btn').forEach(btn => {
            btn.addEventListener('click', () => {
                document.querySelectorAll('.tab-btn').forEach(b => b.classList.remove('active'));
                document.querySelectorAll('.tab-content').forEach(c => c.classList.remove('active'));
                btn.classList.add('active');
                const tabId = btn.dataset.tab;
                document.getElementById(tabId).classList.add('active');
            });
        });

        // VS Code API bridge for extension communication
        const vscode = acquireVsCodeApi();

        // Forward Web Component events to VS Code extension
        document.addEventListener('session-start', (e) => {
            vscode.postMessage({ type: 'startSession', provider: e.detail?.provider || 'claude' });
        });
        document.addEventListener('session-stop', () => {
            vscode.postMessage({ type: 'stopSession' });
        });
        document.addEventListener('session-pause', () => {
            vscode.postMessage({ type: 'pauseSession' });
        });
        document.addEventListener('session-resume', () => {
            vscode.postMessage({ type: 'resumeSession' });
        });
        document.addEventListener('task-select', (e) => {
            vscode.postMessage({ type: 'viewTaskDetails', taskId: e.detail?.id });
        });
        document.addEventListener('pattern-select', (e) => {
            vscode.postMessage({ type: 'viewPatternDetails', patternId: e.detail?.id });
        });
        document.addEventListener('episode-select', (e) => {
            vscode.postMessage({ type: 'viewEpisodeDetails', episodeId: e.detail?.id });
        });
        document.addEventListener('council-action', (e) => {
            vscode.postMessage({ type: 'showInfo', message: 'Council action: ' + (e.detail?.action || 'unknown') });
        });

        // Handle messages from extension
        window.addEventListener('message', event => {
            const message = event.data;
            switch (message.type) {
                case 'themeChanged':
                    // Update all components with new theme
                    document.querySelectorAll('[theme]').forEach(el => {
                        el.setAttribute('theme', message.theme);
                    });
                    break;
                case 'apiUrlChanged':
                    // Update all components with new API URL
                    document.querySelectorAll('[api-url]').forEach(el => {
                        el.setAttribute('api-url', message.apiUrl);
                    });
                    break;
            }
        });

        // Notify extension that webview is ready
        vscode.postMessage({ type: 'ready' });
    </script>
</body>
</html>`;
    }
}

/**
 * Logs View Provider
 * Provides a webview panel for viewing real-time logs from Loki Mode
 */

import * as vscode from 'vscode';
import * as fs from 'fs';
import * as path from 'path';
import { LokiApiClient } from '../api/client';
import { logger } from '../utils/logger';
import { getNonce } from '../utils/webview';

interface LogEntry {
    timestamp: string;
    level: 'debug' | 'info' | 'warn' | 'error';
    message: string;
    source?: string;
}

export class LogsViewProvider implements vscode.WebviewViewProvider, vscode.Disposable {
    public static readonly viewType = 'loki-logs';

    private _view?: vscode.WebviewView;
    private _logs: LogEntry[] = [];
    private _filterLevel: string = 'all';
    private _autoScroll: boolean = true;
    private _pollingInterval?: NodeJS.Timeout;

    constructor(
        private readonly _extensionUri: vscode.Uri,
        private readonly _apiClient: LokiApiClient
    ) {}

    /**
     * Dispose of resources when extension deactivates
     */
    public dispose(): void {
        this._stopLogPolling();
    }

    public resolveWebviewView(
        webviewView: vscode.WebviewView,
        _context: vscode.WebviewViewResolveContext,
        _token: vscode.CancellationToken
    ) {
        this._view = webviewView;

        webviewView.webview.options = {
            enableScripts: true,
            localResourceRoots: [this._extensionUri]
        };

        webviewView.webview.html = this._getHtmlForWebview(webviewView.webview);

        // Handle messages from the webview
        webviewView.webview.onDidReceiveMessage(async (data) => {
            switch (data.type) {
                case 'setFilter':
                    this._filterLevel = data.level;
                    this._updateWebview();
                    break;
                case 'toggleAutoScroll':
                    this._autoScroll = data.enabled;
                    break;
                case 'clearLogs':
                    this._logs = [];
                    this._updateWebview();
                    break;
                case 'ready':
                    // Await initial fetch to avoid race condition
                    await this._fetchLogs();
                    this._startLogPolling();
                    break;
                case 'refresh':
                    await this._fetchLogs();
                    break;
            }
        });

        // Cleanup on view disposal
        webviewView.onDidDispose(() => {
            this._stopLogPolling();
        });
    }

    private async _fetchLogs() {
        try {
            // Try to fetch logs from API first
            const baseUrl = this._apiClient.baseUrl;
            const response = await fetch(`${baseUrl}/logs?limit=100`);

            if (response.ok) {
                const data = await response.json() as { logs?: LogEntry[] };
                if (data.logs && Array.isArray(data.logs)) {
                    this._logs = data.logs;
                    this._updateWebview();
                    return;
                }
            }
        } catch {
            // API logs endpoint not available, try file-based logs
        }

        // Fall back to reading log file
        await this._readLogFile();
    }

    private async _readLogFile() {
        // Find workspace folder
        const workspaceFolders = vscode.workspace.workspaceFolders;
        if (!workspaceFolders || workspaceFolders.length === 0) {
            return;
        }

        const lokiDir = path.join(workspaceFolders[0].uri.fsPath, '.loki');
        const logFile = path.join(lokiDir, 'logs', 'session.log');

        try {
            if (!fs.existsSync(logFile)) {
                // Try alternative log location
                const altLogFile = path.join(lokiDir, 'session.log');
                if (fs.existsSync(altLogFile)) {
                    await this._parseLogFile(altLogFile);
                }
                return;
            }

            await this._parseLogFile(logFile);
        } catch (error) {
            logger.error('Error reading log file:', error);
        }
    }

    private async _parseLogFile(logFile: string) {
        try {
            // Use async file reading to avoid blocking
            const content = await fs.promises.readFile(logFile, 'utf-8');
            const lines = content.split('\n').filter(line => line.trim());

            // Parse last 200 lines
            const recentLines = lines.slice(-200);
            this._logs = recentLines.map(line => this._parseLogLine(line)).filter(Boolean) as LogEntry[];
            this._updateWebview();
        } catch (error) {
            logger.error('Error parsing log file:', error);
        }
    }

    /**
     * Validate and normalize log level
     */
    private _normalizeLogLevel(level: string): LogEntry['level'] {
        const validLevels: LogEntry['level'][] = ['debug', 'info', 'warn', 'error'];
        const normalized = level.toLowerCase();
        // Map common alternatives
        if (normalized === 'warning') return 'warn';
        if (normalized === 'trace') return 'debug';
        if (normalized === 'fatal' || normalized === 'critical') return 'error';
        return validLevels.includes(normalized as LogEntry['level'])
            ? normalized as LogEntry['level']
            : 'info';
    }

    private _parseLogLine(line: string): LogEntry | null {
        // Common log formats:
        // [2026-01-31 10:00:00] [INFO] Message here
        // 2026-01-31T10:00:00.000Z INFO Message here
        // [INFO] Message here

        try {
            // Format 1: [timestamp] [level] message
            const match1 = line.match(/^\[(\d{4}-\d{2}-\d{2}[T\s]\d{2}:\d{2}:\d{2}(?:\.\d+)?Z?)\]\s*\[(\w+)\]\s*(.*)$/);
            if (match1) {
                return {
                    timestamp: match1[1],
                    level: this._normalizeLogLevel(match1[2]),
                    message: match1[3]
                };
            }

            // Format 2: timestamp level message
            const match2 = line.match(/^(\d{4}-\d{2}-\d{2}[T\s]\d{2}:\d{2}:\d{2}(?:\.\d+)?Z?)\s+(\w+)\s+(.*)$/);
            if (match2) {
                return {
                    timestamp: match2[1],
                    level: this._normalizeLogLevel(match2[2]),
                    message: match2[3]
                };
            }

            // Format 3: [level] message (use current time)
            const match3 = line.match(/^\[(\w+)\]\s*(.*)$/);
            if (match3) {
                return {
                    timestamp: new Date().toISOString(),
                    level: this._normalizeLogLevel(match3[1]),
                    message: match3[2]
                };
            }

            // No match, treat as info message
            if (line.trim()) {
                return {
                    timestamp: new Date().toISOString(),
                    level: 'info',
                    message: line
                };
            }

            return null;
        } catch {
            return null;
        }
    }

    private _startLogPolling() {
        // Poll for new logs every 2 seconds
        this._pollingInterval = setInterval(async () => {
            await this._fetchLogs();
        }, 2000);
    }

    private _stopLogPolling() {
        if (this._pollingInterval) {
            clearInterval(this._pollingInterval);
            this._pollingInterval = undefined;
        }
    }

    public addLog(entry: LogEntry) {
        this._logs.push(entry);
        // Keep only last 500 logs
        if (this._logs.length > 500) {
            this._logs = this._logs.slice(-500);
        }
        this._updateWebview();
    }

    private _updateWebview() {
        if (this._view) {
            // Filter logs based on level
            const filteredLogs = this._filterLevel === 'all'
                ? this._logs
                : this._logs.filter(log => log.level === this._filterLevel);

            this._view.webview.postMessage({
                type: 'updateLogs',
                logs: filteredLogs.slice(-200), // Send last 200 filtered
                autoScroll: this._autoScroll,
                filterLevel: this._filterLevel
            });
        }
    }

    private _getHtmlForWebview(webview: vscode.Webview): string {
        const nonce = getNonce();

        return `<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <meta http-equiv="Content-Security-Policy" content="default-src 'none'; style-src ${webview.cspSource} 'unsafe-inline'; script-src 'nonce-${nonce}';">
    <title>Loki Logs</title>
    <style>
        * {
            box-sizing: border-box;
            margin: 0;
            padding: 0;
        }
        body {
            font-family: var(--vscode-editor-font-family, monospace);
            font-size: 12px;
            color: var(--vscode-foreground);
            background-color: var(--vscode-editor-background);
            height: 100vh;
            display: flex;
            flex-direction: column;
        }
        .toolbar {
            padding: 8px 12px;
            border-bottom: 1px solid var(--vscode-panel-border);
            display: flex;
            justify-content: space-between;
            align-items: center;
            gap: 8px;
            flex-shrink: 0;
            flex-wrap: wrap;
        }
        .toolbar-group {
            display: flex;
            gap: 8px;
            align-items: center;
        }
        .toolbar select {
            background: var(--vscode-dropdown-background);
            color: var(--vscode-dropdown-foreground);
            border: 1px solid var(--vscode-dropdown-border);
            padding: 4px 8px;
            border-radius: 4px;
            font-size: 11px;
        }
        .toolbar button {
            background: var(--vscode-button-secondaryBackground);
            color: var(--vscode-button-secondaryForeground);
            border: none;
            padding: 4px 8px;
            border-radius: 4px;
            cursor: pointer;
            font-size: 11px;
            display: flex;
            align-items: center;
            gap: 4px;
        }
        .toolbar button:hover {
            background: var(--vscode-button-secondaryHoverBackground);
        }
        .toolbar button.active {
            background: var(--vscode-button-background);
            color: var(--vscode-button-foreground);
        }
        .log-count {
            font-size: 11px;
            color: var(--vscode-descriptionForeground);
        }
        .logs {
            flex: 1;
            overflow-y: auto;
            padding: 8px 12px;
            font-family: var(--vscode-editor-font-family, 'Consolas', monospace);
        }
        .log-entry {
            padding: 4px 8px;
            border-radius: 3px;
            margin-bottom: 2px;
            display: flex;
            gap: 8px;
            line-height: 1.4;
        }
        .log-entry:hover {
            background: var(--vscode-list-hoverBackground);
        }
        .log-timestamp {
            color: var(--vscode-descriptionForeground);
            white-space: nowrap;
            font-size: 11px;
        }
        .log-level {
            font-weight: 600;
            text-transform: uppercase;
            font-size: 10px;
            padding: 1px 6px;
            border-radius: 3px;
            white-space: nowrap;
        }
        .log-level.debug {
            color: var(--vscode-debugIcon-pauseForeground);
            background: var(--vscode-debugIcon-pauseForeground);
            background-opacity: 0.1;
        }
        .log-level.info {
            color: var(--vscode-editorInfo-foreground);
            background: var(--vscode-editorInfo-background);
        }
        .log-level.warn {
            color: var(--vscode-editorWarning-foreground);
            background: var(--vscode-editorWarning-background);
        }
        .log-level.error {
            color: var(--vscode-editorError-foreground);
            background: var(--vscode-editorError-background);
        }
        .log-message {
            flex: 1;
            word-break: break-word;
        }
        .empty-state {
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            height: 100%;
            color: var(--vscode-descriptionForeground);
            text-align: center;
            padding: 20px;
        }
        .empty-state svg {
            width: 48px;
            height: 48px;
            margin-bottom: 16px;
            opacity: 0.5;
        }
    </style>
</head>
<body>
    <div class="toolbar">
        <div class="toolbar-group">
            <select id="levelFilter">
                <option value="all">All Levels</option>
                <option value="debug">Debug</option>
                <option value="info">Info</option>
                <option value="warn">Warning</option>
                <option value="error">Error</option>
            </select>
            <button id="refreshBtn" title="Refresh logs">Refresh</button>
            <button id="clearBtn" title="Clear logs">Clear</button>
        </div>
        <div class="toolbar-group">
            <button id="autoScrollBtn" class="active" title="Toggle auto-scroll">Auto-scroll</button>
            <span class="log-count" id="logCount">0 entries</span>
        </div>
    </div>
    <div class="logs" id="logs">
        <div class="empty-state">
            <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                <path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"></path>
                <polyline points="14 2 14 8 20 8"></polyline>
                <line x1="16" y1="13" x2="8" y2="13"></line>
                <line x1="16" y1="17" x2="8" y2="17"></line>
                <polyline points="10 9 9 9 8 9"></polyline>
            </svg>
            <p>No logs available</p>
            <p style="font-size: 11px; margin-top: 8px;">Logs will appear when Loki Mode is running</p>
        </div>
    </div>
    <script nonce="${nonce}">
        const vscode = acquireVsCodeApi();
        const logsContainer = document.getElementById('logs');
        const levelFilter = document.getElementById('levelFilter');
        const refreshBtn = document.getElementById('refreshBtn');
        const clearBtn = document.getElementById('clearBtn');
        const autoScrollBtn = document.getElementById('autoScrollBtn');
        const logCount = document.getElementById('logCount');

        let logs = [];
        let autoScroll = true;

        // Level filter change
        levelFilter.addEventListener('change', () => {
            vscode.postMessage({ type: 'setFilter', level: levelFilter.value });
        });

        // Refresh button
        refreshBtn.addEventListener('click', () => {
            vscode.postMessage({ type: 'refresh' });
        });

        // Clear button
        clearBtn.addEventListener('click', () => {
            vscode.postMessage({ type: 'clearLogs' });
        });

        // Auto-scroll toggle
        autoScrollBtn.addEventListener('click', () => {
            autoScroll = !autoScroll;
            autoScrollBtn.classList.toggle('active', autoScroll);
            vscode.postMessage({ type: 'toggleAutoScroll', enabled: autoScroll });
        });

        // Handle messages from extension
        window.addEventListener('message', event => {
            const data = event.data;
            switch (data.type) {
                case 'updateLogs':
                    logs = data.logs;
                    autoScroll = data.autoScroll;
                    levelFilter.value = data.filterLevel;
                    autoScrollBtn.classList.toggle('active', autoScroll);
                    renderLogs();
                    break;
            }
        });

        function renderLogs() {
            logCount.textContent = logs.length + ' entries';

            if (logs.length === 0) {
                logsContainer.innerHTML = \`
                    <div class="empty-state">
                        <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                            <path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"></path>
                            <polyline points="14 2 14 8 20 8"></polyline>
                            <line x1="16" y1="13" x2="8" y2="13"></line>
                            <line x1="16" y1="17" x2="8" y2="17"></line>
                            <polyline points="10 9 9 9 8 9"></polyline>
                        </svg>
                        <p>No logs available</p>
                        <p style="font-size: 11px; margin-top: 8px;">Logs will appear when Loki Mode is running</p>
                    </div>
                \`;
                return;
            }

            logsContainer.innerHTML = logs.map(log => {
                const time = formatTimestamp(log.timestamp);
                const message = escapeHtml(log.message);

                return \`
                    <div class="log-entry">
                        <span class="log-timestamp">\${time}</span>
                        <span class="log-level \${log.level}">\${log.level}</span>
                        <span class="log-message">\${message}</span>
                    </div>
                \`;
            }).join('');

            if (autoScroll) {
                logsContainer.scrollTop = logsContainer.scrollHeight;
            }
        }

        function formatTimestamp(ts) {
            try {
                const date = new Date(ts);
                return date.toLocaleTimeString();
            } catch {
                return ts;
            }
        }

        function escapeHtml(text) {
            const div = document.createElement('div');
            div.textContent = text;
            return div.innerHTML;
        }

        // Notify extension that webview is ready
        vscode.postMessage({ type: 'ready' });
    </script>
</body>
</html>`;
    }
}

/**
 * Memory View Provider
 * Provides a webview panel for viewing memory context, patterns, and token economics
 *
 * @deprecated This view is deprecated in favor of the Memory tab in the main dashboard.
 * Will be removed in v6.0.0. Use `loki.openDashboard` command with memory tab instead.
 * The dashboard provides a unified view with better integration of all Loki features.
 */

import * as vscode from 'vscode';
import { LokiApiClient } from '../api/client';
import { logger } from '../utils/logger';
import { getNonce } from '../utils/webview';

interface MemoryPattern {
    id: string;
    pattern: string;
    category: string;
    confidence: number;
}

interface MemoryEpisode {
    id: string;
    task_id: string;
    agent: string;
    goal: string;
    timestamp: string;
    outcome: string;
}

interface MemorySkill {
    id: string;
    name: string;
    description: string;
    success_rate: number;
}

interface TokenStats {
    discovery_tokens: number;
    read_tokens: number;
    total_tokens: number;
    savings_percent: number;
}

interface MemoryData {
    patterns: MemoryPattern[];
    episodes: MemoryEpisode[];
    skills: MemorySkill[];
    tokenStats: TokenStats;
    lastUpdated: Date;
}

/**
 * @deprecated This view is deprecated in favor of the Memory tab in the main dashboard.
 * Will be removed in v6.0.0. Use `loki.openDashboard` command with memory tab instead.
 */
export class MemoryViewProvider implements vscode.WebviewViewProvider, vscode.Disposable {
    public static readonly viewType = 'loki-memory';
    private static readonly REFRESH_INTERVAL = 10000;

    private _view?: vscode.WebviewView;
    private _memoryData: MemoryData = {
        patterns: [],
        episodes: [],
        skills: [],
        tokenStats: {
            discovery_tokens: 0,
            read_tokens: 0,
            total_tokens: 0,
            savings_percent: 0
        },
        lastUpdated: new Date()
    };
    private _refreshTimer?: ReturnType<typeof setInterval>;

    constructor(
        private readonly _extensionUri: vscode.Uri,
        private readonly _apiClient: LokiApiClient
    ) {
        console.warn('[DEPRECATED] MemoryViewProvider is deprecated. Use the Memory tab in the main dashboard instead. This view will be removed in v6.0.0.');
    }

    public dispose(): void {
        if (this._refreshTimer) {
            clearInterval(this._refreshTimer);
            this._refreshTimer = undefined;
        }
    }

    public resolveWebviewView(
        webviewView: vscode.WebviewView,
        _context: vscode.WebviewViewResolveContext,
        _token: vscode.CancellationToken
    ) {
        this._view = webviewView;

        webviewView.webview.options = {
            enableScripts: true,
            localResourceRoots: [this._extensionUri]
        };

        webviewView.webview.html = this._getHtmlForWebview(webviewView.webview);

        webviewView.webview.onDidReceiveMessage(async (data) => {
            switch (data.type) {
                case 'refresh':
                    await this._refreshMemoryData();
                    break;
                case 'ready':
                    await this._refreshMemoryData();
                    this._startAutoRefresh();
                    break;
                case 'viewPattern':
                    this._showPatternDetails(data.id);
                    break;
                case 'viewEpisode':
                    this._showEpisodeDetails(data.id);
                    break;
            }
        });

        webviewView.onDidChangeVisibility(() => {
            if (webviewView.visible) {
                this._refreshMemoryData();
                this._startAutoRefresh();
            } else {
                this._stopAutoRefresh();
            }
        });
    }

    private _startAutoRefresh(): void {
        if (this._refreshTimer) return;
        this._refreshTimer = setInterval(() => {
            this._refreshMemoryData();
        }, MemoryViewProvider.REFRESH_INTERVAL);
    }

    private _stopAutoRefresh(): void {
        if (this._refreshTimer) {
            clearInterval(this._refreshTimer);
            this._refreshTimer = undefined;
        }
    }

    private async _refreshMemoryData(): Promise<void> {
        try {
            const baseUrl = this._apiClient.baseUrl;

            const [patternsRes, episodesRes, skillsRes, economicsRes] = await Promise.allSettled([
                fetch(`${baseUrl}/api/memory/patterns`),
                fetch(`${baseUrl}/api/memory/episodes`),
                fetch(`${baseUrl}/api/memory/skills`),
                fetch(`${baseUrl}/api/memory/economics`)
            ]);

            if (patternsRes.status === 'fulfilled' && patternsRes.value.ok) {
                const data = await patternsRes.value.json() as { patterns?: MemoryPattern[] };
                this._memoryData.patterns = (data.patterns || []).slice(0, 10);
            }

            if (episodesRes.status === 'fulfilled' && episodesRes.value.ok) {
                const data = await episodesRes.value.json() as { episodes?: MemoryEpisode[] };
                this._memoryData.episodes = (data.episodes || []).slice(0, 5);
            }

            if (skillsRes.status === 'fulfilled' && skillsRes.value.ok) {
                const data = await skillsRes.value.json() as { skills?: MemorySkill[] };
                this._memoryData.skills = (data.skills || []).slice(0, 5);
            }

            if (economicsRes.status === 'fulfilled' && economicsRes.value.ok) {
                const data = await economicsRes.value.json() as TokenStats;
                this._memoryData.tokenStats = data;
            }

            this._memoryData.lastUpdated = new Date();
            this._updateWebview();

        } catch (error) {
            logger.debug('Memory refresh failed:', error);
        }
    }

    private _updateWebview(): void {
        if (this._view) {
            this._view.webview.postMessage({
                type: 'updateMemory',
                data: this._memoryData
            });
        }
    }

    private async _showPatternDetails(patternId: string): Promise<void> {
        try {
            const baseUrl = this._apiClient.baseUrl;
            const response = await fetch(`${baseUrl}/api/memory/patterns/${patternId}`);
            if (response.ok) {
                const pattern = await response.json();
                const content = JSON.stringify(pattern, null, 2);
                const doc = await vscode.workspace.openTextDocument({
                    content,
                    language: 'json'
                });
                await vscode.window.showTextDocument(doc, { preview: true });
            }
        } catch (error) {
            logger.error('Failed to fetch pattern details:', error);
        }
    }

    private async _showEpisodeDetails(episodeId: string): Promise<void> {
        try {
            const baseUrl = this._apiClient.baseUrl;
            const response = await fetch(`${baseUrl}/api/memory/episodes/${episodeId}`);
            if (response.ok) {
                const episode = await response.json();
                const content = JSON.stringify(episode, null, 2);
                const doc = await vscode.workspace.openTextDocument({
                    content,
                    language: 'json'
                });
                await vscode.window.showTextDocument(doc, { preview: true });
            }
        } catch (error) {
            logger.error('Failed to fetch episode details:', error);
        }
    }

    private _getHtmlForWebview(webview: vscode.Webview): string {
        const nonce = getNonce();

        return `<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <meta http-equiv="Content-Security-Policy" content="default-src 'none'; style-src ${webview.cspSource} 'unsafe-inline'; script-src 'nonce-${nonce}';">
    <title>Loki Memory</title>
    <style>
        * { box-sizing: border-box; margin: 0; padding: 0; }
        body { font-family: var(--vscode-font-family); font-size: var(--vscode-font-size); color: var(--vscode-foreground); background-color: var(--vscode-editor-background); padding: 12px; }
        .header { display: flex; justify-content: space-between; align-items: center; margin-bottom: 16px; }
        .header h2 { font-size: 14px; font-weight: 600; }
        .refresh-btn { background: var(--vscode-button-secondaryBackground); color: var(--vscode-button-secondaryForeground); border: none; padding: 4px 8px; border-radius: 4px; cursor: pointer; font-size: 12px; }
        .refresh-btn:hover { background: var(--vscode-button-secondaryHoverBackground); }
        .section { margin-bottom: 20px; }
        .section-title { font-size: 12px; font-weight: 600; color: var(--vscode-descriptionForeground); text-transform: uppercase; letter-spacing: 0.5px; margin-bottom: 8px; display: flex; align-items: center; gap: 6px; }
        .section-title .count { background: var(--vscode-badge-background); color: var(--vscode-badge-foreground); padding: 1px 6px; border-radius: 10px; font-size: 10px; }
        .card { background: var(--vscode-editor-inactiveSelectionBackground); border-radius: 6px; padding: 10px 12px; margin-bottom: 8px; cursor: pointer; transition: background 0.15s; }
        .card:hover { background: var(--vscode-list-hoverBackground); }
        .card-title { font-weight: 500; margin-bottom: 4px; display: flex; justify-content: space-between; align-items: center; }
        .card-meta { font-size: 11px; color: var(--vscode-descriptionForeground); }
        .confidence { font-size: 11px; padding: 2px 6px; border-radius: 4px; background: var(--vscode-badge-background); color: var(--vscode-badge-foreground); }
        .confidence.high { background: var(--vscode-testing-iconPassed); color: white; }
        .confidence.medium { background: var(--vscode-editorWarning-foreground); color: white; }
        .token-stats { display: grid; grid-template-columns: repeat(2, 1fr); gap: 8px; }
        .stat-card { background: var(--vscode-editor-inactiveSelectionBackground); border-radius: 6px; padding: 12px; text-align: center; }
        .stat-value { font-size: 18px; font-weight: 600; color: var(--vscode-foreground); }
        .stat-label { font-size: 10px; color: var(--vscode-descriptionForeground); text-transform: uppercase; margin-top: 4px; }
        .savings { color: var(--vscode-testing-iconPassed); }
        .empty-state { text-align: center; padding: 20px; color: var(--vscode-descriptionForeground); }
        .last-updated { font-size: 10px; color: var(--vscode-descriptionForeground); text-align: center; margin-top: 16px; }
        .outcome-success { color: var(--vscode-testing-iconPassed); }
        .outcome-failure { color: var(--vscode-testing-iconFailed); }
    </style>
</head>
<body>
    <div class="header"><h2>Memory Context</h2><button class="refresh-btn" id="refreshBtn">Refresh</button></div>
    <div class="section"><div class="section-title">Token Economics</div><div class="token-stats" id="tokenStats"><div class="stat-card"><div class="stat-value" id="totalTokens">-</div><div class="stat-label">Total Tokens</div></div><div class="stat-card"><div class="stat-value savings" id="savings">-</div><div class="stat-label">Savings</div></div></div></div>
    <div class="section"><div class="section-title">Patterns <span class="count" id="patternCount">0</span></div><div id="patterns"><div class="empty-state">No patterns learned yet</div></div></div>
    <div class="section"><div class="section-title">Recent Episodes <span class="count" id="episodeCount">0</span></div><div id="episodes"><div class="empty-state">No episodes recorded</div></div></div>
    <div class="section"><div class="section-title">Skills <span class="count" id="skillCount">0</span></div><div id="skills"><div class="empty-state">No skills learned</div></div></div>
    <div class="last-updated" id="lastUpdated">-</div>
    <script nonce="${nonce}">
        const vscode = acquireVsCodeApi();
        document.getElementById('refreshBtn').addEventListener('click', () => { vscode.postMessage({ type: 'refresh' }); });
        window.addEventListener('message', event => { if (event.data.type === 'updateMemory') updateUI(event.data.data); });
        function updateUI(data) {
            document.getElementById('totalTokens').textContent = formatNumber(data.tokenStats.total_tokens || 0);
            document.getElementById('savings').textContent = (data.tokenStats.savings_percent || 0).toFixed(1) + '%';
            document.getElementById('patternCount').textContent = data.patterns.length;
            const patternsEl = document.getElementById('patterns');
            patternsEl.innerHTML = data.patterns.length === 0 ? '<div class="empty-state">No patterns learned yet</div>' : data.patterns.map(p => '<div class="card" onclick="viewPattern(\\'' + escapeAttr(p.id) + '\\')"><div class="card-title"><span>' + escapeHtml(truncate(p.pattern, 50)) + '</span><span class="confidence ' + (p.confidence > 0.8 ? 'high' : p.confidence > 0.5 ? 'medium' : '') + '">' + (p.confidence * 100).toFixed(0) + '%</span></div><div class="card-meta">' + escapeHtml(p.category) + '</div></div>').join('');
            document.getElementById('episodeCount').textContent = data.episodes.length;
            const episodesEl = document.getElementById('episodes');
            episodesEl.innerHTML = data.episodes.length === 0 ? '<div class="empty-state">No episodes recorded</div>' : data.episodes.map(e => '<div class="card" onclick="viewEpisode(\\'' + escapeAttr(e.id) + '\\')"><div class="card-title"><span>' + escapeHtml(truncate(e.goal, 40)) + '</span><span class="' + (e.outcome === 'success' ? 'outcome-success' : 'outcome-failure') + '">' + escapeHtml(e.outcome) + '</span></div><div class="card-meta">' + escapeHtml(e.agent) + ' - ' + formatDate(e.timestamp) + '</div></div>').join('');
            document.getElementById('skillCount').textContent = data.skills.length;
            const skillsEl = document.getElementById('skills');
            skillsEl.innerHTML = data.skills.length === 0 ? '<div class="empty-state">No skills learned</div>' : data.skills.map(s => '<div class="card"><div class="card-title"><span>' + escapeHtml(s.name) + '</span><span class="confidence">' + (s.success_rate * 100).toFixed(0) + '%</span></div><div class="card-meta">' + escapeHtml(truncate(s.description, 60)) + '</div></div>').join('');
            document.getElementById('lastUpdated').textContent = 'Updated: ' + new Date(data.lastUpdated).toLocaleTimeString();
        }
        function viewPattern(id) { vscode.postMessage({ type: 'viewPattern', id: id }); }
        function viewEpisode(id) { vscode.postMessage({ type: 'viewEpisode', id: id }); }
        function escapeHtml(text) { const div = document.createElement('div'); div.textContent = text || ''; return div.innerHTML; }
        function escapeAttr(text) { return (text || '').replace(/'/g, "\\\\'").replace(/"/g, '\\\\"'); }
        function truncate(text, len) { return !text ? '' : text.length > len ? text.substring(0, len) + '...' : text; }
        function formatNumber(n) { return n >= 1000000 ? (n / 1000000).toFixed(1) + 'M' : n >= 1000 ? (n / 1000).toFixed(1) + 'K' : n.toString(); }
        function formatDate(d) { return !d ? '-' : new Date(d).toLocaleDateString() + ' ' + new Date(d).toLocaleTimeString(); }
        vscode.postMessage({ type: 'ready' });
    </script>
</body>
</html>`;
    }
}

import * as vscode from 'vscode';

/**
 * Status states for the Loki Mode status bar
 */
export type StatusState = 'idle' | 'running' | 'paused' | 'error';

/**
 * Configuration for status bar display
 */
interface StatusConfig {
    text: string;
    tooltip: string;
    icon: string;
    color?: string;
    backgroundColor?: string;
}

/**
 * Manages the Loki Mode status bar item
 * Shows current session state and provides quick actions
 */
export class StatusBarManager {
    private statusBarItem: vscode.StatusBarItem;
    private state: StatusState = 'idle';
    private currentPhase: string = '';
    private completedTasks: number = 0;
    private totalTasks: number = 0;
    private provider: string = 'claude';

    constructor() {
        // Create status bar item on the left side with high priority
        this.statusBarItem = vscode.window.createStatusBarItem(
            vscode.StatusBarAlignment.Left,
            100
        );

        // Set command to open quick pick menu
        this.statusBarItem.command = 'loki.showQuickPick';

        // Initialize with idle state
        this.updateDisplay();
        this.statusBarItem.show();
    }

    /**
     * Set the current state of the status bar
     */
    setState(state: StatusState): void {
        this.state = state;
        this.updateDisplay();
    }

    /**
     * Update the current phase
     */
    setPhase(phase: string): void {
        this.currentPhase = phase;
        this.updateDisplay();
    }

    /**
     * Update task counts
     */
    setTaskCounts(completed: number, total: number): void {
        this.completedTasks = completed;
        this.totalTasks = total;
        this.updateDisplay();
    }

    /**
     * Set the current provider
     */
    setProvider(provider: string): void {
        this.provider = provider;
        this.updateDisplay();
    }

    /**
     * Update all status information at once
     */
    updateStatus(options: {
        state?: StatusState;
        phase?: string;
        completedTasks?: number;
        totalTasks?: number;
        provider?: string;
    }): void {
        if (options.state !== undefined) {
            this.state = options.state;
        }
        if (options.phase !== undefined) {
            this.currentPhase = options.phase;
        }
        if (options.completedTasks !== undefined) {
            this.completedTasks = options.completedTasks;
        }
        if (options.totalTasks !== undefined) {
            this.totalTasks = options.totalTasks;
        }
        if (options.provider !== undefined) {
            this.provider = options.provider;
        }
        this.updateDisplay();
    }

    /**
     * Get the current state
     */
    getState(): StatusState {
        return this.state;
    }

    /**
     * Show the status bar item
     */
    show(): void {
        this.statusBarItem.show();
    }

    /**
     * Hide the status bar item
     */
    hide(): void {
        this.statusBarItem.hide();
    }

    /**
     * Dispose of the status bar item
     */
    dispose(): void {
        this.statusBarItem.dispose();
    }

    private updateDisplay(): void {
        const config = this.getStatusConfig();

        this.statusBarItem.text = config.text;
        this.statusBarItem.tooltip = this.buildTooltip(config.tooltip);

        if (config.color) {
            this.statusBarItem.color = new vscode.ThemeColor(config.color);
        } else {
            this.statusBarItem.color = undefined;
        }

        if (config.backgroundColor) {
            this.statusBarItem.backgroundColor = new vscode.ThemeColor(config.backgroundColor);
        } else {
            this.statusBarItem.backgroundColor = undefined;
        }
    }

    private getStatusConfig(): StatusConfig {
        switch (this.state) {
            case 'running':
                return {
                    text: this.buildRunningText(),
                    tooltip: 'Loki Mode is running',
                    icon: '$(sync~spin)',
                    color: 'statusBarItem.warningForeground',
                    backgroundColor: 'statusBarItem.warningBackground'
                };

            case 'paused':
                return {
                    text: '$(debug-pause) Loki: Paused',
                    tooltip: 'Loki Mode is paused',
                    icon: '$(debug-pause)',
                    color: 'statusBarItem.warningForeground'
                };

            case 'error':
                return {
                    text: '$(error) Loki: Error',
                    tooltip: 'Loki Mode encountered an error',
                    icon: '$(error)',
                    color: 'statusBarItem.errorForeground',
                    backgroundColor: 'statusBarItem.errorBackground'
                };

            case 'idle':
            default:
                return {
                    text: '$(rocket) Loki Mode',
                    tooltip: 'Click to start Loki Mode',
                    icon: '$(rocket)'
                };
        }
    }

    private buildRunningText(): string {
        const parts: string[] = ['$(sync~spin) Loki'];

        // Add phase if available
        if (this.currentPhase) {
            parts.push(`: ${this.shortenPhase(this.currentPhase)}`);
        }

        // Add task count if available
        if (this.totalTasks > 0) {
            parts.push(` (${this.completedTasks}/${this.totalTasks})`);
        }

        return parts.join('');
    }

    private shortenPhase(phase: string): string {
        // Shorten long phase names for status bar
        const maxLength = 15;
        if (phase.length > maxLength) {
            return phase.substring(0, maxLength - 3) + '...';
        }
        return phase;
    }

    private buildTooltip(_baseTooltip: string): vscode.MarkdownString {
        const md = new vscode.MarkdownString();
        md.isTrusted = true;

        md.appendMarkdown(`**Loki Mode**\n\n`);
        md.appendMarkdown(`Status: ${this.getStatusText()}\n\n`);

        if (this.state !== 'idle') {
            md.appendMarkdown(`Provider: ${this.formatProvider()}\n\n`);

            if (this.currentPhase) {
                md.appendMarkdown(`Phase: ${this.currentPhase}\n\n`);
            }

            if (this.totalTasks > 0) {
                const progress = Math.round((this.completedTasks / this.totalTasks) * 100);
                md.appendMarkdown(`Progress: ${this.completedTasks}/${this.totalTasks} tasks (${progress}%)\n\n`);
            }
        }

        md.appendMarkdown(`---\n\n`);
        md.appendMarkdown(`Click for actions menu`);

        return md;
    }

    private getStatusText(): string {
        switch (this.state) {
            case 'running':
                return 'Running';
            case 'paused':
                return 'Paused';
            case 'error':
                return 'Error';
            case 'idle':
            default:
                return 'Idle';
        }
    }

    private formatProvider(): string {
        switch (this.provider) {
            case 'claude':
                return 'Claude Code';
            case 'codex':
                return 'OpenAI Codex';
            case 'gemini':
                return 'Google Gemini';
            default:
                return this.provider;
        }
    }
}

/**
 * Show the quick pick menu for Loki Mode actions
 */
export async function showQuickPickMenu(statusManager: StatusBarManager): Promise<string | undefined> {
    const state = statusManager.getState();
    const items: vscode.QuickPickItem[] = [];

    if (state === 'idle') {
        items.push({
            label: '$(rocket) Start Session',
            description: 'Start a new Loki Mode session',
            detail: 'Select a PRD file to begin autonomous development'
        });
    }

    if (state === 'running') {
        items.push({
            label: '$(debug-pause) Pause Session',
            description: 'Pause the current session',
            detail: 'Temporarily halt execution'
        });
    }

    if (state === 'paused') {
        items.push({
            label: '$(debug-continue) Resume Session',
            description: 'Resume the paused session',
            detail: 'Continue from where you left off'
        });
    }

    if (state !== 'idle') {
        items.push({
            label: '$(debug-stop) Stop Session',
            description: 'Stop the current session',
            detail: 'End the session completely'
        });

        items.push({
            label: '$(edit) Inject Input',
            description: 'Send human input to the session',
            detail: 'Provide guidance or corrections'
        });
    }

    items.push({
        label: '$(refresh) Refresh Status',
        description: 'Refresh task and session status',
        detail: 'Sync with the latest state'
    });

    items.push({
        label: '$(info) Show Status',
        description: 'Show detailed status notification',
        detail: 'View current session information'
    });

    const selected = await vscode.window.showQuickPick(items, {
        placeHolder: 'Select an action',
        title: 'Loki Mode Actions'
    });

    if (!selected) {
        return undefined;
    }

    // Return the command to execute based on selection
    if (selected.label.includes('Start')) {
        return 'loki.start';
    } else if (selected.label.includes('Pause')) {
        return 'loki.pause';
    } else if (selected.label.includes('Resume')) {
        return 'loki.resume';
    } else if (selected.label.includes('Stop')) {
        return 'loki.stop';
    } else if (selected.label.includes('Inject')) {
        return 'loki.injectInput';
    } else if (selected.label.includes('Refresh')) {
        return 'loki.refreshTasks';
    } else if (selected.label.includes('Status')) {
        return 'loki.status';
    }

    return undefined;
}

/**
 * Test runner for VS Code extension tests
 * Can run outside of VS Code for unit tests
 */

import * as path from 'path';
import * as fs from 'fs';

// Simple test framework for running tests outside VS Code
interface TestCase {
    name: string;
    fn: () => void | Promise<void>;
}

interface TestSuite {
    name: string;
    tests: TestCase[];
}

const suites: TestSuite[] = [];
let currentSuite: TestSuite | null = null;

// Test DSL functions
function describe(name: string, fn: () => void): void {
    const suite: TestSuite = { name, tests: [] };
    suites.push(suite);
    const previousSuite = currentSuite;
    currentSuite = suite;
    fn();
    currentSuite = previousSuite;
}

function it(name: string, fn: () => void | Promise<void>): void {
    if (currentSuite) {
        currentSuite.tests.push({ name, fn });
    }
}

// Basic assertion library
const assert = {
    ok(value: unknown, message?: string): void {
        if (!value) {
            throw new Error(message || `Expected truthy value but got ${value}`);
        }
    },
    strictEqual<T>(actual: T, expected: T, message?: string): void {
        if (actual !== expected) {
            throw new Error(message || `Expected ${expected} but got ${actual}`);
        }
    },
    deepStrictEqual<T>(actual: T, expected: T, message?: string): void {
        if (JSON.stringify(actual) !== JSON.stringify(expected)) {
            throw new Error(message || `Expected ${JSON.stringify(expected)} but got ${JSON.stringify(actual)}`);
        }
    }
};

// Make test DSL available globally
(global as Record<string, unknown>).describe = describe;
(global as Record<string, unknown>).it = it;
(global as Record<string, unknown>).assert = assert;

async function runTests(): Promise<void> {
    console.log('Running Loki Mode VS Code Extension Tests\n');
    console.log('='.repeat(50));

    // Import test files
    const testDir = path.join(__dirname, 'suite');
    if (fs.existsSync(testDir)) {
        const testFiles = fs.readdirSync(testDir).filter(f => f.endsWith('.test.ts') || f.endsWith('.test.js'));

        for (const file of testFiles) {
            try {
                // Clear require cache for fresh import
                const testPath = path.join(testDir, file);
                delete require.cache[require.resolve(testPath)];
                require(testPath);
            } catch (e) {
                console.error(`Failed to load test file ${file}:`, e);
            }
        }
    }

    let totalPassed = 0;
    let totalFailed = 0;

    for (const suite of suites) {
        console.log(`\n${suite.name}`);

        for (const test of suite.tests) {
            try {
                await test.fn();
                console.log(`  [PASS] ${test.name}`);
                totalPassed++;
            } catch (e) {
                const error = e instanceof Error ? e.message : String(e);
                console.log(`  [FAIL] ${test.name}`);
                console.log(`         ${error}`);
                totalFailed++;
            }
        }
    }

    console.log('\n' + '='.repeat(50));
    console.log(`Results: ${totalPassed} passed, ${totalFailed} failed`);

    if (totalFailed > 0) {
        process.exit(1);
    }
}

// Run tests
runTests().catch(err => {
    console.error('Test runner failed:', err);
    process.exit(1);
});

/**
 * Tests for DashboardWebviewProvider
 * Tests the VS Code webview integration for the Loki Mode dashboard
 */

import * as assert from 'assert';

// Mock VS Code API types for testing outside VS Code
interface MockWebview {
    options: { enableScripts: boolean; localResourceRoots: unknown[] };
    html: string;
    postMessage: (message: unknown) => boolean;
    onDidReceiveMessage: (callback: (message: unknown) => void) => { dispose: () => void };
    cspSource: string;
    asWebviewUri: (uri: unknown) => { toString: () => string };
}

interface MockWebviewView {
    webview: MockWebview;
    visible: boolean;
    onDidChangeVisibility: (callback: () => void) => { dispose: () => void };
    onDidDispose: (callback: () => void) => void;
}

// Test utilities
function createMockWebviewView(): MockWebviewView {
    const messageListeners: ((message: unknown) => void)[] = [];
    const visibilityListeners: (() => void)[] = [];

    return {
        webview: {
            options: { enableScripts: false, localResourceRoots: [] },
            html: '',
            postMessage: () => true,
            onDidReceiveMessage: (callback) => {
                messageListeners.push(callback);
                return { dispose: () => {} };
            },
            cspSource: 'test-csp-source',
            asWebviewUri: () => ({ toString: () => 'test-uri' })
        },
        visible: true,
        onDidChangeVisibility: (callback) => {
            visibilityListeners.push(callback);
            return { dispose: () => {} };
        },
        onDidDispose: () => {}
    };
}

// Test suite
